input.content:
// The log. Append-only, on-device. Packets go in; nothing is ever edited or deleted.
// Envelope: { id, hash, kind, observed_at, origin, loc, payload, links }
// `kind` is a sensory modality (image/audio/text/location), never a business meaning.

const DB_NAME = "packet-log";

let dbPromise = null;

function db() {
  if (!dbPromise) {
    dbPromise = new Promise((resolve, reject) => {
      const req = indexedDB.open(DB_NAME, 1);
      req.onupgradeneeded = () => {
        const d = req.result;
        d.createObjectStore("packets", { keyPath: "seq", autoIncrement: true })
          .createIndex("by_id", "id", { unique: true });
        d.createObjectStore("blobs"); // key = content hash (or packet id when hashing is unavailable)
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  }
  return dbPromise;
}

export function deviceId() {
  let id = localStorage.getItem("device-id");
  if (!id) {
    id = uuid();
    localStorage.setItem("device-id", id);
  }
  return id;
}

export async function appendPacket({ kind, payload = {}, blob = null, links = [], observedAt = null, loc = null }) {
  const bytes = blob
    ? new Uint8Array(await blob.arrayBuffer())
    : new TextEncoder().encode(JSON.stringify(payload));
  const hash = await sha256(bytes);

  const packet = {
    id: uuid(),
    hash,
    kind,
    observed_at: observedAt ?? new Date().toISOString(),
    origin: { device: deviceId() },
    loc,
    payload,
    links,
  };
  if (blob) packet.payload = { ...payload, blob: hash ?? packet.id };

  const d = await db();
  await new Promise((resolve, reject) => {
    const t = d.transaction(["packets", "blobs"], "readwrite");
    const add = t.objectStore("packets").add(packet);
    add.onsuccess = () => { packet.seq = add.result; };
    if (blob) t.objectStore("blobs").put(blob, packet.payload.blob);
    t.oncomplete = resolve;
    t.onerror = () => reject(t.error);
    t.onabort = () => reject(t.error);
  });

  window.dispatchEvent(new CustomEvent("packet-appended", { detail: packet }));
  return packet;
}

export async function listPackets() {
  const d = await db();
  return new Promise((resolve, reject) => {
    const req = d.transaction("packets").objectStore("packets").getAll();
    req.onsuccess = () => resolve(req.result.reverse());
    req.onerror = () => reject(req.error);
  });
}

export async function packetCount() {
  const d = await db();
  return new Promise((resolve, reject) => {
    const req = d.transaction("packets").objectStore("packets").count();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

export async function getBlob(key) {
  const d = await db();
  return new Promise((resolve, reject) => {
    const req = d.transaction("blobs").objectStore("blobs").get(key);
    req.onsuccess = () => resolve(req.result ?? null);
    req.onerror = () => reject(req.error);
  });
}

export async function exportLog() {
  const packets = await listPackets();
  return packets.reverse().map((p) => JSON.stringify(p)).join("\n");
}

async function sha256(bytes) {
  // crypto.subtle only exists in secure contexts; plain-http dev falls back to id-keyed blobs
  if (!crypto.subtle) return null;
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

function uuid() {
  if (crypto.randomUUID) return crypto.randomUUID();
  const b = crypto.getRandomValues(new Uint8Array(16));
  b[6] = (b[6] & 0x0f) | 0x40;
  b[8] = (b[8] & 0x3f) | 0x80;
  const h = [...b].map((x) => x.toString(16).padStart(2, "0")).join("");
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
}

