-- The lake, v0. One append-only table holding every observer's queue.
-- Same doctrine as the device log: INSERT and SELECT policies only — no
-- update, no delete. The device holds a window; the lake holds forever.
-- The membrane is wide open (anon) for the two-phone experiment; tightening
-- it is a policy change, never a schema change.

create table public.packet (
  seq         bigserial primary key,
  id          uuid not null unique,
  hash        text,
  kind        text not null,
  observed_at timestamptz not null,
  received_at timestamptz not null default now(),
  observer    text not null,
  loc         jsonb,
  payload     jsonb not null default '{}'::jsonb,
  links       jsonb not null default '[]'::jsonb
);

-- an OQ is a partition: one observer's packets in arrival order
create index packet_observer_idx on public.packet (observer, seq desc);

alter table public.packet enable row level security;

create policy "append packets" on public.packet
  for insert to anon, authenticated with check (true);

create policy "read packets" on public.packet
  for select to anon, authenticated using (true);

-- Blobs: public bucket, content-addressed by sha256 (same keys as the device)
insert into storage.buckets (id, name, public) values ('blobs', 'blobs', true);

create policy "upload blobs" on storage.objects
  for insert to anon, authenticated with check (bucket_id = 'blobs');

create policy "read blobs" on storage.objects
  for select to anon, authenticated using (bucket_id = 'blobs');

