// The lake. Cloud-canonical home of every observer's queue. The device drains
// its outbox upward in the background and keeps a local window; the lake keeps
// forever. Plain fetch against PostgREST + storage — no client library.
// The anon key grants append + read only; the lake has no update or delete path.

import { listPackets, listOutbox, removeFromOutbox, getBlob, backfillOutbox } from "./log.js";

export const LAKE_URL = "https://.supabase.co";
const LAKE_KEY = "";

const HEADERS = { apikey: LAKE_KEY, Authorization: `Bearer ${LAKE_KEY}` };

let draining = false;

export async function drain() {
  if (draining || !navigator.onLine) return;
  draining = true;
  try {
    await backfillOutbox();
    const pending = await listOutbox();
    if (!pending.length) return;
    const byId = new Map((await listPackets()).map((p) => [p.id, p]));
    for (const { id } of pending) {
      const p = byId.get(id);
      if (!p) { await removeFromOutbox(id); continue; }
      await pushBlob(p);
      await pushEnvelope(p);
      await removeFromOutbox(id);
      window.dispatchEvent(new CustomEvent("packet-synced", { detail: { id } }));
    }
  } catch {
    // whatever didn't make it stays in the outbox; the next drain retries
  } finally {
    draining = false;
  }
}

async function pushBlob(p) {
  const key = p.payload?.blob;
  if (!key) return;
  const blob = await getBlob(key);
  if (!blob) return;
  const res = await fetch(`${LAKE_URL}/storage/v1/object/blobs/${key}`, {
    method: "POST",
    headers: { ...HEADERS, "Content-Type": blob.type || "application/octet-stream", "x-upsert": "true" },
    body: blob,
  });
  if (!res.ok && res.status !== 409) throw new Error(`blob ${res.status}`);
}

async function pushEnvelope(p) {
  const res = await fetch(`${LAKE_URL}/rest/v1/packet?on_conflict=id`, {
    method: "POST",
    headers: { ...HEADERS, "Content-Type": "application/json", Prefer: "resolution=ignore-duplicates" },
    body: JSON.stringify({
      id: p.id,
      hash: p.hash,
      kind: p.kind,
      observed_at: p.observed_at,
      observer: p.origin?.device ?? "unknown",
      loc: p.loc,
      payload: p.payload,
      links: p.links,
    }),
  });
  if (!res.ok) throw new Error(`packet ${res.status}`);
}

export async function fetchLake(limit = 200) {
  const res = await fetch(
    `${LAKE_URL}/rest/v1/packet?select=*&order=seq.desc&limit=${limit}`,
    { headers: HEADERS }
  );
  if (!res.ok) throw new Error(`lake ${res.status}`);
