// The lens. Renders packets; never writes them. Display is lens-side —
// the payload says what was observed, the lens decides how it looks.
// Two views: the OQ (this device's log) and the Lake (every observer's queue).

import { getBlob, listPackets, pendingIds } from "./log.js";
import { fetchLake, remoteBlobUrl } from "./lake.js";

const KINDS = {
  text: { color: "var(--amber)", title: (p) => firstLine(p.payload.body) || "Note" },
  image: { color: "var(--blue)", title: () => "Photo" },
  audio: { color: "var(--green)", title: (p) => `Audio · ${mmss(p.payload.duration_ms)}` },
  location: { color: "var(--teal)", title: () => "Location" },
};
const FALLBACK = { color: "var(--purple)", title: (p) => p.kind };

const blobUrls = new Map();

// a row flips to "in lake" the moment its packet drains
window.addEventListener("packet-synced", (e) => {
  document.querySelectorAll(`li[data-id="${e.detail.id}"] .place`).forEach((el) => {
    el.textContent = "in lake";
    el.classList.remove("place--pending");
  });
});

export async function renderQueue(listEl) {
  const [packets, pending] = await Promise.all([listPackets(), pendingIds()]);
  listEl.textContent = "";
  for (const p of packets) listEl.append(buildRow(p, { pending: pending.has(p.id) }));
}

export function prependPacket(listEl, packet) {
  const row = buildRow(packet, { pending: true });
  row.classList.add("new");
  listEl.prepend(row);
}

export async function renderLake(listEl) {
  const packets = await fetchLake();
  listEl.textContent = "";
  for (const p of packets) listEl.append(buildRow(p, { showObserver: true }));
}

function buildRow(p, { pending = false, showObserver = false } = {}) {
  const kind = KINDS[p.kind] ?? FALLBACK;
  const li = document.createElement("li");
  li.dataset.id = p.id;

  const row = document.createElement("div");
  row.className = "row";

  const bar = document.createElement("div");
  bar.className = "bar";
  bar.style.background = kind.color;

  const main = document.createElement("div");
  main.className = "row-main";

  const title = document.createElement("div");
  title.className = "row-title";
  title.textContent = kind.title(p);

  const meta = document.createElement("div");
  meta.className = "row-meta";
  const place = document.createElement("span");
  place.className = pending ? "place place--pending" : "place";
  place.textContent = pending ? "on device" : "in lake";
  const when = document.createElement("span");
  when.textContent = formatWhen(p.observed_at);
  meta.append(place, when);
  if (showObserver) {
    const obs = document.createElement("span");
    obs.className = "obs";
    obs.textContent = `obs ${String(p.observer ?? p.origin?.device ?? "?").slice(0, 4)}`;
    meta.append(obs);
  }
  if (p.loc) {
    const coords = document.createElement("span");
    coords.textContent = `${p.loc.lat}, ${p.loc.lng}`;
    meta.append(coords);
  }

  main.append(title, meta);
  row.append(bar, main, chevron());
  li.append(row);

  row.addEventListener("click", () => toggleDetail(li, p));
  return li;
}

async function toggleDetail(li, p) {
  const open = li.classList.toggle("open");
  let detail = li.querySelector(".detail");
  if (!detail) {
    detail = document.createElement("div");
    detail.className = "detail";
    li.append(detail);
    await fillDetail(detail, p);
  }
  detail.style.display = open ? "block" : "none";
}

async function fillDetail(detail, p) {
  if (p.kind === "text") {
    const body = document.createElement("div");
    body.className = "body";
    body.textContent = p.payload.body;
    detail.append(body);
  } else if (p.kind === "image") {
    const img = document.createElement("img");
    img.src = await blobUrl(p.payload.blob);
    detail.append(img);
  } else if (p.kind === "audio") {
    const audio = document.createElement("audio");
    audio.controls = true;
    audio.src = await blobUrl(p.payload.blob);
    detail.append(audio);
  } else if (p.kind === "location") {
    const a = document.createElement("a");
    a.href = `https://maps.apple.com/?ll=${p.payload.lat},${p.payload.lng}`;
    a.target = "_blank";
    a.rel = "noopener";
    a.textContent = `${p.payload.lat}, ${p.payload.lng} · ±${p.payload.accuracy_m}m — open in Maps`;
    detail.append(a);
  } else {
    const body = document.createElement("div");
    body.className = "body";
    body.textContent = JSON.stringify(p.payload, null, 2);
    detail.append(body);
  }
}

// local blob first; another observer's media streams from the lake
async function blobUrl(key) {
  if (!blobUrls.has(key)) {
    const blob = await getBlob(key);
    blobUrls.set(key, blob ? URL.createObjectURL(blob) : remoteBlobUrl(key));
  }
  return blobUrls.get(key);
}

function firstLine(s = "") {
  const line = s.split("\n")[0].trim();
  return line.length > 48 ? line.slice(0, 48) + "…" : line;
}

function mmss(ms = 0) {
  const s = Math.round(ms / 1000);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}

function formatWhen(iso) {
  const d = new Date(iso);
  const day = d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
  const time = d.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
  return `${day} at ${time}`;
}

function chevron() {
  const span = document.createElement("span");
  span.className = "chev";
  span.innerHTML =
    '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>';
  return span;
}

