import { deviceId, packetCount, exportLog } from "./log.js";
import * as receptors from "./receptors.js";
import { renderQueue, prependPacket, renderLake } from "./lens.js";
import { startDraining } from "./lake.js";

const $ = (id) => document.getElementById(id);

// --- boot
renderQueue($("queue")).then(updateSub);
if ("serviceWorker" in navigator) navigator.serviceWorker.register("sw.js").catch(() => {});
navigator.storage?.persist?.().catch(() => {});
startDraining();

window.addEventListener("packet-appended", (e) => {
  if (view === "oq") prependPacket($("queue"), e.detail);
  updateSub();
});

async function updateSub() {
  if (view !== "oq") return;
  const n = await packetCount();
  $("sub").textContent = `local log · ${n} packet${n === 1 ? "" : "s"}`;
  $("empty").hidden = n > 0;
}

// --- views: OQ (this device) / Lake (every observer)
let view = "oq";
let lakePoll = null;

$("view-oq").addEventListener("click", () => switchView("oq"));
$("view-lake").addEventListener("click", () => switchView("lake"));

async function switchView(v) {
  if (v === view) return;
  view = v;
  $("view-oq").classList.toggle("active", v === "oq");
  $("view-lake").classList.toggle("active", v === "lake");
  clearInterval(lakePoll);
  $("empty").hidden = true;
  if (v === "oq") {
    await renderQueue($("queue"));
    updateSub();
  } else {
    $("sub").textContent = "the lake · every observer";
    const refresh = () => renderLake($("queue")).catch(() => {});
    await refresh();
    lakePoll = setInterval(refresh, 10_000);
  }
}

// --- audio
let rec = null;
let recTimer = null;
$("btn-mic").addEventListener("click", async () => {
  if (rec) {
    const r = rec;
    rec = null;
    setRecordingUi(false, 0);
    await r.stop();
  } else {
    try {
      rec = await receptors.startRecording();
      setRecordingUi(true, rec.startedAt);
    } catch {
      alert("Microphone unavailable. On a phone, 360 needs to be served over HTTPS (or localhost).");
    }
  }
});

function setRecordingUi(on, startedAt) {
  $("btn-mic").classList.toggle("recording", on);
  $("rec-pill").hidden = !on;
  clearInterval(recTimer);
  if (on) {
    $("rec-pill").textContent = "● 0:00";
    recTimer = setInterval(() => {
