:root {
  --bg: #f2f2f6;
  --fg: #111114;
  --meta: #8e8e93;
  --hairline: rgba(0, 0, 0, 0.12);
  --sheet: #ffffff;
  --btn: #ffffff;
  --amber: #eab308;
  --blue: #3b82f6;
  --green: #22c55e;
  --teal: #14b8a6;
  --purple: #a855f7;
  --red: #ef4444;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #000000;
    --fg: #f2f2f7;
    --meta: #98989f;
    --hairline: rgba(255, 255, 255, 0.16);
    --sheet: #1c1c1e;
    --btn: #2c2c2e;
  }
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  background: var(--bg);
  color: var(--fg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  touch-action: manipulation;
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  -webkit-user-select: none;
}
button:disabled { opacity: 0.4; }

header { padding: calc(env(safe-area-inset-top) + 14px) 20px 10px; }
header h1 { font-size: 17px; font-weight: 700; }
header .sub { font-size: 13px; color: var(--meta); margin-top: 2px; }

main { padding-bottom: 130px; }

#queue { list-style: none; padding: 0 16px; }

#queue li { border-bottom: 1px solid var(--hairline); }

.row {
  display: flex;
  gap: 10px;
  padding: 8px 0;
  align-items: stretch;
}

.row .bar { width: 4px; border-radius: 2px; flex: none; }

.row-main { flex: 1; min-width: 0; }

.row-title {
  font-size: 16px;
  font-weight: 650;
  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.row-meta {
  margin-top: 1px;
  font-size: 13px;
  color: var(--meta);
  display: flex;
  gap: 8px;
  flex-wrap: nowrap;
  overflow: hidden;
}
.row-meta span { white-space: nowrap; }
.row-meta span:last-child { overflow: hidden; text-overflow: ellipsis; }
.row-meta .place { color: var(--green); font-weight: 600; }

.chev { color: var(--meta); align-self: center; transition: transform 0.2s; }
li.open .chev { transform: rotate(90deg); }

.detail {
  display: none;
  margin-left: 14px;
  padding-bottom: 14px;
}
.detail img { width: 100%; border-radius: 12px; display: block; }
.detail audio { width: 100%; }
.detail .body { white-space: pre-wrap; font-size: 16px; line-height: 1.4; }
.detail a { color: var(--teal); font-size: 16px; }

li.new .row { animation: pop 0.35s ease; }
@keyframes pop {
  from { opacity: 0; transform: translateY(-8px); }
}

#empty {
  text-align: center;
  color: var(--meta);
  padding: 90px 32px;
  font-size: 16px;
  line-height: 1.6;
}

.cluster {
  position: fixed;
  bottom: calc(env(safe-area-inset-bottom) + 18px);
  display: flex;
  gap: 12px;
  align-items: center;
}
.cluster.left { left: 16px; }
.cluster.right { right: 16px; }

.cluster button {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  border: none;
  background: var(--btn);
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.18);
  display: flex;
  align-items: center;
  justify-content: center;
}
.cluster button svg { width: 25px; height: 25px; }
#btn-camera { width: 62px; height: 62px; }
#btn-camera svg { width: 28px; height: 28px; }

#btn-mic.recording {
  background: var(--red);
  color: #fff;
}

#rec-pill {
  position: fixed;
  top: calc(env(safe-area-inset-top) + 10px);
  left: 50%;
  transform: translateX(-50%);
  background: var(--red);
  color: #fff;
  padding: 6px 14px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 14px;
  font-variant-numeric: tabular-nums;
}

.sheet {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: flex-end;
  z-index: 10;
}
.sheet[hidden] { display: none; }

.sheet-card {
  background: var(--sheet);
  width: 100%;
  border-radius: 16px 16px 0 0;
  padding: 20px 20px calc(env(safe-area-inset-bottom) + 20px);
}
.sheet-card h2 { font-size: 17px; margin-bottom: 12px; }

textarea {
  width: 100%;
  min-height: 130px;
  font: inherit;
  font-size: 17px;
  border: 1px solid var(--hairline);
  border-radius: 12px;
  padding: 12px;
  background: transparent;
  color: var(--fg);
  resize: vertical;
}

.sheet-actions {
  display: flex;
  gap: 12px;
  margin-top: 14px;
  justify-content: flex-end;
}
.sheet-actions button {
  border: none;
  background: transparent;
  font-size: 17px;
  padding: 10px 18px;
  border-radius: 999px;
}
.sheet-actions .save {
  background: var(--fg);
  color: var(--bg);
  font-weight: 600;
}

.kv {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 10px 0;
  border-bottom: 1px solid var(--hairline);
  font-size: 15px;
}
.kv span:last-child {
  color: var(--meta);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.doctrine {
  margin-top: 14px;
  font-size: 13px;
  color: var(--meta);
  line-height: 1.5;
}

