import { deviceId, packetCount, exportLog } from "./log.js";
import * as receptors from "./receptors.js";
import { renderQueue, prependPacket, renderLake } from "./lens.js";
import { startDraining, fetchLake } from "./lake.js";
import { deriveNames } from "./fold.js";

const $ = (id) => document.getElementById(id);

// --- boot
renderQueue($("queue")).then(updateSub);
if ("serviceWorker" in navigator) navigator.serviceWorker.register("sw.js").catch(() => {});
navigator.storage?.persist?.().catch(() => {});
startDraining();

window.addEventListener("packet-appended", (e) => {
  if (view === "oq") prependPacket($("queue"), e.detail);
  updateSub();
});

async function updateSub() {
  if (view !== "oq") return;
  const n = await packetCount();
  $("sub").textContent = `local log · ${n} packet${n === 1 ? "" : "s"}`;
  $("empty").hidden = n > 0;
}

// --- views: OQ (this device) / Lake (every observer)
let view = "oq";
let lakePoll = null;

$("view-oq").addEventListener("click", () => switchView("oq"));
$("view-lake").addEventListener("click", () => switchView("lake"));

async function switchView(v) {
  if (v === view) return;
  view = v;
  $("view-oq").classList.toggle("active", v === "oq");
  $("view-lake").classList.toggle("active", v === "lake");
  clearInterval(lakePoll);
  $("empty").hidden = true;
  if (v === "oq") {
    await renderQueue($("queue"));
    updateSub();
  } else {
    $("sub").textContent = "the lake · every observer";
    const refresh = () => renderLake($("queue")).catch(() => {});
    await refresh();
    lakePoll = setInterval(refresh, 10_000);
  }
}

// --- audio
let rec = null;
let recTimer = null;
$("btn-mic").addEventListener("click", async () => {
  if (rec) {
    const r = rec;
    rec = null;
    setRecordingUi(false, 0);
    await r.stop();
  } else {
    try {
      rec = await receptors.startRecording();
      setRecordingUi(true, rec.startedAt);
    } catch {
      alert("Microphone unavailable. On a phone, 360 needs to be served over HTTPS (or localhost).");
    }
  }
});

function setRecordingUi(on, startedAt) {
  $("btn-mic").classList.toggle("recording", on);
  $("rec-pill").hidden = !on;
  clearInterval(recTimer);
  if (on) {
    $("rec-pill").textContent = "● 0:00";
    recTimer = setInterval(() => {
      const s = Math.floor((Date.now() - startedAt) / 1000);
      $("rec-pill").textContent = `● ${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
    }, 250);
  }
}

// --- location
$("btn-location").addEventListener("click", async () => {
  $("btn-location").disabled = true;
  try {
    await receptors.captureLocation();
  } catch {
    alert("Location unavailable. Check permission — and on a phone, 360 needs HTTPS.");
  } finally {
    $("btn-location").disabled = false;
  }
});

// --- settings
$("btn-settings").addEventListener("click", async () => {
  $("kv-device").textContent = deviceId();
  $("kv-count").textContent = String(await packetCount());
  $("kv-storage").textContent = await storageLine();
  $("settings-sheet").hidden = false;
});
$("settings-close").addEventListener("click", () => { $("settings-sheet").hidden = true; });
$("export-btn").addEventListener("click", exportLogToFile);

async function storageLine() {
  const est = await navigator.storage?.estimate?.().catch(() => null);
  if (est?.usage == null) return "—";
  return `${(est.usage / 1048576).toFixed(1)} MB used`;
}

async function exportLogToFile() {
  const nd = await exportLog();
  const stamp = new Date().toISOString().slice(0, 19).replaceAll(":", "-");
  const file = new File([nd], `packet-log-${stamp}.ndjson`, { type: "application/x-ndjson" });
  if (navigator.canShare?.({ files: [file] })) {
    await navigator.share({ files: [file] }).catch(() => {});
  } else {
    const a = document.createElement("a");
    a.href = URL.createObjectURL(file);
    a.download = file.name;
    a.click();
    URL.revokeObjectURL(a.href);
  }
}

