  --sheet: #ffffff;
  --btn: #ffffff;
  --amber: #eab308;
  --blue: #3b82f6;
  --green: #22c55e;
  --teal: #14b8a6;
  --purple: #a855f7;
  --red: #ef4444;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #000000;
