* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  background: var(--bg);
  color: var(--fg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  touch-action: manipulation;
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  -webkit-user-select: none;
}
button:disabled { opacity: 0.4; }

header {
  padding: calc(env(safe-area-inset-top) + 14px) 20px 10px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
header h1 { font-size: 17px; font-weight: 700; }
header .sub { font-size: 13px; color: var(--meta); margin-top: 2px; }

.views {
  display: flex;
  gap: 2px;
  background: rgba(127, 127, 127, 0.14);
  border-radius: 999px;
  padding: 3px;
}
.views button {
  border: none;
  background: transparent;
  padding: 6px 14px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 600;
  color: var(--meta);
}
.views button.active {
  background: var(--btn);
  color: var(--fg);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.15);
}

main { padding-bottom: 130px; }

#queue { list-style: none; padding: 0 16px; }

#queue li { border-bottom: 1px solid var(--hairline); }

.row {
  display: flex;
  gap: 10px;
  padding: 8px 0;
  align-items: stretch;
}

.row .bar { width: 4px; border-radius: 2px; flex: none; }

.row-main { flex: 1; min-width: 0; }

.row-title {
  font-size: 16px;
  font-weight: 650;
  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.row-meta {
  margin-top: 1px;
  font-size: 13px;
  color: var(--meta);
  display: flex;
  gap: 8px;
  flex-wrap: nowrap;
  overflow: hidden;
