// Receptors: each turns a moment of reality into a packet — instantly and dumbly.
// No receptor interprets. Location stamping is best-effort from a cached fix
// and never blocks a capture.

import { appendPacket } from "./log.js";

let lastFix = null;

export function freshFix(maxAgeMs = 90_000) {
  if (!lastFix || Date.now() - lastFix.at > maxAgeMs) return null;
  const { lat, lng, accuracy_m } = lastFix;
  return { lat, lng, accuracy_m };
}

export function refreshFix() {
  if (!navigator.geolocation) return;
  navigator.geolocation.getCurrentPosition(
    (pos) => { lastFix = fixFrom(pos); },
    () => {},
    { enableHighAccuracy: true, timeout: 10_000, maximumAge: 30_000 }
  );
}

function fixFrom(pos) {
  return {
    lat: +pos.coords.latitude.toFixed(5),
    lng: +pos.coords.longitude.toFixed(5),
    accuracy_m: Math.round(pos.coords.accuracy),
    at: Date.now(),
  };
}

export function captureText(body) {
  return appendPacket({ kind: "text", payload: { body }, loc: freshFix() });
}

// volume is the projection amplitude, recorded at utterance time:
// 1 stays in this queue; 2 reaches the person's other devices
export function say(body, volume) {
  return appendPacket({ kind: "text", payload: { body, volume }, loc: freshFix() });
}

export function claimName(name) {
  return appendPacket({ kind: "ui", payload: { action: "claim", name }, loc: freshFix() });
}

export function capturePhoto(file) {
  refreshFix();
  return appendPacket({
    kind: "image",
    blob: file,
    payload: { mime: file.type || "image/jpeg", bytes: file.size },
    loc: freshFix(),
  });
}

export function captureLocation() {
  return new Promise((resolve, reject) => {
    if (!navigator.geolocation) return reject(new Error("geolocation unavailable"));
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        lastFix = fixFrom(pos);
        const { lat, lng, accuracy_m } = lastFix;
        resolve(await appendPacket({
          kind: "location",
          payload: { lat, lng, accuracy_m },
          loc: { lat, lng, accuracy_m },
        }));
      },
      reject,
      { enableHighAccuracy: true, timeout: 15_000 }
    );
  });
}

export async function startRecording() {
  const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  const mime = ["audio/mp4", "audio/webm;codecs=opus", "audio/webm"]
    .find((m) => MediaRecorder.isTypeSupported(m));
  const recorder = new MediaRecorder(stream, mime ? { mimeType: mime } : undefined);
  const chunks = [];
  const startedAt = Date.now();
  const done = new Promise((resolve) => recorder.addEventListener("stop", resolve));
  recorder.addEventListener("dataavailable", (e) => { if (e.data.size) chunks.push(e.data); });
  recorder.start();
  refreshFix();

  return {
    startedAt,
    async stop() {
      recorder.stop();
      await done;
      stream.getTracks().forEach((t) => t.stop());
      const blob = new Blob(chunks, { type: recorder.mimeType || mime || "audio/mp4" });
      // observed_at is the moment recording STARTED — reference what you knew at perception time
      return appendPacket({
        kind: "audio",
        blob,
        payload: { mime: blob.type, bytes: blob.size, duration_ms: Date.now() - startedAt },
        observedAt: new Date(startedAt).toISOString(),
        loc: freshFix(),
      });
    },
  };
}

