// The lens. Renders packets; never writes them. Display is lens-side —
// the payload says what was observed, the lens decides how it looks.
// Views: the OQ (this device's log, plus what it hears through the graph)
// and the Lake (every observer's queue, named by the fold).

import { getBlob, listPackets, pendingIds, deviceId } from "./log.js";
import { fetchLake, remoteBlobUrl } from "./lake.js";
import { deriveNames, deriveHeard } from "./fold.js";

const KINDS = {
  text: { color: "var(--amber)", title: (p) => firstLine(p.payload.body) || "Note" },
  image: { color: "var(--blue)", title: () => "Photo" },
  audio: { color: "var(--green)", title: (p) => `Audio · ${mmss(p.payload.duration_ms)}` },
  location: { color: "var(--teal)", title: () => "Location" },
  ui: {
    color: "var(--purple)",
    title: (p) => (p.payload?.action === "claim" ? `Claimed “${p.payload.name}”` : "UI"),
  },
};
const FALLBACK = { color: "var(--purple)", title: (p) => p.kind };

const blobUrls = new Map();

// a row flips to "in lake" the moment its packet drains
window.addEventListener("packet-synced", (e) => {
  document.querySelectorAll(`li[data-id="${e.detail.id}"] .place`).forEach((el) => {
    el.textContent = "in lake";
    el.className = "place";
  });
});

export async function renderQueue(listEl) {
  const [packets, pending] = await Promise.all([listPackets(), pendingIds()]);
  let heardRows = [];
  try {
    const lake = await fetchLake();
    const names = deriveNames(lake);
    heardRows = deriveHeard(lake, deviceId(), names).map((p) => ({
      p,
      opts: { heardFrom: names.get(p.observer)?.name ?? shortObs(p) },
    }));
  } catch {
    // offline: the OQ still renders; hearing needs the lake
  }
  const rows = [
    ...packets.map((p) => ({ p, opts: { pending: pending.has(p.id) } })),
    ...heardRows,
