// The lens. Renders packets; never writes them. Display is lens-side —
// the payload says what was observed, the lens decides how it looks.
// Views: the OQ (this device's log, plus what it hears through the graph)
// and the Lake (every observer's queue, named by the fold).

import { getBlob, listPackets, pendingIds, deviceId } from "./log.js";
import { fetchLake, remoteBlobUrl } from "./lake.js";
import { deriveNames, deriveHeard, deriveEmergentNames } from "./fold.js";

// declared name first; emergent (~word) rides alongside or stands in
function labelFor(p, names, emergent) {
  const claimed = names.get(p.observer)?.name;
  const word = emergent.get(p.observer);
  if (claimed && word && !claimed.includes(word)) return `${claimed} · ~${word}`;
  if (claimed) return claimed;
  if (word) return `~${word}`;
  return shortObs(p);
}

const KINDS = {
  text: { color: "var(--amber)", title: (p) => firstLine(p.payload.body) || "Note" },
  image: { color: "var(--blue)", title: () => "Photo" },
  audio: { color: "var(--green)", title: (p) => `Audio · ${mmss(p.payload.duration_ms)}` },
  location: { color: "var(--teal)", title: () => "Location" },
  transcript: { color: "var(--purple)", title: (p) => firstLine(p.payload.body) || "Transcript" },
  ui: {
    color: "var(--purple)",
    title: (p) => (p.payload?.action === "claim" ? `Claimed “${p.payload.name}”` : "UI"),
  },
};
const FALLBACK = { color: "var(--purple)", title: (p) => p.kind };

const blobUrls = new Map();

// a row flips to "in lake" the moment its packet drains
window.addEventListener("packet-synced", (e) => {
  document.querySelectorAll(`li[data-id="${e.detail.id}"] .place`).forEach((el) => {
    el.textContent = "in lake";
    el.className = "place";
  });
});

export async function renderQueue(listEl) {
  const [packets, pending] = await Promise.all([listPackets(), pendingIds()]);
  let heardRows = [];
  try {
    const lake = await fetchLake();
    const names = deriveNames(lake);
    const emergent = deriveEmergentNames(lake);
    heardRows = deriveHeard(lake, deviceId(), names).map((p) => ({
      p,
      opts: { heardFrom: labelFor(p, names, emergent) },
    }));
  } catch {
    // offline: the OQ still renders; hearing needs the lake
  }
  const rows = [
    ...packets.map((p) => ({ p, opts: { pending: pending.has(p.id) } })),
    ...heardRows,
  ].sort((a, b) => (a.p.observed_at < b.p.observed_at ? 1 : -1));
  listEl.textContent = "";
  for (const r of rows) listEl.append(buildRow(r.p, r.opts));
}

export function prependPacket(listEl, packet) {
  const row = buildRow(packet, { pending: true });
  row.classList.add("new");
  listEl.prepend(row);
}

export async function renderLake(listEl) {
  const packets = await fetchLake();
  const names = deriveNames(packets);
  const emergent = deriveEmergentNames(packets);
  listEl.textContent = "";
  for (const p of packets) {
    listEl.append(buildRow(p, { obsLabel: labelFor(p, names, emergent) }));
  }
}

function buildRow(p, { pending = false, obsLabel = null, heardFrom = null } = {}) {
  const kind = KINDS[p.kind] ?? FALLBACK;
  const li = document.createElement("li");
  li.dataset.id = p.id;

  const row = document.createElement("div");
  row.className = "row";

  const bar = document.createElement("div");
  bar.className = "bar";
  bar.style.background = heardFrom ? "var(--purple)" : kind.color;

  const main = document.createElement("div");
  main.className = "row-main";

  const title = document.createElement("div");
  title.className = "row-title";
  title.textContent = kind.title(p);

  const meta = document.createElement("div");
  meta.className = "row-meta";
  const place = document.createElement("span");
  if (heardFrom) {
    place.className = "place place--heard";
    place.textContent = `heard · ${heardFrom}`;
  } else if (pending) {
    place.className = "place place--pending";
    place.textContent = "on device";
  } else {
    place.className = "place";
    place.textContent = "in lake";
  }
  const when = document.createElement("span");
  when.textContent = formatWhen(p.observed_at);
  meta.append(place, when);
  if (obsLabel) {
    const obs = document.createElement("span");
    obs.className = "obs";
    obs.textContent = obsLabel;
    meta.append(obs);
  }
  if (p.loc) {
    const coords = document.createElement("span");
    coords.textContent = `${p.loc.lat}, ${p.loc.lng}`;
    meta.append(coords);
  }

  main.append(title, meta);
  row.append(bar, main, chevron());
  li.append(row);

  row.addEventListener("click", () => toggleDetail(li, p));
  return li;
}

async function toggleDetail(li, p) {
  const open = li.classList.toggle("open");
  let detail = li.querySelector(".detail");
  if (!detail) {
    detail = document.createElement("div");
    detail.className = "detail";
    li.append(detail);
    await fillDetail(detail, p);
  }
  detail.style.display = open ? "block" : "none";
}

async function fillDetail(detail, p) {
  if (p.kind === "text" || p.kind === "transcript") {
    const body = document.createElement("div");
    body.className = "body";
    body.textContent = p.payload.body;
    detail.append(body);
    if (p.kind === "transcript") {
      const prov = document.createElement("div");
      prov.className = "prov";
      const from = p.links?.[0]?.id ? ` · derived from ${String(p.links[0].id).slice(0, 8)}` : "";
      prov.textContent = `${p.payload.model ?? "model"}${from}`;
      detail.append(prov);
    }
  } else if (p.kind === "image") {
    const img = document.createElement("img");
    img.src = await blobUrl(p.payload.blob);
    detail.append(img);
  } else if (p.kind === "audio") {
    const canvas = document.createElement("canvas");
    canvas.className = "wave";
    const audio = document.createElement("audio");
    audio.controls = true;
    audio.src = await blobUrl(p.payload.blob);
    detail.append(canvas, audio);
    drawWave(canvas, p).catch(() => canvas.remove());
  } else if (p.kind === "location") {
    const a = document.createElement("a");
    a.href = `https://maps.apple.com/?ll=${p.payload.lat},${p.payload.lng}`;
    a.target = "_blank";
    a.rel = "noopener";
    a.textContent = `${p.payload.lat}, ${p.payload.lng} · ±${p.payload.accuracy_m}m — open in Maps`;
    detail.append(a);
  } else {
    const body = document.createElement("div");
    body.className = "body";
    body.textContent = JSON.stringify(p.payload, null, 2);
    detail.append(body);
  }
}

// The wave, on an ABSOLUTE scale: full-scale signal = full height, so the
// same sound heard by two phones renders same shape, different amplitude.
async function drawWave(canvas, p) {
  if ((p.payload.bytes ?? 0) > 10_485_760) { canvas.remove(); return; } // skip very long audio
  const blob = await getBlob(p.payload.blob);
  const bytes = blob
    ? await blob.arrayBuffer()
    : await (await fetch(remoteBlobUrl(p.payload.blob))).arrayBuffer();
  const actx = new (window.AudioContext || window.webkitAudioContext)();
  let decoded;
  try {
    decoded = await actx.decodeAudioData(bytes);
  } finally {
    actx.close();
  }
  const data = decoded.getChannelData(0);

  const W = Math.max(200, (canvas.closest("li")?.clientWidth ?? 320) - 20);
  const H = 72;
  const dpr = window.devicePixelRatio || 1;
  canvas.width = W * dpr;
  canvas.height = H * dpr;
  canvas.style.width = `${W}px`;
  canvas.style.height = `${H}px`;
  const g = canvas.getContext("2d");
  g.scale(dpr, dpr);

  const cols = Math.min(360, W);
  const per = Math.floor(data.length / cols) || 1;
  const peaks = new Float32Array(cols);
  let sumSq = 0;
  let peakAll = 0;
  for (let i = 0; i < cols; i++) {
    let peak = 0;
    for (let j = i * per, e = Math.min(j + per, data.length); j < e; j++) {
      const v = Math.abs(data[j]);
      if (v > peak) peak = v;
      sumSq += data[j] * data[j];
    }
    peaks[i] = peak;
    if (peak > peakAll) peakAll = peak;
  }
  const rms = Math.sqrt(sumSq / data.length);

  g.fillStyle =
    getComputedStyle(document.documentElement).getPropertyValue("--green").trim() || "#22c55e";
  const mid = H / 2;
  const bw = W / cols;
  for (let i = 0; i < cols; i++) {
    const h = Math.max(1, peaks[i] * (H - 4));
    g.fillRect(i * bw, mid - h / 2, Math.max(1, bw - 1), h);
  }

  const stats = document.createElement("div");
  stats.className = "prov";
  stats.textContent = `peak ${Math.round(peakAll * 100)}% · rms ${Math.round(rms * 100)}% of full scale`;
  canvas.insertAdjacentElement("afterend", stats);
}

// local blob first; another observer's media streams from the lake
async function blobUrl(key) {
  if (!blobUrls.has(key)) {
    const blob = await getBlob(key);
    blobUrls.set(key, blob ? URL.createObjectURL(blob) : remoteBlobUrl(key));
  }
  return blobUrls.get(key);
}

function shortObs(p) {
  return `obs ${String(p.observer ?? p.origin?.device ?? "?").slice(0, 4)}`;
}

function firstLine(s = "") {
  const line = s.split("\n")[0].trim();
  return line.length > 48 ? line.slice(0, 48) + "…" : line;
}

function mmss(ms = 0) {
  const s = Math.round(ms / 1000);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}

function formatWhen(iso) {
  const d = new Date(iso);
  const day = d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
  const time = d.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
  return `${day} at ${time}`;
}

function chevron() {
  const span = document.createElement("span");
  span.className = "chev";
  span.innerHTML =
    '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>';
  return span;
}

