:root {
  --bg: #f2f2f6;
  --fg: #111114;
  --meta: #8e8e93;
  --hairline: rgba(0, 0, 0, 0.12);
  --sheet: #ffffff;
  --btn: #ffffff;
  --amber: #eab308;
  --blue: #3b82f6;
  --green: #22c55e;
  --teal: #14b8a6;
  --purple: #a855f7;
  --red: #ef4444;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #000000;
    --fg: #f2f2f7;
    --meta: #98989f;
    --hairline: rgba(255, 255, 255, 0.16);
    --sheet: #1c1c1e;
    --btn: #2c2c2e;
  }
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  background: var(--bg);
  color: var(--fg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  touch-action: manipulation;
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  -webkit-user-select: none;
}
button:disabled { opacity: 0.4; }

header {
  padding: calc(env(safe-area-inset-top) + 14px) 20px 10px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
header h1 { font-size: 17px; font-weight: 700; }
header .sub { font-size: 13px; color: var(--meta); margin-top: 2px; }

.views {
  display: flex;
  gap: 2px;
  background: rgba(127, 127, 127, 0.14);
  border-radius: 999px;
  padding: 3px;
}
.views button {
  border: none;
  background: transparent;
  padding: 6px 14px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 600;
