}
.views button.active {
  background: var(--btn);
  color: var(--fg);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.15);
}

main { padding-bottom: 130px; }

#queue { list-style: none; padding: 0 16px; }

#queue li { border-bottom: 1px solid var(--hairline); }

.row {
  display: flex;
  gap: 10px;
  padding: 8px 0;
  align-items: stretch;
}

.row .bar { width: 4px; border-radius: 2px; flex: none; }

.row-main { flex: 1; min-width: 0; }

.row-title {
  font-size: 16px;
  font-weight: 650;
  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.row-meta {
  margin-top: 1px;
  font-size: 13px;
  color: var(--meta);
  display: flex;
  gap: 8px;
  flex-wrap: nowrap;
  overflow: hidden;
}
.row-meta span { white-space: nowrap; }
.row-meta span:last-child { overflow: hidden; text-overflow: ellipsis; }
.row-meta .place { color: var(--green); font-weight: 600; }
.row-meta .place--pending { color: var(--amber); }
.row-meta .place--heard { color: var(--purple); }
.row-meta .obs { color: var(--purple); font-weight: 600; }

.chev { color: var(--meta); align-self: center; transition: transform 0.2s; }
li.open .chev { transform: rotate(90deg); }

.detail {
  display: none;
  margin-left: 14px;
  padding-bottom: 14px;
}
.detail img { width: 100%; border-radius: 12px; display: block; }
.detail audio { width: 100%; }
.detail .body { white-space: pre-wrap; font-size: 16px; line-height: 1.4; }
.detail a { color: var(--teal); font-size: 16px; }

li.new .row { animation: pop 0.35s ease; }
@keyframes pop {
  from { opacity: 0; transform: translateY(-8px); }
}

#empty {
