  $("kv-storage").textContent = await storageLine();
  $("settings-sheet").hidden = false;
  trainGoop();
  $("kv-name").textContent = await claimedName();
});

// the queue model: a fold of this device's OQ, identified by (queue, seq range)
async function trainGoop() {
  const packets = await listPackets();
  const spoken = packets.filter(
    (p) => (p.kind === "text" || p.kind === "transcript") && p.payload?.body
  );
  queueModel = trainModel(spoken.map((p) => p.payload.body));
  if (!queueModel.words) {
    $("goop-stats").textContent = "empty queue — say something first";
    return;
  }
  const seqs = packets.map((p) => p.seq).filter((s) => s != null);
  $("goop-stats").textContent =
    `${spoken.length} packets · ${queueModel.words} words · seq ${Math.min(...seqs)}–${Math.max(...seqs)}`;
}

