// Deterministic response policy: the mode is a pure function of how well the
// model predicted the incoming words — no dice between modes. Expected →
// "ok". Illegible (mostly never-heard words) → "why?". Half-familiar → riff.
// As the queue grows, surprise falls and the policy matures on its own.
export function respond(model, body) {
  const toks = tokenize(body);
  if (!toks.length || !model?.words) return { mode: "why", body: "why?" };
  const novel = toks.filter((w) => !model.uni.has(w)).length / toks.length;
  let known = 0;
  let total = 0;
  for (let i = 1; i < toks.length; i++) {
    total++;
    if (model.bi.get(toks[i - 1])?.has(toks[i])) known++;
  }
  const coverage = total ? known / total : 0;
  if (novel > 0.5) return { mode: "why", body: "why?" };
  if (coverage >= 0.75) return { mode: "ok", body: "ok" };
  const riff = goop(model, toks.slice(-2).join(" "), 24);
  return { mode: "riff", body: riff || "ok" };
}

