toolUseResult.originalFile:
// The queue model. Cal's loop implemented with counts instead of backprop:
// see a word in context, remember it perfectly — next time that context
// appears, predict it right. A trigram-with-backoff Markov model is the
// smallest zero-mystique version of "overfit exactly to the queue": fully
// explicit, deterministic, corpus snapshottable as (queue, seq range).
// Trained at tap-time from the log; stored nowhere. GOOP is the point.

export function trainModel(bodies) {
  const tri = new Map(); // "w1 w2" -> Map(w3 -> n)
  const bi = new Map();  // w1 -> Map(w2 -> n)
  const uni = new Map(); // w -> n
  let words = 0;
  for (const body of bodies) {
    const toks = tokenize(body);
    words += toks.length;
    for (let i = 0; i < toks.length; i++) {
      bump(uni, toks[i]);
      if (i >= 1) bumpNested(bi, toks[i - 1], toks[i]);
      if (i >= 2) bumpNested(tri, `${toks[i - 2]} ${toks[i - 1]}`, toks[i]);
    }
  }
  return { tri, bi, uni, words };
}

export function goop(model, seed, maxWords = 40) {
  const toks = tokenize(seed);
  const out = [];
  for (let i = 0; i < maxWords; i++) {
    const w2 = toks[toks.length - 1];
    const w1 = toks[toks.length - 2];
    const next =
      (w1 && w2 && pick(model.tri.get(`${w1} ${w2}`))) ||
      (w2 && pick(model.bi.get(w2))) ||
      pick(model.uni);
    if (!next) break;
    out.push(next);
    toks.push(next);
  }
  return out.join(" ");
}

// Deterministic response policy: the mode is a pure function of how well the
// model predicted the incoming words — no dice between modes. Expected →
// "ok". Illegible (mostly never-heard words) → "why?". Half-familiar → riff.
// As the queue grows, surprise falls and the policy matures on its own.
export function respond(model, body) {
  const toks = tokenize(body);
  if (!toks.length || !model?.words) return { mode: "why", body: "why?" };
  const novel = toks.filter((w) => !model.uni.has(w)).length / toks.length;
  let known = 0;
  let total = 0;
  for (let i = 1; i < toks.length; i++) {
    total++;
    if (model.bi.get(toks[i - 1])?.has(toks[i])) known++;
  }
  const coverage = total ? known / total : 0;
  if (novel > 0.5) return { mode: "why", body: "why?" };
  if (coverage >= 0.75) return { mode: "ok", body: "ok" };
  const riff = goop(model, toks.slice(-2).join(" "), 24);
  return { mode: "riff", body: riff || "ok" };
}

function tokenize(s = "") {
  return s.toLowerCase().match(/[a-z0-9']+/g) ?? [];
}

function bump(map, k) {
  map.set(k, (map.get(k) ?? 0) + 1);
}

function bumpNested(map, k, w) {
  let inner = map.get(k);
  if (!inner) map.set(k, (inner = new Map()));
  bump(inner, w);
}

function pick(counts) {
  if (!counts || !counts.size) return null;
  let total = 0;
  for (const n of counts.values()) total += n;
  let r = Math.random() * total;
  for (const [w, n] of counts) {
    r -= n;
    if (r <= 0) return w;
  }
  return null;
}

