// Emergent naming: a queue's name condenses out of what is said in it.
// Score = how often a word appears here vs everywhere else (a thin TF-IDF
// against the lake itself; real-world frequencies are a later data file).
// Derived per look, stored nowhere. Declared names (claims) and emergent
// names can drift apart — the drift is signal.
const COMMON = new Set(
  ("the be to of and a in that have i it for not on with he as you do at this but his by from they we say her " +
   "she or an will my one all would there their what so up out if about who get which go me when make can like " +
   "time no just him know take into year your good some could them see other than then now look only come its " +
   "over think also back after use two how our work first well way even new want because any these give day " +
   "most us is are was were been has had does did doing im dont cant thats youre ive hey hello okay ok yeah " +
   "yes really very much more why where here was what").split(" ")
);

export function deriveEmergentNames(lakePackets, perQueueWindow = 50) {
  const bodies = new Map(); // observer -> recent spoken/typed bodies
  for (const p of lakePackets) {
    if ((p.kind !== "text" && p.kind !== "transcript") || !p.payload?.body) continue;
    const list = bodies.get(p.observer) ?? [];
    if (list.length < perQueueWindow) list.push(p.payload.body);
    bodies.set(p.observer, list);
  }

  const counts = new Map(); // observer -> Map(word -> n)
  const global = new Map();
  for (const [obs, list] of bodies) {
    const c = new Map();
    for (const body of list) {
      for (const w of body.toLowerCase().match(/[a-z']{3,}/g) ?? []) {
        if (COMMON.has(w)) continue;
        c.set(w, (c.get(w) ?? 0) + 1);
        global.set(w, (global.get(w) ?? 0) + 1);
      }
    }
    counts.set(obs, c);
  }

  const names = new Map();
  for (const [obs, c] of counts) {
    let best = null;
    let bestScore = 0;
    for (const [w, n] of c) {
      const elsewhere = (global.get(w) ?? n) - n;
      const score = n / (1 + elsewhere);
      if (score > bestScore) {
        best = w;
        bestScore = score;
      }
    }
    if (best) names.set(obs, best);
  }
  return names;
}

input.new_string:
// Emergent naming: a queue's name condenses out of what is said in it.
// No stoplist, no English priors — commonness is derived from the lake
// itself: a word said in most queues distinguishes none of them (IDF).
// A word said in every queue scores exactly zero. The measure sharpens
// automatically as observers join. Derived per look, stored nowhere.
export function deriveEmergentNames(lakePackets, perQueueWindow = 50) {
  const bodies = new Map(); // observer -> recent spoken/typed bodies
  for (const p of lakePackets) {
    if ((p.kind !== "text" && p.kind !== "transcript") || !p.payload?.body) continue;
    const list = bodies.get(p.observer) ?? [];
    if (list.length < perQueueWindow) list.push(p.payload.body);
    bodies.set(p.observer, list);
  }

  const counts = new Map(); // observer -> Map(word -> n)
  const queuesWith = new Map(); // word -> Set(observers that say it)
  for (const [obs, list] of bodies) {
    const c = new Map();
    for (const body of list) {
      for (const w of body.toLowerCase().match(/[a-z']{3,}/g) ?? []) {
        c.set(w, (c.get(w) ?? 0) + 1);
        let s = queuesWith.get(w);
        if (!s) queuesWith.set(w, (s = new Set()));
        s.add(obs);
      }
    }
    counts.set(obs, c);
  }

  const N = counts.size;
  const names = new Map();
  for (const [obs, c] of counts) {
    let best = null;
    let bestScore = 0;
    let fallback = null;
    let fallbackN = 0;
    for (const [w, n] of c) {
      const score = n * Math.log((1 + N) / (1 + queuesWith.get(w).size));
      if (score > bestScore) {
        best = w;
        bestScore = score;
      }
      if (n > fallbackN) {
        fallback = w;
        fallbackN = n;
      }
    }
    // a lone queue has nothing to contrast against; its loudest word stands in
    if (best ?? fallback) names.set(obs, best ?? fallback);
  }
  return names;
}

