toolUseResult.originalFile:
// The first fold. Derives observer names and the person graph from claim
// packets in the lake — nothing here is stored; it is rebuilt on every look.
// A claim is an ordinary ui packet: { action: "claim", name: "cal.pocket" }.
// The dot is the hierarchy: person "cal", device label "pocket". The person
// is a derived node with no queue of its own — the devices are its senses.

export function deriveNames(lakePackets) {
  const names = new Map(); // observer id -> { name, person, at }
  for (const p of lakePackets) {
    if (p.kind !== "ui" || p.payload?.action !== "claim" || !p.payload?.name) continue;
    const cur = names.get(p.observer);
    if (!cur || p.observed_at > cur.at) {
      const name = String(p.payload.name).trim().toLowerCase();
      names.set(p.observer, { name, person: name.split(".")[0], at: p.observed_at });
    }
  }
  return names;
}

