// just the conversation: who said what, when — genome packets excluded
async function exportChat() {
  const packets = await listPackets();
  const lines = packets
    .filter(
      (p) =>
        (p.kind === "text" || p.kind === "transcript") &&
        p.payload?.body &&
        p.payload.role !== "algorithm"
    )
    .sort((a, b) => (a.observed_at < b.observed_at ? -1 : 1))
    .map((p) => {
      const d = new Date(p.observed_at);
      const t =
        d.toLocaleDateString(undefined, { month: "short", day: "numeric" }) +
        " " +
        d.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
      const who = p.origin?.device?.startsWith("goop:")
        ? `goop${p.payload.mode ? " · " + p.payload.mode : ""}`
        : "phone";
      return `[${t}] ${who}: ${p.payload.body}`;
    });
  await shareFile(`chat-${new Date().toISOString().slice(0, 10)}.txt`, lines.join("\n"), "text/plain");
}

