import { deviceId, packetCount, exportLog, listPackets, appendPacket } from "./log.js";
import { trainModel, goop, respond, algoSource } from "./goop.js";

// The genome packet: the goop's complete source, appended to its own queue
// once per version. Every reply cites it by hash, so any answer is fully
// re-derivable: exact code + exact corpus + deterministic policy.
let algoHash = null;
async function ensureGenome() {
  if (algoHash) return algoHash;
  try {
    const src = await algoSource();
    algoHash = await sha256Hex(src);
    if (algoHash && localStorage.getItem("goop-genome") !== algoHash) {
      await appendPacket({
        kind: "text",
        payload: { body: src, name: "goop-trigram-v1", role: "algorithm", algo: algoHash },
        origin: { device: `goop:${deviceId()}` },
      });
      localStorage.setItem("goop-genome", algoHash);
    }
  } catch {
    // offline before first cache: reply goes out uncited this once
  }
  return algoHash;
}

async function sha256Hex(s) {
  if (!crypto.subtle) return null;
  const d = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  return [...new Uint8Array(d)].map((b) => b.toString(16).padStart(2, "0")).join("");
}
import * as receptors from "./receptors.js";
import { renderQueue, prependPacket, renderLake } from "./lens.js";
import { startDraining, fetchLake } from "./lake.js";
import { deriveNames } from "./fold.js";

const $ = (id) => document.getElementById(id);

// --- boot
renderQueue($("queue")).then(updateSub);
if ("serviceWorker" in navigator) navigator.serviceWorker.register("sw.js").catch(() => {});
navigator.storage?.persist?.().catch(() => {});
startDraining();

window.addEventListener("packet-appended", (e) => {
  if (view === "oq") prependPacket($("queue"), e.detail);
  updateSub();
  respondToTranscript(e.detail);
});

// Every transcript gets a reply from the resident goop: mode chosen
// deterministically by surprise, judged against the model as it stood
// BEFORE this packet arrived — true prediction, not hindsight.
async function respondToTranscript(p) {
  if (p.kind !== "transcript" || p.origin?.device !== deviceId()) return;
  if (!queueModel) await trainGoop(p.id);
  const algo = await ensureGenome();
  const { mode, body } = respond(queueModel, p.payload.body);
  await appendPacket({
    kind: "text",
    payload: { body, model: "goop-trigram-v1", mode, algo, corpus: corpusStamp },
    links: [{ rel: "in_reply_to", id: p.id }],
    origin: { device: `goop:${deviceId()}` },
  });
  await trainGoop(); // now absorb what was said
}

async function updateSub() {
  if (view !== "oq") return;
  const n = await packetCount();
  $("sub").textContent = `local log · ${n} packet${n === 1 ? "" : "s"}`;
  $("empty").hidden = n > 0;
}

// --- views: OQ (this device) / Lake (every observer)
let view = "oq";
let lakePoll = null;

$("view-oq").addEventListener("click", () => switchView("oq"));
$("view-lake").addEventListener("click", () => switchView("lake"));

async function switchView(v) {
  if (v === view) return;
  view = v;
  $("view-oq").classList.toggle("active", v === "oq");
  $("view-lake").classList.toggle("active", v === "lake");
  clearInterval(lakePoll);
  $("empty").hidden = true;
  if (v === "oq") {
    await renderQueue($("queue"));
    updateSub();
  } else {
    $("sub").textContent = "the lake · every observer";
    await renderLake($("queue")).catch(() => {});
    lakePoll = setInterval(() => renderLake($("queue"), { merge: true }).catch(() => {}), 10_000);
  }
}

// --- audio
let rec = null;
let recTimer = null;
$("btn-mic").addEventListener("click", async () => {
  if (rec) {
    const r = rec;
    rec = null;
    setRecordingUi(false, 0);
    await r.stop();
  } else {
    try {
      rec = await receptors.startRecording();
      setRecordingUi(true, rec.startedAt);
    } catch {
      alert("Microphone unavailable. On a phone, 360 needs to be served over HTTPS (or localhost).");
    }
  }
});

window.addEventListener("scribe-caption", (e) => {
  const el = $("live-caption");
  if (e.detail == null || !rec) {
    el.hidden = true;
    el.textContent = "";
    return;
  }
  el.textContent = e.detail;
  el.hidden = !e.detail;
});

function setRecordingUi(on, startedAt) {
  $("btn-mic").classList.toggle("recording", on);
  $("rec-pill").hidden = !on;
  clearInterval(recTimer);
  if (on) {
    $("rec-pill").textContent = "● 0:00";
    recTimer = setInterval(() => {
      const s = Math.floor((Date.now() - startedAt) / 1000);
      $("rec-pill").textContent = `● ${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
    }, 250);
  }
}

// --- say (text at a volume: 1 stays here, 2 reaches my other devices)
let volume = 2;
$("btn-say").addEventListener("click", () => {
  receptors.refreshFix();
  $("say-sheet").hidden = false;
  $("say-input").focus();
});
$("vol-1").addEventListener("click", () => setVolume(1));
$("vol-2").addEventListener("click", () => setVolume(2));
function setVolume(v) {
  volume = v;
  $("vol-1").classList.toggle("active", v === 1);
  $("vol-2").classList.toggle("active", v === 2);
}
$("say-cancel").addEventListener("click", closeSaySheet);
$("say-save").addEventListener("click", async () => {
  const body = $("say-input").value.trim();
  if (!body) return;
  closeSaySheet();
  await receptors.say(body, volume);
});
function closeSaySheet() {
  $("say-sheet").hidden = true;
  $("say-input").value = "";
}

// --- location
$("btn-location").addEventListener("click", async () => {
  $("btn-location").disabled = true;
  try {
    await receptors.captureLocation();
  } catch {
    alert("Location unavailable. Check permission — and on a phone, 360 needs HTTPS.");
  } finally {
    $("btn-location").disabled = false;
  }
});

// --- settings
let queueModel = null;
$("btn-settings").addEventListener("click", async () => {
  $("kv-device").textContent = deviceId();
  $("kv-count").textContent = String(await packetCount());
  $("kv-storage").textContent = await storageLine();
  $("settings-sheet").hidden = false;
  trainGoop();
  $("kv-name").textContent = await claimedName();
});

// the queue model: a fold of this device's OQ, identified by (queue, seq range).
// Trains ONLY on packets this phone perceived — never on the goop's own
// answers, or the parrot eats its chants and collapses.
let corpusStamp = null;
async function trainGoop(excludeId = null) {
  const packets = await listPackets();
  const spoken = packets.filter(
    (p) =>
      (p.kind === "text" || p.kind === "transcript") &&
      p.payload?.body &&
      p.origin?.device === deviceId() &&
      p.id !== excludeId
  );
  queueModel = trainModel(spoken.map((p) => p.payload.body));
  if (!queueModel.words) {
    $("goop-stats").textContent = "empty queue — say something first";
    return;
  }
  const seqs = packets.map((p) => p.seq).filter((s) => s != null);
  corpusStamp = {
    device: deviceId(),
    packets: spoken.length,
    words: queueModel.words,
    seq_lo: Math.min(...seqs),
    seq_hi: Math.max(...seqs),
  };
  $("goop-stats").textContent =
    `${spoken.length} packets · ${queueModel.words} words · seq ${corpusStamp.seq_lo}–${corpusStamp.seq_hi}`;
}

// call and response, in the queue itself: the question is Cal's packet,
// the answer is the goop's packet in its OWN queue, in_reply_to, with its
// corpus citation stamped in the payload.
$("goop-btn").addEventListener("click", async () => {
  if (!queueModel?.words) return;
  const q = $("goop-seed").value.trim();
  if (!q) return;
  $("goop-seed").value = "";
  const out = goop(queueModel, q) || "…";
  $("goop-out").textContent = out;
  $("goop-out").hidden = false;
  const question = await receptors.captureText(q);
  const algo = await ensureGenome();
  await appendPacket({
    kind: "text",
    payload: { body: out, model: "goop-trigram-v1", mode: "riff", algo, corpus: corpusStamp },
    links: [{ rel: "in_reply_to", id: question.id }],
    origin: { device: `goop:${deviceId()}` },
  });
});
$("claim-btn").addEventListener("click", async () => {
  const name = $("claim-input").value.trim().toLowerCase();
  if (!name) return;
  $("claim-input").value = "";
  await receptors.claimName(name);
  $("kv-name").textContent = name;
});

async function claimedName() {
  try {
    const names = deriveNames(await fetchLake());
    return names.get(deviceId())?.name ?? "unclaimed";
  } catch {
    return "unclaimed";
  }
}
$("settings-close").addEventListener("click", () => { $("settings-sheet").hidden = true; });
$("export-btn").addEventListener("click", exportLogToFile);

async function storageLine() {
  const est = await navigator.storage?.estimate?.().catch(() => null);
  if (est?.usage == null) return "—";
  return `${(est.usage / 1048576).toFixed(1)} MB used`;
}

async function exportLogToFile() {
  const nd = await exportLog();
  const stamp = new Date().toISOString().slice(0, 19).replaceAll(":", "-");
  const file = new File([nd], `packet-log-${stamp}.ndjson`, { type: "application/x-ndjson" });
  if (navigator.canShare?.({ files: [file] })) {
    await navigator.share({ files: [file] }).catch(() => {});
  } else {
    const a = document.createElement("a");
    a.href = URL.createObjectURL(file);
    a.download = file.name;
    a.click();
    URL.revokeObjectURL(a.href);
  }
}

// tapping the backdrop closes a sheet
$("settings-sheet").addEventListener("click", (e) => {
  if (e.target === $("settings-sheet")) $("settings-sheet").hidden = true;
});

