// the queue model: a fold of a chosen queue, identified by (queue, seq range).
// Default source is this device's own perceptions; any lake queue can be
// selected instead. Never trains on goop-origin packets or genome bodies.
let corpusStamp = null;
let goopSource = "device";

async function trainGoop(excludeId = null) {
  let packets;
  let sourceLabel;
  if (goopSource === "device") {
    packets = (await listPackets()).filter((p) => p.origin?.device === deviceId());
    sourceLabel = "this device";
  } else {
    packets = await fetchQueue(goopSource).catch(() => []);
    sourceLabel = goopSource.slice(0, 18);
  }
  const spoken = packets.filter(
    (p) =>
