async function pageAll(pathBase, max) {
  const out = [];
  const page = 1000;
  for (let offset = 0; offset < max; offset += page) {
    const res = await fetch(`${pathBase}&limit=${Math.min(page, max - offset)}&offset=${offset}`, {
      headers: HEADERS,
