#!/usr/bin/env python3
"""The reveal: name(imessage:self, λ) at three horizons, full corpus, same
IDF fold as the app. Prints only words and scores — never note contents."""
import json, math, re, urllib.request
from collections import Counter
from datetime import datetime, timedelta, timezone

LAKE = "https://.supabase.co"
KEY = ""

def fetch_all():
    rows, offset = [], 0
    while True:
        req = urllib.request.Request(
            f"{LAKE}/rest/v1/packet?select=observer,kind,payload,observed_at&order=seq.asc&limit=1000&offset={offset}",
            headers={"apikey": KEY, "Authorization": f"Bearer {KEY}"})
        with urllib.request.urlopen(req) as r:
            page = json.load(r)
        rows += page
        if len(page) < 1000:
            return rows
        offset += 1000

rows = fetch_all()
by_obs = {}
for r in rows:
    p = r.get("payload") or {}
    if r["kind"] in ("text", "transcript") and p.get("body") and p.get("role") != "algorithm":
        by_obs.setdefault(r["observer"], []).append((r["observed_at"], p["body"]))

tok = lambda s: re.findall(r"[a-z']{3,}", s.lower())

queues_with = {}
full_counts = {}
for obs, items in by_obs.items():
    c = Counter()
    for _, body in items:
        for w in tok(body):
            c[w] += 1
            queues_with.setdefault(w, set()).add(obs)
    full_counts[obs] = c

N = len(by_obs)
TARGET = "imessage:self"
items = sorted(by_obs[TARGET])
now = datetime.now(timezone.utc)
year_ago = (now - timedelta(days=365)).isoformat()

horizons = {
    "fast (last 50 notes)": items[-50:],
    "year (last 365 days)": [i for i in items if i[0] >= year_ago],
    "lifetime (all %d notes)" % len(items): items,
}

print(f"queues in lake: {N} · imessage notes: {len(items)}\n")
for name, subset in horizons.items():
    c = Counter()
    for _, body in subset:
        for w in tok(body):
            c[w] += 1
    scored = sorted(
        ((n * math.log((1 + N) / (1 + len(queues_with[w]))), w, n) for w, n in c.items()),
        reverse=True)
    print(name)
    for s, w, n in scored[:6]:
        print(f"   {w:20s} n={n:<6d} score={s:.1f}")
    print()

