#!/usr/bin/env python3
"""twin — a local seance over chat.db. Fully offline; nothing leaves this machine.

Each chosen person becomes an expert: a Markov fold over ONLY the messages
they sent you (their sediment, speaking under the tilde). Routing is
coverage-arbitration — the expert whose model best predicts the question
hears it loudest and answers; at volume 2 the answer is re-scored and the
next-best expert may riff on it (the cascade). The twin log is append-only
ndjson in this directory; twin utterances feed back into their own expert
on purpose — contamination is labeled strata, and origins never lie, so
any future fold can re-derive the pure corpus.

Run from YOUR terminal (it holds Full Disk Access):
    python3 twin.py --list              # top contacts by message volume
    python3 twin.py "Mom" "Finn"        # start the seance with chosen people
Then open http://localhost:8362
"""

import argparse
import glob
import json
import math
import random
import re
import sqlite3
import sys
import uuid
from collections import Counter, defaultdict
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, HTTPServer
from pathlib import Path

HERE = Path(__file__).parent
LOG_PATH = HERE / "twin-log.ndjson"
APPLE_EPOCH = 978307200
END = "¶"
SILENCE = "…"  # the room saying nothing

# ---------------------------------------------------------------- the fold

def tokenize(s):
    return re.findall(r"[a-z0-9']+", s.lower())


class Model:
    def __init__(self):
        self.tri = defaultdict(Counter)
        self.bi = defaultdict(Counter)
        self.uni = Counter()
        self.words = 0
        self.bodies = 0

    def feed(self, body):
        toks = tokenize(body)
        if not toks:
            return
        self.words += len(toks)
        self.bodies += 1
        seq = toks + [END]
        for i, w in enumerate(seq):
            if w != END:
                self.uni[w] += 1
            if i >= 1:
                self.bi[seq[i - 1]][w] += 1
            if i >= 2:
                self.tri[(seq[i - 2], seq[i - 1])][w] += 1

    def coverage(self, text):
        """How well this expert could have predicted the utterance: a blend
        of vocabulary knowledge and known word-to-word transitions."""
        toks = tokenize(text)
        if not toks or not self.uni:
            return 0.0
        vocab = sum(1 for w in toks if w in self.uni) / len(toks)
        trans_total = max(1, len(toks) - 1)
        trans = sum(1 for i in range(1, len(toks)) if toks[i] in self.bi.get(toks[i - 1], ())) / trans_total
        return round(0.5 * vocab + 0.5 * trans, 4)

    def riff(self, seed, max_words=200):
        toks = tokenize(seed)
        if not toks:
            if not self.uni:
                return ""
            toks = [random.choice(list(self.uni))]
        out = []
        for _ in range(max_words):
            w2 = toks[-1]
            w1 = toks[-2] if len(toks) >= 2 else None
            dist = (self.tri.get((w1, w2)) if w1 else None) or self.bi.get(w2) or self.uni
            if not dist:
                break
            nxt = random.choices(list(dist.keys()), weights=list(dist.values()))[0]
            if nxt == END:
                break
            out.append(nxt)
            toks.append(nxt)
        return " ".join(out)

# ------------------------------------------------------------- the sources

def digits(s):
    return re.sub(r"\D", "", s or "")


def decode_attributed(blob):
    if not blob:
        return None
    try:
        s = blob.split(b"NSString")[1][5:]
        if s[0] == 0x81:
            length = int.from_bytes(s[1:3], "little")
            start = 3
        else:
            length = s[0]
            start = 1
        return s[start:start + length].decode("utf-8", errors="ignore") or None
    except Exception:
        return None


def find_db(explicit):
    for p in ([Path(explicit)] if explicit else []) + [Path("/tmp/chat.db"), Path.home() / "Library/Messages/chat.db"]:
        if p and p.exists():
            return p
    sys.exit("no chat.db found (copy to /tmp or grant Full Disk Access)")


def load_contacts(explicit):
    names = {}
    if explicit:
        paths = [explicit]
    else:
        base = Path.home() / "Library/Application Support/AddressBook"
        paths = glob.glob(str(base / "**" / "AddressBook-v22.abcddb"), recursive=True)
    for db in paths:
        try:
            con = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
            cur = con.cursor()
            for first, last, num in cur.execute(
                "SELECT r.ZFIRSTNAME, r.ZLASTNAME, p.ZFULLNUMBER "
                "FROM ZABCDPHONENUMBER p JOIN ZABCDRECORD r ON p.ZOWNER = r.Z_PK"):
                name = " ".join(x for x in (first, last) if x)
                if name and num:
                    names[digits(num)[-10:]] = name
            for first, last, email in cur.execute(
                "SELECT r.ZFIRSTNAME, r.ZLASTNAME, e.ZADDRESS "
                "FROM ZABCDEMAILADDRESS e JOIN ZABCDRECORD r ON e.ZOWNER = r.Z_PK"):
                name = " ".join(x for x in (first, last) if x)
                if name and email:
                    names[email.lower()] = name
            con.close()
        except Exception:
            continue
    return names


def resolve(handle, contacts):
    h = handle or ""
    if "@" in h:
        return contacts.get(h.lower())
    return contacts.get(digits(h)[-10:])


def load_people(db_path, contacts):
    """person name -> {"them": [bodies], "me": [bodies], "count": n}"""
    con = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
    cur = con.cursor()
    people = defaultdict(lambda: {"them": [], "me": [], "count": 0})
    for handle, from_me, text, ab in cur.execute(
        "SELECT h.id, m.is_from_me, m.text, m.attributedBody "
        "FROM message m JOIN handle h ON m.handle_id = h.ROWID "
        "WHERE m.associated_message_type = 0"):
        body = (text or decode_attributed(ab) or "").strip()
        if not body:
            continue
        name = resolve(handle, contacts) or handle
        p = people[name]
        p["count"] += 1
        p["me" if from_me else "them"].append(body)
    con.close()
    return people

# ---------------------------------------------------------------- the log

def append_log(origin, body, extra=None):
    packet = {
        "id": str(uuid.uuid4()),
        "kind": "text",
        "observed_at": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"),
        "origin": {"device": origin},
        "payload": {"body": body, **(extra or {})},
        "links": [],
    }
    with open(LOG_PATH, "a") as f:
