def tokenize(s):
    return re.findall(r"[a-z0-9']+", s.lower())


class Model:
    def __init__(self):
        self.tri = defaultdict(Counter)
        self.bi = defaultdict(Counter)
        self.uni = Counter()
        self.words = 0
        self.bodies = 0

    def feed(self, body):
        toks = tokenize(body)
        if not toks:
            return
        self.words += len(toks)
        self.bodies += 1
        seq = toks + [END]
        for i, w in enumerate(seq):
            if w != END:
                self.uni[w] += 1
            if i >= 1:
                self.bi[seq[i - 1]][w] += 1
            if i >= 2:
                self.tri[(seq[i - 2], seq[i - 1])][w] += 1

    def coverage(self, text):
        """How well this expert could have predicted the utterance: a blend
        of vocabulary knowledge and known word-to-word transitions."""
        toks = tokenize(text)
        if not toks or not self.uni:
            return 0.0
        vocab = sum(1 for w in toks if w in self.uni) / len(toks)
        trans_total = max(1, len(toks) - 1)
        trans = sum(1 for i in range(1, len(toks)) if toks[i] in self.bi.get(toks[i - 1], ())) / trans_total
        return round(0.5 * vocab + 0.5 * trans, 4)

    def riff(self, seed, max_words=200):
        toks = tokenize(seed)
        if not toks:
            if not self.uni:
                return ""
            toks = [random.choice(list(self.uni))]
        out = []
        for _ in range(max_words):
            w2 = toks[-1]
            w1 = toks[-2] if len(toks) >= 2 else None
            dist = (self.tri.get((w1, w2)) if w1 else None) or self.bi.get(w2) or self.uni
            if not dist:
                break
            nxt = random.choices(list(dist.keys()), weights=list(dist.values()))[0]
            if nxt == END:
                break
            out.append(nxt)
            toks.append(nxt)
