// The lens on the seance. Renders the log; never invents anything.
const $ = (id) => document.getElementById(id);
let volume = 2;

boot();

async function boot() {
  await renderExperts();
  const log = await fetch("/api/log").then((r) => r.json());
  for (const p of log) addRow(p);
  scrollLog();
}

async function renderExperts(scores = null) {
  const experts = await fetch("/api/experts").then((r) => r.json());
  const el = $("experts");
  el.textContent = "";
  for (const e of experts) {
    const card = document.createElement("div");
    card.className = "card";
    const name = document.createElement("div");
    name.className = "name";
    name.textContent = `~${e.name.toLowerCase()}`;
    const meta = document.createElement("div");
    meta.className = "meta";
    meta.textContent = `${e.bedrock} bedrock · ${e.growth} growth · ${e.words} words`;
    card.append(name, meta);
    if (scores && e.name in scores) {
      const bar = document.createElement("div");
      bar.className = "bar";
      const fill = document.createElement("div");
      fill.className = "fill";
      fill.style.width = `${Math.round(scores[e.name] * 100)}%`;
      bar.append(fill);
      const val = document.createElement("div");
      val.className = "meta";
      val.textContent = `coverage ${(scores[e.name] * 100).toFixed(1)}%`;
      card.append(bar, val);
    }
    el.append(card);
  }
}

function addRow(p) {
  const li = document.createElement("li");
  const dev = p.origin?.device ?? "";
  const mine = dev === "twin:cal";
  li.className = mine ? "row mine" : "row theirs";
  const who = document.createElement("div");
  who.className = "who";
  const when = new Date(p.observed_at).toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
  const cov = p.payload.coverage != null ? ` · ${(p.payload.coverage * 100).toFixed(0)}%` : "";
  who.textContent = mine ? `cal · ${when}` : `${dev.replace("twin:", "")}${cov} · ${when}`;
  const body = document.createElement("div");
  body.className = "bubble";
  body.textContent = p.payload.body;
  li.append(who, body);
  $("log").append(li);
}

function scrollLog() {
  const main = document.querySelector("main");
  main.scrollTop = main.scrollHeight;
}

$("vol-1").addEventListener("click", () => setVolume(1));
$("vol-2").addEventListener("click", () => setVolume(2));
function setVolume(v) {
  volume = v;
  $("vol-1").classList.toggle("active", v === 1);
  $("vol-2").classList.toggle("active", v === 2);
}

async function ask() {
  const seed = $("seed").value.trim();
  if (!seed) return;
  $("seed").value = "";
  const res = await fetch("/api/ask", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ seed, volume }),
  }).then((r) => r.json());
  for (const p of res.chain ?? []) addRow(p);
  renderExperts(res.scores ?? null);
  scrollLog();
}

$("ask").addEventListener("click", ask);
$("seed").addEventListener("keydown", (e) => {
  if (e.key === "Enter") ask();
});

