// The lens on the seance. Two views: the room (coverage-arbitration) and
// 1:1 chats (dialogue folds with learned turn-taking). Renders; never invents.
const $ = (id) => document.getElementById(id);
let volume = 2;
let view = "room"; // "room" | person name
let current = []; // packets rendered in the current view, for copy chat

boot();

async function boot() {
  await renderSidebar();
  await showRoom();
}

async function renderSidebar(scores = null) {
  const experts = await fetch("/api/experts").then((r) => r.json());
  const el = $("experts");
  el.textContent = "";
  el.append(sidebarCard("the room", "everyone at once · coverage decides", () => showRoom(), view === "room"));
  for (const e of experts) {
    const meta = `${e.bedrock} bedrock · ${e.growth} growth · ${e.words} words`;
    const card = sidebarCard(`~${String(e.name).toLowerCase()}`, meta, () => showChat(e.name), view === e.name);
    if (scores && e.name in scores) {
      const bar = document.createElement("div");
      bar.className = "bar";
      const fill = document.createElement("div");
      fill.className = "fill";
      fill.style.width = `${Math.round(scores[e.name] * 100)}%`;
      bar.append(fill);
      const val = document.createElement("div");
      val.className = "meta";
      val.textContent = `coverage ${(scores[e.name] * 100).toFixed(1)}%`;
      card.append(bar, val);
    }
    el.append(card);
  }
}

function sidebarCard(title, meta, onClick, active) {
  const card = document.createElement("div");
  card.className = active ? "card active" : "card";
  const name = document.createElement("div");
  name.className = "name";
  name.textContent = title;
  const m = document.createElement("div");
  m.className = "meta";
  m.textContent = meta;
  card.append(name, m);
  card.addEventListener("click", onClick);
  return card;
}

async function showRoom() {
  view = "room";
  $("mode-label").textContent = "the room";
  $("volume").hidden = false;
  $("sim-controls").hidden = true;
  $("log").textContent = "";
  current = [];
  const log = await fetch("/api/log").then((r) => r.json());
  for (const p of log) addRow(p);
  renderSidebar();
  scrollLog();
}

async function showChat(name) {
  view = name;
  $("mode-label").textContent = `~${String(name).toLowerCase()}`;
  $("volume").hidden = true;
  $("sim-controls").hidden = false;
  $("log").textContent = "";
  current = [];
  const thread = await fetch(`/api/thread?person=${encodeURIComponent(name)}`).then((r) => r.json());
  for (const p of thread) addRow(p);
  renderSidebar();
  scrollLog();
}

function addRow(p) {
  current.push(p);
  const li = document.createElement("li");
  const dev = p.origin?.device ?? "";
  const mine = dev === "twin:cal" || dev === "twin:~cal";
  li.className = mine ? "row mine" : "row theirs";
  if (p.payload.sim) li.classList.add("sim");
  const who = document.createElement("div");
  who.className = "who";
  const cov = p.payload.coverage != null ? ` · ${(p.payload.coverage * 100).toFixed(0)}%` : "";
  const when = p.payload.sim
    ? `+${fmtOffset(p.payload.sim_offset_s)}`
    : new Date(p.observed_at).toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
  who.textContent = dev === "twin:cal" ? `cal · ${when}` : `${dev.replace("twin:", "")}${cov} · ${when}`;
  const body = document.createElement("div");
  body.className = "bubble";
  body.textContent = p.payload.body;
  li.append(who, body);
  $("log").append(li);
}

function fmtOffset(s = 0) {
  if (s < 60) return `${s}s`;
  if (s < 3600) return `${Math.floor(s / 60)}m ${s % 60}s`;
  return `${Math.floor(s / 3600)}h ${Math.floor((s % 3600) / 60)}m`;
}

function addEnded(text) {
  const li = document.createElement("li");
  li.className = "ended";
  li.textContent = `— ${text} —`;
  $("log").append(li);
}

function scrollLog() {
  const main = document.querySelector("main");
  main.scrollTop = main.scrollHeight;
}

$("vol-1").addEventListener("click", () => setVolume(1));
$("vol-2").addEventListener("click", () => setVolume(2));
function setVolume(v) {
  volume = v;
  $("vol-1").classList.toggle("active", v === 1);
  $("vol-2").classList.toggle("active", v === 2);
}

async function ask() {
  const seed = $("seed").value.trim();
  if (!seed) return;
  $("seed").value = "";
  if (view === "room") {
    const res = await fetch("/api/ask", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ seed, volume }),
    }).then((r) => r.json());
    for (const p of res.chain ?? []) addRow(p);
    renderSidebar(res.scores ?? null);
  } else {
    const res = await fetch("/api/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ person: view, message: seed }),
    }).then((r) => r.json());
    for (const p of res.chain ?? []) addRow(p);
    renderSidebar();
  }
  scrollLog();
}

$("sim-btn").addEventListener("click", async () => {
  if (view === "room") return;
  const btn = $("sim-btn");
  btn.disabled = true;
  btn.textContent = "running…";
  try {
    const res = await fetch("/api/simulate", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ person: view, minutes: Number($("sim-mins").value) || 30 }),
    }).then((r) => r.json());
    for (const p of res.chain ?? []) addRow(p);
    addEnded(`${res.ended} · ${fmtOffset(res.sim_seconds)} simulated`);
    renderSidebar();
    scrollLog();
  } finally {
    btn.disabled = false;
    btn.textContent = "simulate";
  }
});

$("copy-chat").addEventListener("click", async () => {
  const lines = current.map((p) => {
    const d = new Date(p.observed_at);
    const t =
      d.toLocaleDateString(undefined, { month: "short", day: "numeric" }) +
      " " +
      d.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
    const dev = p.origin?.device ?? "";
    const cov = p.payload.coverage != null ? ` · ${(p.payload.coverage * 100).toFixed(0)}%` : "";
    const who = dev === "twin:cal" ? "cal" : dev.replace("twin:", "") + cov;
    return `[${t}] ${who}: ${p.payload.body}`;
  });
  await navigator.clipboard.writeText(lines.join("\n"));
  const btn = $("copy-chat");
  btn.textContent = "copied";
  setTimeout(() => (btn.textContent = "copy chat"), 1200);
});

$("ask").addEventListener("click", ask);
$("seed").addEventListener("keydown", (e) => {
  if (e.key === "Enter") ask();
});

