const { Database, Connection, VERSION } = require('@ladybugdb/core');
(async () => {
  console.log('VERSION', VERSION);
  const db = new Database('./probe.db');
  const conn = new Connection(db);
  await conn.query("CREATE NODE TABLE Person(id STRING, name STRING, PRIMARY KEY (id))");
  await conn.query("CREATE NODE TABLE Property(id STRING, label STRING, PRIMARY KEY (id))");
  await conn.query("CREATE REL TABLE AT(FROM Person TO Property, since STRING)");
  await conn.query("CREATE (p:Person {id:'p1', name:'Cal'})");
  await conn.query("CREATE (q:Property {id:'r1', label:'yard'})");
  await conn.query("MATCH (p:Person {id:'p1'}), (q:Property {id:'r1'}) CREATE (p)-[:AT {since:'2026'}]->(q)");
  const res = await conn.query("MATCH (p:Person)-[r:AT]->(q:Property) RETURN p.name, q.label, r.since");
  const rows = await res.getAll();
  console.log('rows:', JSON.stringify(rows));
  const res2 = await conn.query("MATCH (n) RETURN label(n) AS l, count(*) AS c");
  console.log('counts:', JSON.stringify(await res2.getAll()));
  console.log('methods on conn:', Object.getOwnPropertyNames(Object.getPrototypeOf(conn)).join(','));
})().catch(e => { console.error('ERR', e.message); process.exit(1); });
EOF
