// discipline that keeps rebuilds from scrambling identity — and the one that
// keeps a shared commons possible later without a re-identification project.

function hash(kind: string, value: string) {
  return kind + ":" + createHash("sha256").update(value).digest("hex").slice(0, 16);
}

export const normPhone = (s: string) => s.replace(/\D/g, "").slice(-10);
export const normText = (s: string) => s.trim().toLowerCase().replace(/\s+/g, " ");
