export const placeId = (lat: number, lng: number) =>
  hash("property", `${lat.toFixed(4)},${lng.toFixed(4)}`);

export const sessionId = (observer: string, startIso: string) =>
  hash("session", `${observer}|${startIso}`);

export const engagementId = (propertyKey: string, opened: string) =>
  hash("engagement", `${propertyKey}|${opened.slice(0, 10)}`);

