// The lake: cloud-canonical, append-only, the only source of truth.
// The hub only ever READS here. Everything downstream is a fold.

export type Packet = {
  seq: number;
  id: string;
  hash: string | null;
  kind: string;
  observed_at: string;
  received_at: string;
  observer: string;
  loc: { lat: number; lng: number; accuracy_m?: number } | null;
  payload: Record<string, unknown>;
  links: { rel: string; id: string }[];
};

const LAKE_URL =
  process.env.LAKE_URL ?? "https://.supabase.co";
const LAKE_KEY =
  process.env.LAKE_KEY ??
  "";

const HEADERS = { apikey: LAKE_KEY, Authorization: `Bearer ${LAKE_KEY}` };

// PostgREST caps at 1000 rows — page through, never truncate silently
export async function fetchAllPackets(max = 100_000): Promise<Packet[]> {
  const out: Packet[] = [];
  const page = 1000;
  for (let offset = 0; offset < max; offset += page) {
    const res = await fetch(
      `${LAKE_URL}/rest/v1/packet?select=*&order=seq.asc&limit=${page}&offset=${offset}`,
      { headers: HEADERS, cache: "no-store" }
    );
    if (!res.ok) throw new Error(`lake ${res.status}: ${await res.text()}`);
    const rows = (await res.json()) as Packet[];
    out.push(...rows);
    if (rows.length < page) break;
  }
  return out;
}

export async function lakeCount(): Promise<number> {
  const res = await fetch(`${LAKE_URL}/rest/v1/packet?select=seq&limit=1`, {
    headers: { ...HEADERS, Prefer: "count=exact" },
    cache: "no-store",
  });
  const range = res.headers.get("content-range");
  return range ? Number(range.split("/")[1]) : 0;
}

export const blobUrl = (key: string) =>
  `${LAKE_URL}/storage/v1/object/public/blobs/${key}`;

