// The fold: packets in, graph out. Pure and deterministic — the same log
// always yields the same graph. Nothing here is stored; the rebuild button
// throws the whole graph away and runs this again.

import type { Packet } from "./lake";
import { personId, placeId, sessionId } from "./ids";

export type Node = { kind: string; id: string; props: Record<string, unknown> };
export type Edge = { rel: string; from: string; to: string };

export type FoldResult = {
  nodes: Node[];
  edges: Edge[];
  stats: Record<string, number>;
};

// field capture clusters into a session when it is close in TIME and SPACE
const SESSION_GAP_MS = 30 * 60 * 1000;
const SESSION_RADIUS_M = 200;

function metersBetween(a: [number, number], b: [number, number]) {
  const R = 6371000;
  const dLat = ((b[0] - a[0]) * Math.PI) / 180;
  const dLng = ((b[1] - a[1]) * Math.PI) / 180;
  const lat = ((a[0] + b[0]) / 2) * (Math.PI / 180);
  const x = dLng * Math.cos(lat);
  return Math.sqrt(dLat * dLat + x * x) * R;
}

export function fold(packets: Packet[]): FoldResult {
  const nodes = new Map<string, Node>();
  const edges: Edge[] = [];
  const put = (kind: string, id: string, props: Record<string, unknown>) => {
    const key = `${kind}|${id}`;
    const existing = nodes.get(key);
    if (existing) Object.assign(existing.props, props);
    else nodes.set(key, { kind, id, props });
  };
  const link = (rel: string, from: string, to: string) =>
    edges.push({ rel, from, to });

  // --- observers: every distinct point of view that ever appended
  const byObserver = new Map<string, Packet[]>();
  for (const p of packets) {
    const list = byObserver.get(p.observer) ?? [];
    list.push(p);
    byObserver.set(p.observer, list);
  }
  for (const [obs, list] of byObserver) {
    put("Observer", obs, {
      name: obs,
      first_seen: list[0].observed_at,
      last_seen: list[list.length - 1].observed_at,
      packets: list.length,
    });
  }

  // --- persons: derived from claim packets ("cal.pocket" -> person cal)
  for (const p of packets) {
    if (p.kind !== "ui") continue;
    const payload = p.payload as { action?: string; name?: string };
    if (payload.action !== "claim" || !payload.name) continue;
    const person = String(payload.name).split(".")[0].toLowerCase();
    const pid = personId(person);
    put("Person", pid, { name: person, first_seen: p.observed_at });
    link("OWNS", pid, p.observer);
  }

  // --- media: the graph's handle on an observed artifact (id = packet id)
  for (const p of packets) {
    if (p.kind === "ui") continue;
    const payload = p.payload as { body?: string; blob?: string };
    put("Media", p.id, {
      kind: p.kind,
      observed_at: p.observed_at,
      blob: payload.blob ?? "",
      preview: (payload.body ?? "").slice(0, 140),
      lat: p.loc?.lat ?? 0,
      lng: p.loc?.lng ?? 0,
    });
    link("OBSERVED", p.observer, p.id);
  }

  // --- sessions: time+space clustering over located field capture.
  // Derived, never stamped. Packets with no fix can't be placed, so they
  // simply don't join a session — absence of evidence, not a guess.
  for (const [obs, list] of byObserver) {
    const located = list
      .filter((p) => p.loc && p.kind !== "ui")
      .sort((a, b) => (a.observed_at < b.observed_at ? -1 : 1));
    let cluster: Packet[] = [];
    const flush = () => {
      if (cluster.length < 2) {
        cluster = [];
        return;
      }
      const start = cluster[0].observed_at;
      const sid = sessionId(obs, start);
      const lat =
        cluster.reduce((s, p) => s + (p.loc?.lat ?? 0), 0) / cluster.length;
      const lng =
        cluster.reduce((s, p) => s + (p.loc?.lng ?? 0), 0) / cluster.length;
      put("Session", sid, {
        started_at: start,
        ended_at: cluster[cluster.length - 1].observed_at,
        packets: cluster.length,
        lat,
        lng,
      });
      link("SESSION_BY", sid, obs);
      const prop = placeId(lat, lng);
      put("Property", prop, {
        label: `${lat.toFixed(4)}, ${lng.toFixed(4)}`,
        address: "",
        lat,
        lng,
      });
      link("SESSION_AT", sid, prop);
      for (const p of cluster) link("IN_SESSION", p.id, sid);
      cluster = [];
    };
    for (const p of located) {
      if (!cluster.length) {
        cluster = [p];
        continue;
      }
      const prev = cluster[cluster.length - 1];
      const dt =
        new Date(p.observed_at).getTime() - new Date(prev.observed_at).getTime();
      const dm = metersBetween(
        [prev.loc!.lat, prev.loc!.lng],
        [p.loc!.lat, p.loc!.lng]
      );
      if (dt <= SESSION_GAP_MS && dm <= SESSION_RADIUS_M) cluster.push(p);
      else {
        flush();
        cluster = [p];
      }
    }
    flush();
  }

  const stats: Record<string, number> = { packets: packets.length };
  for (const n of nodes.values()) stats[n.kind] = (stats[n.kind] ?? 0) + 1;
  stats.edges = edges.length;

  return { nodes: [...nodes.values()], edges, stats };
}

