export const runtime = "nodejs";

// Direct Cypher against the twin — the debugging window into the brain.
export async function POST(request: Request) {
  try {
    const { cypher } = (await request.json()) as { cypher?: string };
    if (!cypher?.trim()) return Response.json({ rows: [] });
    const rows = await query(cypher);
    return Response.json({ rows: rows.slice(0, 200), total: rows.length });
  } catch (e) {
    return Response.json(
      { error: e instanceof Error ? e.message : String(e) },
      { status: 400 }
    );
  }
}

