"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";

// The rebuild button: throw the entire graph away and re-fold it from the
// log. Designed for seven generations, never shipped until now.
export function RebuildButton({ onDone }: { onDone?: () => void }) {
  const [busy, setBusy] = useState(false);
  const [note, setNote] = useState<string | null>(null);

  async function run() {
    setBusy(true);
    setNote(null);
    try {
      const res = await fetch("/api/rebuild", { method: "POST" });
      const data = await res.json();
      setNote(
        data.ok
          ? `rebuilt in ${(data.ms / 1000).toFixed(1)}s · ${data.stats.packets} packets folded`
          : `failed: ${data.error}`
      );
      onDone?.();
    } catch (e) {
      setNote(e instanceof Error ? e.message : String(e));
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="flex items-center gap-3">
      {note && <span className="text-xs text-muted-foreground">{note}</span>}
      <Button onClick={run} disabled={busy} size="sm">
        {busy ? "folding…" : "Rebuild graph"}
      </Button>
    </div>
  );
}

