"use client";

import { useCallback, useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { RebuildButton } from "@/components/rebuild-button";
import { KIND_COLOR } from "@/lib/ontology";

type Stats = {
  built: boolean;
  counts: Record<string, number>;
  packets: number;
  lastBuild: { at: string; ms: number } | null;
};

export default function Overview() {
  const [stats, setStats] = useState<Stats | null>(null);

  const load = useCallback(() => {
    fetch("/api/stats")
      .then((r) => r.json())
      .then(setStats)
      .catch(() => {});
  }, []);

  useEffect(load, [load]);

  return (
    <div className="p-8">
      <header className="mb-8 flex items-start justify-between">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">Overview</h1>
          <p className="text-sm text-muted-foreground">
            {stats?.packets?.toLocaleString() ?? "—"} packets in the lake ·{" "}
            {stats?.built ? "graph built" : "no graph yet"}
            {stats?.lastBuild
              ? ` · last fold ${(stats.lastBuild.ms / 1000).toFixed(1)}s`
              : ""}
          </p>
        </div>
        <RebuildButton onDone={load} />
      </header>

      <div className="grid grid-cols-2 gap-4 md:grid-cols-3 lg:grid-cols-5">
        {Object.entries(stats?.counts ?? {}).map(([kind, count]) => (
          <Card key={kind}>
            <CardHeader className="pb-2">
              <CardTitle className="flex items-center gap-2 text-sm font-medium text-muted-foreground">
                <span
                  className="inline-block size-2.5 rounded-full"
                  style={{ background: KIND_COLOR[kind] }}
                />
                {kind}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-3xl font-semibold tabular-nums">
                {count.toLocaleString()}
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {!stats?.built && (
        <p className="mt-8 max-w-xl text-sm text-muted-foreground">
          The graph is empty. Nothing is lost — it is a projection, not a
          record. Press <span className="font-medium">Rebuild graph</span> and
          every packet in the lake will be folded into entities again.
        </p>
      )}
    </div>
  );
}

