input.content:
"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { RebuildButton } from "@/components/rebuild-button";
import { KIND_COLOR } from "@/lib/ontology";

type GNode = { id: string; kind: string; label: string };
type GEdge = { rel: string; from: string; to: string };
type Sim = GNode & { x: number; y: number; vx: number; vy: number };

export default function GraphPage() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const simRef = useRef<{ nodes: Sim[]; edges: GEdge[] }>({ nodes: [], edges: [] });
  const viewRef = useRef({ x: 0, y: 0, k: 1 });
  const [hover, setHover] = useState<Sim | null>(null);
  const [meta, setMeta] = useState({ nodes: 0, edges: 0, dropped: 0 });

  const load = useCallback(async () => {
    const data = (await fetch("/api/graph").then((r) => r.json())) as {
      nodes: GNode[];
      edges: GEdge[];
      dropped: number;
    };
    const R = 260;
    simRef.current = {
      nodes: data.nodes.map((n, i) => {
        const a = (i / Math.max(1, data.nodes.length)) * Math.PI * 2;
        return { ...n, x: Math.cos(a) * R, y: Math.sin(a) * R, vx: 0, vy: 0 };
      }),
      edges: data.edges,
    };
    setMeta({
      nodes: data.nodes.length,
      edges: data.edges.length,
      dropped: data.dropped,
    });
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  // hand-rolled force layout: repulsion, springs, gravity. No dependencies.
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d")!;
    let raf = 0;

    const resize = () => {
      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };
    resize();
    window.addEventListener("resize", resize);

    const step = () => {
      const { nodes, edges } = simRef.current;
      const index = new Map(nodes.map((n) => [n.id, n]));

      for (let i = 0; i < nodes.length; i++) {
        const a = nodes[i];
        for (let j = i + 1; j < nodes.length; j++) {
          const b = nodes[j];
          let dx = b.x - a.x;
          let dy = b.y - a.y;
          let d2 = dx * dx + dy * dy;
          if (d2 < 1) {
            dx = Math.random() - 0.5;
            dy = Math.random() - 0.5;
            d2 = 1;
          }
          const f = 900 / d2;
          const d = Math.sqrt(d2);
          a.vx -= (dx / d) * f;
          a.vy -= (dy / d) * f;
          b.vx += (dx / d) * f;
          b.vy += (dy / d) * f;
        }
      }
      for (const e of edges) {
        const a = index.get(e.from);
        const b = index.get(e.to);
        if (!a || !b) continue;
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const d = Math.max(1, Math.hypot(dx, dy));
        const f = (d - 70) * 0.008;
        a.vx += (dx / d) * f;
        a.vy += (dy / d) * f;
        b.vx -= (dx / d) * f;
        b.vy -= (dy / d) * f;
      }
      for (const n of nodes) {
        n.vx -= n.x * 0.0016;
        n.vy -= n.y * 0.0016;
        n.vx *= 0.86;
        n.vy *= 0.86;
        n.x += n.vx;
        n.y += n.vy;
      }

      const rect = canvas.getBoundingClientRect();
      const { x: ox, y: oy, k } = viewRef.current;
      ctx.clearRect(0, 0, rect.width, rect.height);
      ctx.save();
      ctx.translate(rect.width / 2 + ox, rect.height / 2 + oy);
      ctx.scale(k, k);

      ctx.strokeStyle = "rgba(127,127,127,0.28)";
      ctx.lineWidth = 1 / k;
      ctx.beginPath();
      for (const e of edges) {
        const a = index.get(e.from);
        const b = index.get(e.to);
        if (!a || !b) continue;
        ctx.moveTo(a.x, a.y);
        ctx.lineTo(b.x, b.y);
      }
      ctx.stroke();

      for (const n of nodes) {
        const r = n.kind === "Media" ? 3 : n.kind === "Person" ? 9 : 6;
        ctx.fillStyle = KIND_COLOR[n.kind] ?? "#888";
        ctx.beginPath();
        ctx.arc(n.x, n.y, r, 0, Math.PI * 2);
        ctx.fill();
        if (n.kind !== "Media" && k > 0.55) {
          ctx.fillStyle = "rgba(140,140,150,0.95)";
          ctx.font = `${11 / k}px ui-sans-serif, system-ui`;
          ctx.fillText(n.label || n.kind, n.x + r + 3 / k, n.y + 3 / k);
        }
      }
      ctx.restore();
      raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);

    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", resize);
    };
  }, []);

  // pan, zoom, hover
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    let dragging = false;
    let last = { x: 0, y: 0 };

    const toWorld = (ev: MouseEvent) => {
      const rect = canvas.getBoundingClientRect();
      const { x: ox, y: oy, k } = viewRef.current;
      return {
        x: (ev.clientX - rect.left - rect.width / 2 - ox) / k,
        y: (ev.clientY - rect.top - rect.height / 2 - oy) / k,
      };
    };
    const onDown = (ev: MouseEvent) => {
      dragging = true;
      last = { x: ev.clientX, y: ev.clientY };
    };
    const onUp = () => (dragging = false);
    const onMove = (ev: MouseEvent) => {
      if (dragging) {
        viewRef.current.x += ev.clientX - last.x;
        viewRef.current.y += ev.clientY - last.y;
        last = { x: ev.clientX, y: ev.clientY };
        return;
      }
      const p = toWorld(ev);
      let best: Sim | null = null;
      let bestD = 14;
      for (const n of simRef.current.nodes) {
        const d = Math.hypot(n.x - p.x, n.y - p.y);
        if (d < bestD) {
          best = n;
          bestD = d;
        }
      }
      setHover(best);
    };
    const onWheel = (ev: WheelEvent) => {
      ev.preventDefault();
      const k = viewRef.current.k * (ev.deltaY < 0 ? 1.1 : 0.9);
      viewRef.current.k = Math.min(4, Math.max(0.2, k));
    };
    canvas.addEventListener("mousedown", onDown);
    window.addEventListener("mouseup", onUp);
    canvas.addEventListener("mousemove", onMove);
    canvas.addEventListener("wheel", onWheel, { passive: false });
    return () => {
      canvas.removeEventListener("mousedown", onDown);
      window.removeEventListener("mouseup", onUp);
      canvas.removeEventListener("mousemove", onMove);
      canvas.removeEventListener("wheel", onWheel);
    };
  }, []);

  return (
    <div className="flex h-screen flex-col">
      <header className="flex items-start justify-between gap-6 border-b p-6">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">The graph</h1>
          <p className="text-sm text-muted-foreground">
            {meta.nodes} nodes · {meta.edges} edges
            {meta.dropped > 0 && ` · ${meta.dropped.toLocaleString()} media not drawn`}
            {" · drag to pan, scroll to zoom"}
          </p>
        </div>
        <RebuildButton onDone={load} />
      </header>

      <div className="flex min-h-0 flex-1">
        <canvas ref={canvasRef} className="min-w-0 flex-1 cursor-grab" />
        <div className="w-64 shrink-0 border-l p-4">
          <div className="mb-4 space-y-1.5">
            {Object.entries(KIND_COLOR).map(([kind, color]) => (
              <div key={kind} className="flex items-center gap-2 text-xs">
                <span
                  className="inline-block size-2.5 rounded-full"
                  style={{ background: color }}
                />
                <span className="text-muted-foreground">{kind}</span>
              </div>
            ))}
          </div>
          {hover && (
            <div className="rounded-md border p-3">
              <div className="text-xs font-semibold" style={{ color: KIND_COLOR[hover.kind] }}>
                {hover.kind}
              </div>
              <div className="mt-1 break-words text-sm">{hover.label || "—"}</div>
              <div className="mt-2 break-all font-mono text-[10px] text-muted-foreground">
                {hover.id}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

