input.content:
"use client";

import { useEffect, useState } from "react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";

// A CRM screen is a lens: one Cypher walk, rendered as a boring table.
const CYPHER = `
MATCH (s:Session)-[:SESSION_BY]->(o:Observer)
OPTIONAL MATCH (s)-[:SESSION_AT]->(p:Property)
RETURN s.started_at AS started, s.ended_at AS ended, s.packets AS packets,
       o.name AS observer, p.label AS place
ORDER BY started DESC LIMIT 100`;

type Row = Record<string, string | number | null>;

export default function Sessions() {
  const [rows, setRows] = useState<Row[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetch("/api/query", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ cypher: CYPHER }),
    })
      .then((r) => r.json())
      .then((d) => (d.error ? setError(d.error) : setRows(d.rows ?? [])))
      .catch((e) => setError(String(e)));
  }, []);

  const dur = (a: string, b: string) => {
    const ms = new Date(b).getTime() - new Date(a).getTime();
    const m = Math.round(ms / 60000);
    return m >= 60 ? `${Math.floor(m / 60)}h ${m % 60}m` : `${m}m`;
  };

  return (
    <div className="p-8">
      <header className="mb-6">
        <h1 className="text-2xl font-semibold tracking-tight">Sessions</h1>
        <p className="text-sm text-muted-foreground">
          Derived by clustering field capture in time and space — never stamped,
          always recomputed. {rows.length} shown.
        </p>
      </header>

      {error && (
        <p className="mb-4 rounded-md border border-destructive/40 p-3 text-sm text-destructive">
          {error} — try rebuilding the graph.
        </p>
      )}

      <div className="rounded-md border">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Started</TableHead>
              <TableHead>Duration</TableHead>
              <TableHead className="text-right">Packets</TableHead>
              <TableHead>Observer</TableHead>
              <TableHead>Place</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {rows.map((r, i) => (
              <TableRow key={i}>
                <TableCell className="whitespace-nowrap font-medium">
                  {new Date(String(r.started)).toLocaleString()}
                </TableCell>
                <TableCell className="text-muted-foreground">
