"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";

const EXAMPLES = [
  "MATCH (o:Observer) RETURN o.name, o.packets ORDER BY o.packets DESC",
  "MATCH (p:Person)-[:OWNS]->(o:Observer) RETURN p.name, o.name",
  "MATCH (m:Media)-[:IN_SESSION]->(s:Session) RETURN s.started_at, m.kind, m.preview LIMIT 25",
  "MATCH (s:Session)-[:SESSION_AT]->(p:Property) RETURN p.label, count(s) AS sessions",
];

export default function QueryPage() {
  const [cypher, setCypher] = useState(EXAMPLES[0]);
  const [rows, setRows] = useState<Record<string, unknown>[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  async function run(q = cypher) {
    setBusy(true);
    setError(null);
    try {
      const d = await fetch("/api/query", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ cypher: q }),
      }).then((r) => r.json());
      if (d.error) {
        setError(d.error);
        setRows([]);
      } else setRows(d.rows ?? []);
    } finally {
      setBusy(false);
    }
  }

  const cols = rows.length ? Object.keys(rows[0]) : [];

  return (
    <div className="p-8">
      <header className="mb-6">
        <h1 className="text-2xl font-semibold tracking-tight">Cypher</h1>
        <p className="text-sm text-muted-foreground">
          Walk the twin directly. Every CRM screen is one of these underneath.
        </p>
      </header>

      <textarea
        value={cypher}
        onChange={(e) => setCypher(e.target.value)}
        spellCheck={false}
        className="h-28 w-full rounded-md border bg-transparent p-3 font-mono text-sm"
      />
      <div className="mt-3 flex flex-wrap items-center gap-2">
        <Button size="sm" onClick={() => run()} disabled={busy}>
          {busy ? "walking…" : "Run"}
        </Button>
        {EXAMPLES.map((e, i) => (
          <button
            key={i}
            onClick={() => {
              setCypher(e);
              run(e);
            }}
            className="rounded-full border px-3 py-1 text-xs text-muted-foreground hover:text-foreground"
          >
            example {i + 1}
          </button>
        ))}
      </div>

      {error && (
        <pre className="mt-4 overflow-x-auto rounded-md border border-destructive/40 p-3 text-xs text-destructive">
          {error}
        </pre>
      )}

      {rows.length > 0 && (
        <div className="mt-6 overflow-x-auto rounded-md border">
          <table className="w-full text-sm">
            <thead className="bg-muted/50">
              <tr>
                {cols.map((c) => (
                  <th key={c} className="p-2 text-left font-medium">
                    {c}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map((r, i) => (
                <tr key={i} className="border-t">
                  {cols.map((c) => (
                    <td key={c} className="max-w-md truncate p-2 font-mono text-xs">
                      {String(r[c] ?? "")}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

