// THE ONTOLOGY. This file is the only place the shape of the world is
// declared. Being wrong here costs one edit and one rebuild — never a
// migration — because the graph is a disposable fold over the packet log.
//
// Nouns (Cal's v1): person, property, account, engagement, shift, contract,
// media. Plus two the packet model requires: observer (a point of view with
// a queue) and session (a derived cluster of field capture — never stamped,
// always derived; a stage is never a column).

export type Col = "STRING" | "DOUBLE" | "INT64";

export const NODES: Record<string, Record<string, Col>> = {
  Person: {
    id: "STRING",
    name: "STRING",
    phone: "STRING",
    email: "STRING",
    first_seen: "STRING",
  },
  Property: {
    id: "STRING",
    label: "STRING",
    address: "STRING",
    lat: "DOUBLE",
    lng: "DOUBLE",
  },
  Account: { id: "STRING", label: "STRING", kind: "STRING" },
  Engagement: { id: "STRING", label: "STRING", opened_at: "STRING" },
  Shift: { id: "STRING", started_at: "STRING", ended_at: "STRING" },
  Contract: {
    id: "STRING",
    label: "STRING",
    signed_at: "STRING",
    amount: "DOUBLE",
  },
  Media: {
    id: "STRING",
    kind: "STRING",
    observed_at: "STRING",
    blob: "STRING",
    preview: "STRING",
    lat: "DOUBLE",
    lng: "DOUBLE",
  },
  Observer: {
    id: "STRING",
    name: "STRING",
    first_seen: "STRING",
    last_seen: "STRING",
    packets: "INT64",
  },
  Session: {
    id: "STRING",
    started_at: "STRING",
    ended_at: "STRING",
    packets: "INT64",
    lat: "DOUBLE",
    lng: "DOUBLE",
  },
};

export const RELS: Record<string, [string, string]> = {
  OWNS: ["Person", "Observer"], // a person's senses
  OBSERVED: ["Observer", "Media"], // what crossed a membrane
  IN_SESSION: ["Media", "Session"], // derived clusters of field capture
  SESSION_BY: ["Session", "Observer"],
  SESSION_AT: ["Session", "Property"],
  PART_OF: ["Session", "Engagement"], // the business shape
  FOR_PROPERTY: ["Engagement", "Property"],
  WITH_PERSON: ["Engagement", "Person"],
  WORKED: ["Person", "Shift"],
  SHIFT_ON: ["Shift", "Engagement"],
  SIGNED: ["Person", "Contract"],
  COVERS: ["Contract", "Engagement"],
  HOLDS: ["Person", "Account"],
  CHARGED: ["Contract", "Account"],
};

export const nodeColumns = (kind: string) => Object.keys(NODES[kind]);

export const DDL: string[] = [
  ...Object.entries(NODES).map(
    ([kind, cols]) =>
      `CREATE NODE TABLE ${kind}(${Object.entries(cols)
        .map(([c, t]) => `${c} ${t}`)
        .join(", ")}, PRIMARY KEY (id))`
  ),
  ...Object.entries(RELS).map(
    ([rel, [from, to]]) => `CREATE REL TABLE ${rel}(FROM ${from} TO ${to})`
  ),
];

export const ENTITY_KINDS = Object.keys(NODES);

export const KIND_COLOR: Record<string, string> = {
  Person: "#a855f7",
  Property: "#14b8a6",
  Account: "#f59e0b",
  Engagement: "#3b82f6",
  Shift: "#ec4899",
  Contract: "#ef4444",
  Media: "#22c55e",
  Observer: "#eab308",
  Session: "#8b5cf6",
};

