toolUseResult.originalFile:
import { query, ready } from "@/lib/graph";
import { ENTITY_KINDS, RELS } from "@/lib/ontology";

export const runtime = "nodejs";

// The viewer needs a legible subgraph, not the whole lake. Structural nodes
// are always included; Media is sampled. What was dropped is reported — a
// silent cap reads as "you're seeing everything" when you aren't.
export async function GET(request: Request) {
  if (!(await ready())) return Response.json({ nodes: [], edges: [], dropped: 0 });
  const url = new URL(request.url);
  const mediaCap = Number(url.searchParams.get("media") ?? 120);

  const nodes: { id: string; kind: string; label: string }[] = [];
  let dropped = 0;

  for (const kind of ENTITY_KINDS) {
    const labelCol =
      kind === "Media"
        ? "n.kind"
        : kind === "Session"
          ? "n.started_at"
          : kind === "Observer" || kind === "Person" || kind === "Property"
            ? "n.name"
            : "n.label";
    const cap = kind === "Media" ? mediaCap : 5000;
    const rows = await query(
      `MATCH (n:${kind}) RETURN n.id AS id, ${
        kind === "Property" ? "n.label" : labelCol
      } AS label LIMIT ${cap}`
    );
    for (const r of rows)
      nodes.push({
        id: String(r.id),
        kind,
        label: String(r.label ?? "").slice(0, 40),
      });
    if (kind === "Media") {
      const total = await query(`MATCH (n:Media) RETURN count(*) AS c`);
      dropped = Math.max(0, Number(total[0]?.c ?? 0) - rows.length);
    }
  }

  const have = new Set(nodes.map((n) => n.id));
  const edges: { rel: string; from: string; to: string }[] = [];
  for (const rel of Object.keys(RELS)) {
    const rows = await query(
      `MATCH (a)-[:${rel}]->(b) RETURN a.id AS from, b.id AS to LIMIT 4000`
    );
    for (const r of rows) {
      const from = String(r.from);
      const to = String(r.to);
      if (have.has(from) && have.has(to)) edges.push({ rel, from, to });
    }
  }

  return Response.json({ nodes, edges, dropped });
}

