export async function query(cypher: string): Promise<Record<string, unknown>[]> {
  const conn = await open();
  const res = await conn.query(cypher);
  const rows = (await res.getAll()) as Record<string, unknown>[];
  // Ladybug returns INT64 aggregates as BigInt, which JSON can't serialize
  return rows.map((row) =>
    Object.fromEntries(
      Object.entries(row).map(([k, v]) => [
        k,
        typeof v === "bigint" ? Number(v) : v,
      ])
    )
  );
}

