// The twin. An embedded Ladybug database holding the derived graph.
// It is DISPOSABLE by design: rebuild() deletes the whole file and re-folds
// from the lake. Nothing of value is ever stored only here.

import { rm, mkdir, writeFile } from "fs/promises";
import path from "path";
import { DDL, NODES, RELS, nodeColumns } from "./ontology";
import { fetchAllPackets } from "./lake";
import { fold, type Edge, type Node } from "./fold";

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Conn = any;

const DB_DIR = path.join(process.cwd(), ".data");
const DB_PATH = path.join(DB_DIR, "graph.db");

type Held = {
  conn: Conn | null;
  built: { at: string; ms: number; stats: Record<string, number> } | null;
  building: boolean;
};

const held: Held = ((globalThis as Record<string, unknown>).__twin as Held) ?? {
  conn: null,
  built: null,
  building: false,
};
(globalThis as Record<string, unknown>).__twin = held;

async function open(fresh = false): Promise<Conn> {
  if (held.conn && !fresh) return held.conn;
  const { Database, Connection } = await import("@ladybugdb/core");
  if (fresh) {
    if (held.conn) {
      try {
        await held.conn.close();
      } catch {}
      held.conn = null;
    }
    await rm(DB_PATH, { recursive: true, force: true });
    await rm(DB_PATH + ".wal", { force: true });
  }
  await mkdir(DB_DIR, { recursive: true });
  const db = new Database(DB_PATH);
  const conn = new Connection(db);
  held.conn = conn;
  return conn;
}

export function lastBuild() {
  return held.built;
}
export function isBuilding() {
  return held.building;
}

// Bulk load via COPY — orders of magnitude faster than statement-per-row.
const csvCell = (v: unknown) => {
  if (typeof v === "number") return String(Number.isFinite(v) ? v : 0);
  // newlines collapse to spaces: the parallel CSV reader can't take quoted
  // newlines, and a preview is a single line by definition
  const s = String(v ?? "").replace(/[\r\n\t]+/g, " ");
  return /[",]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

async function copyNodes(conn: Conn, nodes: Node[], dir: string) {
  const byKind = new Map<string, Node[]>();
  for (const n of nodes) {
    const list = byKind.get(n.kind) ?? [];
    list.push(n);
    byKind.set(n.kind, list);
  }
  for (const [kind, list] of byKind) {
    if (!NODES[kind]) continue;
    const cols = nodeColumns(kind);
    const lines = list.map((n) =>
      cols
        .map((c) => csvCell(c === "id" ? n.id : n.props[c] ?? (NODES[kind][c] === "STRING" ? "" : 0)))
        .join(",")
    );
    const file = path.join(dir, `${kind}.csv`);
    await writeFile(file, lines.join("\n") + "\n");
    await conn.query(`COPY ${kind} FROM '${file}' (HEADER=false)`);
  }
}

async function copyEdges(conn: Conn, edges: Edge[], nodes: Node[], dir: string) {
  const kindOf = new Map(nodes.map((n) => [n.id, n.kind]));
  const byRel = new Map<string, Edge[]>();
  for (const e of edges) {
    const spec = RELS[e.rel];
    if (!spec) continue;
    if (kindOf.get(e.from) !== spec[0] || kindOf.get(e.to) !== spec[1]) continue;
    const list = byRel.get(e.rel) ?? [];
    list.push(e);
    byRel.set(e.rel, list);
  }
  for (const [rel, list] of byRel) {
    const lines = list.map((e) => `${csvCell(e.from)},${csvCell(e.to)}`);
    const file = path.join(dir, `rel_${rel}.csv`);
    await writeFile(file, lines.join("\n") + "\n");
    await conn.query(`COPY ${rel} FROM '${file}' (HEADER=false)`);
  }
}

// THE REBUILD BUTTON. Drop the graph, re-fold every packet, start again.
export async function rebuild() {
  if (held.building) throw new Error("already rebuilding");
  held.building = true;
  const t0 = Date.now();
  try {
    const packets = await fetchAllPackets();
    const folded = fold(packets);
    const conn = await open(true);
    for (const ddl of DDL) await conn.query(ddl);
    const staging = path.join(DB_DIR, "staging");
    await mkdir(staging, { recursive: true });
    await copyNodes(conn, folded.nodes, staging);
    await copyEdges(conn, folded.edges, folded.nodes, staging);
    await rm(staging, { recursive: true, force: true });
    held.built = {
      at: new Date().toISOString(),
      ms: Date.now() - t0,
      stats: folded.stats,
    };
    return held.built;
  } finally {
    held.building = false;
  }
}

export async function query(cypher: string): Promise<Record<string, unknown>[]> {
  const conn = await open();
  const res = await conn.query(cypher);
  return (await res.getAll()) as Record<string, unknown>[];
}

export async function ready() {
  try {
    await query("MATCH (n:Observer) RETURN count(*) AS c");
    return true;
  } catch {
    return false;
  }
}

