#!/usr/bin/env python3
"""twin — a local seance over chat.db. Fully offline; nothing leaves this machine.

Each person is a DIALOGUE fold: the full two-voice history of your 1:1
thread, woven into one stream with speaker tokens — §me§ before every
message you sent, §them§ before every message they sent, in true time
order. The model learns turn-taking itself: a reply ends when the model
predicts it's your turn again; a mid-walk §them§ is another bubble in a
burst, exactly as they actually text.

Two ways to talk:
  the room — coverage-arbitration across everyone (who hears you loudest answers)
  chats    — iMessage-style 1:1 with any person; your back-and-forth feeds
             their model as labeled growth, so the session propagates

The log (twin-log.ndjson) is local append-only ndjson. Origins never lie:
bedrock (real archive) and growth (twin talk) stay separate strata.

Run from YOUR terminal (it holds Full Disk Access):
    python3 twin.py --list        # top contacts
    python3 twin.py               # seat the top 20, uncurated
    python3 twin.py "Mum" "Fynn"  # or summon by name
Then open http://localhost:8362
"""

import argparse
import glob
import json
import random
import re
import sqlite3
import sys
import uuid
from collections import Counter, defaultdict
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, HTTPServer
from pathlib import Path
from urllib.parse import parse_qs, urlparse

HERE = Path(__file__).parent
LOG_PATH = HERE / "twin-log.ndjson"
ME = "§me§"
THEM = "§them§"
SILENCE = "…"

# ---------------------------------------------------------------- the fold

def tokenize(s):
    return re.findall(r"[a-z0-9']+", s.lower())


class Dialogue:
    """A two-voice Markov fold with learned turn-taking."""

    def __init__(self):
        self.tri = defaultdict(Counter)
        self.bi = defaultdict(Counter)
        self.uni = Counter()
        self.words = 0
        self.bedrock = 0
        self.growth = 0
        self._prev = []  # rolling 2-token tail so cross-message transitions count
        # adjacency pairs: responder from_me -> [(prompt token set, reply opening)]
        self.pairs = {True: [], False: []}
        self._burst = set()
        self._burst_fm = None

    def feed(self, from_me, body, growth=False, weight=1.0):
        toks = [ME if from_me else THEM] + tokenize(body)
        if len(toks) == 1:
            return
        # adjacency pairs: on a speaker flip, the previous burst is the prompt
        # this reply answered — recorded so replies can be conditioned on
        # messages LIKE yours, not just your final word
        if self._burst_fm is not None and from_me != self._burst_fm and self._burst:
            self.pairs[from_me].append((frozenset(self._burst), toks[1:3]))
            self._burst = set()
        if from_me != self._burst_fm:
            self._burst = set()
        self._burst |= set(toks[1:])
        self._burst_fm = from_me
        seq = self._prev + toks
        for i in range(len(self._prev), len(seq)):
            w = seq[i]
            if w not in (ME, THEM):
                self.uni[w] += weight
                self.words += 1
            if i >= 1:
                self.bi[seq[i - 1]][w] += weight
            if i >= 2:
                self.tri[(seq[i - 2], seq[i - 1])][w] += weight
        self._prev = seq[-2:]
        if growth:
            self.growth += 1
        else:
            self.bedrock += 1

    def coverage(self, text):
        toks = tokenize(text)
        if not toks or not self.uni:
            return 0.0
        vocab = sum(1 for w in toks if w in self.uni) / len(toks)
        trans_total = max(1, len(toks) - 1)
        trans = sum(1 for i in range(1, len(toks)) if toks[i] in self.bi.get(toks[i - 1], ())) / trans_total
        return round(0.5 * vocab + 0.5 * trans, 4)

    def retrieve(self, prompt_toks, responder_fm):
        """Find how this speaker actually opened replies to messages like
        this one: best adjacency pair by rare-word overlap (IDF-weighted)."""
        prompt = set(prompt_toks)
        best, best_score = None, 0.0
        for pset, opening in self.pairs[responder_fm]:
            shared = prompt & pset
            if not shared:
                continue
            score = sum(1.0 / (1 + self.uni.get(w, 0)) for w in shared)
            if score > best_score:
                best, best_score = opening, score
        return best or []

    def reply(self, seed_toks, as_them=True, max_tokens=150, prompt_toks=None):
        """Walk from a seed that ends with the speaker's token; stop when the
        model predicts the OTHER speaker (turn over); the same speaker token
        mid-walk starts another bubble in a burst. If a prompt is given, the
        walk opens with how this speaker actually answered similar messages."""
        speak = THEM if as_them else ME
        yield_tok = ME if as_them else THEM
        toks = list(seed_toks)
        bubbles = [[]]
        if prompt_toks:
            for w in self.retrieve(prompt_toks, not as_them):
                bubbles[-1].append(w)
                toks.append(w)
        for _ in range(max_tokens):
            w2 = toks[-1]
            w1 = toks[-2] if len(toks) >= 2 else None
            dist = (self.tri.get((w1, w2)) if w1 else None) or self.bi.get(w2) or self.uni
            if not dist:
                break
            nxt = random.choices(list(dist.keys()), weights=list(dist.values()))[0]
            if nxt == yield_tok:
                break
            if nxt == speak:
                if bubbles[-1]:
                    bubbles.append([])
                toks.append(nxt)
                continue
            bubbles[-1].append(nxt)
            toks.append(nxt)
        return [" ".join(b) for b in bubbles if b]

# ------------------------------------------------------------- the sources

def digits(s):
    return re.sub(r"\D", "", s or "")


def decode_attributed(blob):
    if not blob:
        return None
    try:
        s = blob.split(b"NSString")[1][5:]
        if s[0] == 0x81:
            length = int.from_bytes(s[1:3], "little")
            start = 3
        else:
            length = s[0]
            start = 1
        return s[start:start + length].decode("utf-8", errors="ignore") or None
    except Exception:
        return None


def find_db(explicit):
    for p in ([Path(explicit)] if explicit else []) + [Path("/tmp/chat.db"), Path.home() / "Library/Messages/chat.db"]:
        if p and p.exists():
            return p
    sys.exit("no chat.db found (copy to /tmp or grant Full Disk Access)")


def load_contacts(explicit):
    names = {}
    if explicit:
        paths = [explicit]
    else:
        base = Path.home() / "Library/Application Support/AddressBook"
        paths = glob.glob(str(base / "**" / "AddressBook-v22.abcddb"), recursive=True)
    for db in paths:
        try:
            con = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
            cur = con.cursor()
            for first, last, num in cur.execute(
                "SELECT r.ZFIRSTNAME, r.ZLASTNAME, p.ZFULLNUMBER "
                "FROM ZABCDPHONENUMBER p JOIN ZABCDRECORD r ON p.ZOWNER = r.Z_PK"):
                name = " ".join(x for x in (first, last) if x)
                if name and num:
                    names[digits(num)[-10:]] = name
            for first, last, email in cur.execute(
                "SELECT r.ZFIRSTNAME, r.ZLASTNAME, e.ZADDRESS "
                "FROM ZABCDEMAILADDRESS e JOIN ZABCDRECORD r ON e.ZOWNER = r.Z_PK"):
                name = " ".join(x for x in (first, last) if x)
                if name and email:
                    names[email.lower()] = name
            con.close()
        except Exception:
            continue
    return names


def resolve(handle, contacts):
    h = handle or ""
    if "@" in h:
        return contacts.get(h.lower())
    return contacts.get(digits(h)[-10:])


def load_people(db_path, contacts):
    """person -> chronologically sorted [(date, from_me, body)] from 1:1 chats.
    Both voices recovered: sent messages are found via chat_message_join
    (macOS often files them with a null handle)."""
    con = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
    cur = con.cursor()
    handles = dict(cur.execute("SELECT ROWID, id FROM handle"))
    chat_handles = defaultdict(set)
    for chat_id, hid in cur.execute("SELECT chat_id, handle_id FROM chat_handle_join"):
        chat_handles[chat_id].add(hid)

    people = defaultdict(list)
    for chat_id, hids in chat_handles.items():
        if len(hids) != 1:
            continue  # group chats sit out v1
        name = resolve(handles.get(next(iter(hids))), contacts) or handles.get(next(iter(hids)))
        if not name:
            continue
        for from_me, text, ab, date in cur.execute(
            "SELECT m.is_from_me, m.text, m.attributedBody, m.date "
            "FROM message m JOIN chat_message_join j ON j.message_id = m.ROWID "
            "WHERE j.chat_id = ? AND m.associated_message_type = 0 ORDER BY m.date",
            (chat_id,)):
            body = (text or decode_attributed(ab) or "").strip()
            if body:
                people[name].append((date, bool(from_me), body))
    con.close()
    for name in people:
        people[name].sort(key=lambda t: t[0])
    return people

# ---------------------------------------------------------------- the log

def append_log(origin, body, extra=None):
    packet = {
        "id": str(uuid.uuid4()),
        "kind": "text",
        "observed_at": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"),
        "origin": {"device": origin},
        "payload": {"body": body, **(extra or {})},
        "links": [],
    }
    with open(LOG_PATH, "a") as f:
        f.write(json.dumps(packet) + "\n")
    return packet


def read_log():
    if not LOG_PATH.exists():
        return []
    out = []
    for line in LOG_PATH.read_text().splitlines():
        try:
            out.append(json.loads(line))
        except Exception:
            continue
    return out

# -------------------------------------------------------------- the seance

class Seance:
    def __init__(self, people, chosen):
        self.msgs = {name: people[name] for name in chosen}
        self.experts = {}
        self.era = {}   # name -> halflife_days (0 = timeless)
        self.gaps = {}  # name -> {from_me: [reply latencies in seconds]}
        import time as _time
        self._now = _time.time()
        for name in chosen:
            g = {True: [], False: []}
            prev_date, prev_fm = None, None
            for date, from_me, _ in people[name]:
                secs = date / 1e9 if date > 1e15 else date
                if prev_date is not None and from_me != prev_fm:
                    g[from_me].append(max(1.0, secs - prev_date))
                prev_date, prev_fm = secs, from_me
            self.gaps[name] = g
            self.era[name] = 0
            self.experts[name] = self._build(name, 0)
        self.name_toks = {n: set(tokenize(str(n))) for n in chosen}

    # Era-weighted rebuild: bedrock counts decay by half-life (0 = timeless);
    # the log growth strata replay hot so past sessions stay loud.
    def _build(self, name, halflife_days):
        d = Dialogue()
        for date, from_me, body in self.msgs[name]:
            secs = date / 1e9 if date > 1e15 else date
            if halflife_days:
                age_days = max(0.0, (self._now - secs) / 86400)
                w = 0.5 ** (age_days / halflife_days)
            else:
                w = 1.0
            d.feed(from_me, body, weight=w)
        for pkt in read_log():
            thread = pkt["payload"].get("thread")
            dev = pkt.get("origin", {}).get("device", "")
            if thread == name:
                d.feed(dev in ("twin:cal", "twin:~cal"), pkt["payload"]["body"], growth=True)
            elif not thread and dev == "twin:~" + name:
                d.feed(False, pkt["payload"]["body"], growth=True)
        return d

    def set_era(self, name, halflife_days):
        self.era[name] = halflife_days
        self.experts[name] = self._build(name, halflife_days)
        return {"name": name, "halflife_days": halflife_days, "words": self.experts[name].words}

    def summary(self):
        return [
            {"name": n, "bedrock": e.bedrock, "growth": e.growth, "words": e.words}
            for n, e in self.experts.items()
        ]

    @staticmethod
    def _seed(packets, force, tail=60):
        toks = []
        for pkt in packets[-12:]:
            dev = pkt["origin"]["device"]
            speaker = ME if dev in ("twin:cal", "twin:~cal") else THEM
            toks += [speaker] + tokenize(pkt["payload"]["body"])
        toks.append(force)
        clipped = toks[-tail:]
        return clipped if clipped[-1] == force else clipped + [force]

    def chat(self, name, message):
        expert = self.experts[name]
        thread = [p for p in read_log() if p["payload"].get("thread") == name]
        pkt = append_log("twin:cal", message, {"thread": name})
        chain = [pkt]
        bubbles = expert.reply(self._seed(thread + [pkt], THEM), prompt_toks=tokenize(message)) or [SILENCE]
        expert.feed(True, message, growth=True)
        for b in bubbles:
            chain.append(append_log(f"twin:~{name}", b, {"thread": name}))
            if b != SILENCE:
                expert.feed(False, b, growth=True)
        return {"chain": chain}

    def simulate(self, name, minutes, max_turns=80):
        """Perturb-and-run: the two ghosts volley on their learned rhythm.
        Ends when a ghost generates nothing (ghosted), a sampled silence
        outlasts the window (left on read), or the clock runs out."""
        expert = self.experts[name]
        budget = max(1.0, float(minutes)) * 60.0
        clock = 0.0
        history = [p for p in read_log() if p["payload"].get("thread") == name]
        last_dev = history[-1]["origin"]["device"] if history else "twin:cal"
        next_them = last_dev in ("twin:cal", "twin:~cal")
        chain = []
        ended = "clock ran out"
        for _ in range(max_turns):
            fm = not next_them  # responder's from_me flag
            pool = [g for g in self.gaps[name][fm] if g <= 86400] or [60.0]
            gap = random.choice(pool)
            if clock + gap > budget:
                ended = "left on read past the window"
                break
            clock += gap
            prompt = tokenize(history[-1]["payload"]["body"]) if history else None
            bubbles = expert.reply(self._seed(history, THEM if next_them else ME), as_them=next_them, prompt_toks=prompt)
            if not bubbles:
                ended = f"~{name} ghosted" if next_them else "~cal ghosted"
                break
            dev = f"twin:~{name}" if next_them else "twin:~cal"
            for b in bubbles:
                p = append_log(dev, b, {"thread": name, "sim": True, "sim_offset_s": round(clock)})
                chain.append(p)
                history.append(p)
                expert.feed(fm, b, growth=True)
            next_them = not next_them
        return {"chain": chain, "ended": ended, "sim_seconds": round(clock)}

    def addressed(self, seed):
        toks = set(tokenize(seed))
        hits = set()
        for name, ntoks in self.name_toks.items():
            for t in toks:
                if t in ntoks or (len(t) >= 4 and any(nt.startswith(t) for nt in ntoks)):
                    hits.add(name)
                    break
        return hits

    def ask(self, seed, volume):
        chain = [append_log("twin:cal", seed)]
        scores = {n: e.coverage(seed) for n, e in self.experts.items()}
        named = self.addressed(seed)
        if named:
            best = max(named, key=lambda n: scores[n])
        else:
            best = max(scores, key=scores.get)
        if scores[best] < 0.15 and not named:
            chain.append(append_log("twin:room", SILENCE, {"scores": scores}))
            return {"chain": chain, "scores": scores}
        bubbles = self.experts[best].reply([ME] + tokenize(seed) + [THEM], prompt_toks=tokenize(seed))
        reply = "\n".join(bubbles) if bubbles else SILENCE
        extra = {"coverage": scores[best], "scores": scores}
        if named:
            extra["routed"] = "named"
        chain.append(append_log(f"twin:~{best}", reply, extra))
        if reply != SILENCE:
            self.experts[best].feed(False, reply, growth=True)
        if volume >= 2 and reply != SILENCE and len(self.experts) > 1:
            rescored = {n: e.coverage(reply) for n, e in self.experts.items() if n != best}
            second = max(rescored, key=rescored.get)
            if rescored[second] >= 0.3:
                b2 = self.experts[second].reply([ME] + tokenize(reply) + [THEM])
                r2 = "\n".join(b2) if b2 else SILENCE
                chain.append(append_log(f"twin:~{second}", r2, {"coverage": rescored[second]}))
                if r2 != SILENCE:
                    self.experts[second].feed(False, r2, growth=True)
        return {"chain": chain, "scores": scores}

# -------------------------------------------------------------- the server

class Handler(BaseHTTPRequestHandler):
    seance = None

    def log_message(self, *args):
        pass

    def send_json(self, obj, status=200):
        body = json.dumps(obj).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def send_file(self, name, ctype):
        p = HERE / name
        if not p.exists():
            self.send_response(404)
            self.end_headers()
            return
        body = p.read_bytes()
        self.send_response(200)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        u = urlparse(self.path)
        if u.path in ("/", "/index.html"):
            self.send_file("index.html", "text/html; charset=utf-8")
        elif u.path == "/app.js":
            self.send_file("app.js", "text/javascript; charset=utf-8")
        elif u.path == "/style.css":
            self.send_file("style.css", "text/css; charset=utf-8")
        elif u.path == "/api/experts":
            self.send_json(self.seance.summary())
        elif u.path == "/api/log":
            self.send_json([p for p in read_log() if not p["payload"].get("thread")])
        elif u.path == "/api/thread":
            name = parse_qs(u.query).get("person", [""])[0]
            self.send_json([p for p in read_log() if p["payload"].get("thread") == name])
        else:
            self.send_response(404)
            self.end_headers()

    def do_POST(self):
        length = int(self.headers.get("Content-Length", 0))
        try:
            req = json.loads(self.rfile.read(length))
        except Exception:
            self.send_json({"error": "bad request"}, 400)
            return
        if self.path == "/api/ask":
            seed = str(req.get("seed", "")).strip()
            if not seed:
                self.send_json({"error": "empty seed"}, 400)
                return
            self.send_json(self.seance.ask(seed, int(req.get("volume", 2))))
        elif self.path == "/api/chat":
            person = str(req.get("person", ""))
            message = str(req.get("message", "")).strip()
            if person not in self.seance.experts or not message:
                self.send_json({"error": "unknown person or empty message"}, 400)
                return
            self.send_json(self.seance.chat(person, message))
        elif self.path == "/api/era":
            person = str(req.get("person", ""))
            if person not in self.seance.experts:
                self.send_json({"error": "unknown person"}, 400)
                return
            self.send_json(self.seance.set_era(person, int(req.get("halflife_days", 0))))
        elif self.path == "/api/simulate":
            person = str(req.get("person", ""))
            if person not in self.seance.experts:
                self.send_json({"error": "unknown person"}, 400)
                return
            self.send_json(self.seance.simulate(person, req.get("minutes", 30)))
        else:
            self.send_response(404)
            self.end_headers()

# ------------------------------------------------------------------- main

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("names", nargs="*", help="people to summon (substring match); none = top contacts")
    ap.add_argument("--list", action="store_true", help="show top contacts and exit")
    ap.add_argument("--top", type=int, default=20, help="how many top contacts to seat when no names given")
    ap.add_argument("--db", default=None, help="path to chat.db")
    ap.add_argument("--contacts", default=None, help="path to AddressBook-v22.abcddb")
    ap.add_argument("--port", type=int, default=8362)
    args = ap.parse_args()

    contacts = load_contacts(args.contacts)
    people = load_people(find_db(args.db), contacts)
    ranked = sorted(people.items(), key=lambda kv: -len(kv[1]))

    if args.list:
        print("top 1:1 threads by message volume:")
        for name, msgs in ranked[:30]:
            theirs = sum(1 for _, fm, _ in msgs if not fm)
            print(f"   {str(name):30s} {len(msgs):6d} msgs ({theirs} theirs, {len(msgs)-theirs} yours)")
        return

    if args.names:
        chosen = []
        for want in args.names:
            match = next((n for n, _ in ranked if want.lower() in str(n).lower()), None)
            if match:
                chosen.append(match)
            else:
                print(f"no contact matching '{want}' — skipping")
    else:
        chosen = [n for n, msgs in ranked[: args.top] if any(not fm for _, fm, _ in msgs)]
    if not chosen:
        sys.exit("nobody summoned")

    Handler.seance = Seance(people, chosen)
    for s in Handler.seance.summary():
        print(f"   ~{str(s['name']).lower()}: {s['bedrock']} bedrock, {s['growth']} growth, {s['words']} words")
    print(f"\nthe room is open: http://localhost:{args.port}")
    HTTPServer(("127.0.0.1", args.port), Handler).serve_forever()


if __name__ == "__main__":
    main()

