/* the lens dresses as Messages.app (dark) — sediment in a familiar skin */
* { margin: 0; padding: 0; box-sizing: border-box; }
:root {
  --bg: #1e1e1e;
  --sidebar: #262628;
  --hairline: rgba(255, 255, 255, 0.09);
  --fg: #f2f2f7;
  --meta: #8e8e93;
  --blue: #0a84ff;
  --gray-bubble: #3a3a3c;
  --select: #0a84ff;
}
html, body { height: 100%; }
body {
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", sans-serif;
  background: var(--bg);
  color: var(--fg);
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
}
#shell { display: flex; height: 100vh; }

/* ------------------------------------------------------------- sidebar */
#sidebar {
  width: 300px;
  min-width: 300px;
  background: var(--sidebar);
  border-right: 1px solid var(--hairline);
  display: flex;
  flex-direction: column;
}
#search-wrap { padding: 12px 12px 8px; }
#search {
  width: 100%;
  background: rgba(255, 255, 255, 0.08);
  border: none;
  border-radius: 8px;
  padding: 6px 10px;
  color: var(--fg);
  font-size: 13px;
  outline: none;
}
#search::placeholder { color: var(--meta); }
#convos { flex: 1; overflow-y: auto; padding: 0 6px 12px; }
.convo {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border-radius: 10px;
  cursor: default;
  user-select: none;
}
.convo:hover { background: rgba(255, 255, 255, 0.05); }
.convo.active { background: var(--select); }
.convo.active .cv-meta, .convo.active .cv-time { color: rgba(255, 255, 255, 0.8); }
.avatar {
  width: 40px;
  height: 40px;
  min-width: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.5px;
}
.cv-body { flex: 1; min-width: 0; }
.cv-top { display: flex; justify-content: space-between; align-items: baseline; }
.cv-name { font-weight: 600; font-size: 13.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cv-time { font-size: 11px; color: var(--meta); margin-left: 6px; flex-shrink: 0; }
.cv-meta {
  font-size: 12px;
  color: var(--meta);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  margin-top: 1px;
}
.cv-bar { height: 3px; border-radius: 2px; background: rgba(255, 255, 255, 0.12); margin-top: 5px; overflow: hidden; }
.cv-bar .fill { height: 100%; background: #30d158; }
.convo.active .cv-bar .fill { background: #fff; }

/* ---------------------------------------------------------------- pane */
#pane { flex: 1; display: flex; flex-direction: column; min-width: 0; }
#chat-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  border-bottom: 1px solid var(--hairline);
  background: rgba(30, 30, 30, 0.92);
}
#head-id { display: flex; align-items: center; gap: 10px; min-width: 0; }
#head-avatar { width: 32px; height: 32px; min-width: 32px; font-size: 12px; }
#head-name { font-weight: 600; font-size: 14px; }
#head-sub { font-size: 11px; color: var(--meta); }
#head-controls { display: flex; align-items: center; gap: 8px; }
#head-controls button {
  background: rgba(255, 255, 255, 0.08);
  color: var(--fg);
  border: none;
  border-radius: 7px;
  padding: 4px 10px;
  font-size: 12px;
  cursor: pointer;
}
#head-controls button:hover { background: rgba(255, 255, 255, 0.14); }
#head-controls button.active { background: var(--blue); }
#head-controls button:disabled { opacity: 0.5; cursor: default; }
#sim-mins {
  width: 52px;
  background: rgba(255, 255, 255, 0.08);
  border: none;
  border-radius: 7px;
  padding: 4px 8px;
  color: var(--fg);
  font-size: 12px;
  outline: none;
}

/* ------------------------------------------------------------ messages */
#scroll { flex: 1; overflow-y: auto; padding: 14px 18px 8px; }
#log { list-style: none; display: flex; flex-direction: column; }
.row { display: flex; flex-direction: column; margin: 1px 0; }
.row.mine { align-items: flex-end; }
.row.theirs { align-items: flex-start; }
.who {
  font-size: 11px;
  color: var(--meta);
  margin: 8px 6px 2px;
}
.bubble {
  max-width: 64%;
  padding: 7px 12px;
  border-radius: 18px;
  font-size: 14px;
  line-height: 1.32;
  white-space: pre-wrap;
  word-break: break-word;
}
.mine .bubble { background: var(--blue); color: #fff; border-bottom-right-radius: 5px; }
.theirs .bubble { background: var(--gray-bubble); color: #fff; border-bottom-left-radius: 5px; }
.row.sim .bubble { opacity: 0.75; }
.fine { font-size: 10px; color: var(--meta); margin: 2px 8px 4px; }
.datesep {
  text-align: center;
  font-size: 11px;
  color: var(--meta);
  margin: 14px 0 6px;
}
.ended {
  text-align: center;
  font-size: 11.5px;
  color: var(--meta);
  font-style: italic;
  margin: 10px 0;
}

/* typing indicator */
.typing .bubble { display: inline-flex; gap: 4px; align-items: center; padding: 11px 14px; }
.typing .dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #8e8e93;
  animation: blink 1.2s infinite both;
}
.typing .dot:nth-child(2) { animation-delay: 0.18s; }
.typing .dot:nth-child(3) { animation-delay: 0.36s; }
@keyframes blink { 0%, 70%, 100% { opacity: 0.35; } 35% { opacity: 1; } }

/* ------------------------------------------------------------ composer */
#composer { padding: 8px 14px 12px; }
#seed {
  width: 100%;
  background: transparent;
  border: 1px solid var(--gray-bubble);
  border-radius: 18px;
  padding: 8px 14px;
  color: var(--fg);
  font-size: 14px;
  outline: none;
}
#seed::placeholder { color: var(--meta); }

::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.14); border-radius: 4px; }
::-webkit-scrollbar-track { background: transparent; }

