* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  height: 100%;
  background: var(--bg);
  color: var(--fg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

body {
  display: grid;
  grid-template: "header header" auto "aside main" 1fr "aside footer" auto / 280px 1fr;
}

header {
  grid-area: header;
  padding: 18px 24px 10px;
  border-bottom: 1px solid var(--hairline);
  display: flex;
  justify-content: space-between;
  align-items: center;
}
#copy-chat {
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  color: var(--meta);
  background: transparent;
  border: 1px solid var(--hairline);
  border-radius: 999px;
  padding: 8px 14px;
  cursor: pointer;
}
#copy-chat:hover { color: var(--fg); }
header h1 { font-size: 17px; font-weight: 700; }
header .sub { font-size: 13px; color: var(--meta); margin-top: 2px; }

aside {
  grid-area: aside;
  padding: 16px;
  border-right: 1px solid var(--hairline);
  overflow-y: auto;
}
.card {
  background: var(--card);
  border-radius: 14px;
  padding: 12px 14px;
  margin-bottom: 10px;
  box-shadow: 0 1px 6px rgba(0, 0, 0, 0.08);
  cursor: pointer;
  border: 1.5px solid transparent;
}
.card.active { border-color: var(--purple); }
header .mode { font-size: 14px; font-weight: 600; color: var(--purple); margin-left: 8px; }
.card .name { font-size: 16px; font-weight: 700; color: var(--purple); }
.card .meta { font-size: 12px; color: var(--meta); margin-top: 3px; }
.card .bar {
  height: 6px;
  border-radius: 3px;
  background: rgba(127, 127, 127, 0.15);
  margin-top: 8px;
  overflow: hidden;
}
.card .fill { height: 100%; background: var(--green); border-radius: 3px; }

main { grid-area: main; overflow-y: auto; padding: 18px 24px; }
#log { list-style: none; display: flex; flex-direction: column; gap: 12px; }

.row { max-width: 70%; display: flex; flex-direction: column; gap: 3px; }
.row.mine { align-self: flex-end; align-items: flex-end; }
.row.theirs { align-self: flex-start; }
.who { font-size: 12px; color: var(--meta); }
.row.theirs .who { color: var(--purple); font-weight: 600; }
.bubble {
  background: var(--card);
  border-radius: 16px;
  padding: 10px 14px;
  font-size: 15px;
  line-height: 1.45;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);
}
.row.mine .bubble { background: var(--fg); color: var(--bg); }

footer {
  grid-area: footer;
  padding: 14px 24px calc(env(safe-area-inset-bottom) + 14px);
  border-top: 1px solid var(--hairline);
  display: flex;
  gap: 12px;
  align-items: center;
}
.volume { display: flex; gap: 6px; }
.volume button {
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  color: var(--meta);
  background: transparent;
  border: 1px solid var(--hairline);
  border-radius: 999px;
  padding: 8px 12px;
  cursor: pointer;
}
.volume button.active { background: var(--fg); color: var(--bg); border-color: var(--fg); }

.era { display: flex; gap: 4px; }
.era button {
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  color: var(--meta);
  background: transparent;
  border: 1px solid var(--hairline);
  border-radius: 999px;
  padding: 7px 11px;
  cursor: pointer;
}
.era button.active { background: var(--purple); color: #fff; border-color: var(--purple); }

.sim-row { display: flex; gap: 6px; align-items: center; }
.sim-row input {
  width: 64px;
  font: inherit;
  font-size: 14px;
  border: 1px solid var(--hairline);
  border-radius: 999px;
  padding: 8px 12px;
  background: transparent;
  color: var(--fg);
}
.sim-label { font-size: 13px; color: var(--meta); }
#sim-btn {
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  color: var(--purple);
  background: transparent;
  border: 1px solid var(--purple);
  border-radius: 999px;
  padding: 8px 14px;
  cursor: pointer;
}
.row.sim .bubble { opacity: 0.8; border: 1px dashed var(--hairline); }
.row.sim .who { font-style: italic; }
.ended { align-self: center; font-size: 12px; color: var(--meta); font-style: italic; padding: 4px 0; }

.ask-row { flex: 1; display: flex; gap: 10px; }
.ask-row input {
  flex: 1;
  font: inherit;
  font-size: 15px;
  border: 1px solid var(--hairline);
  border-radius: 999px;
  padding: 10px 16px;
  background: transparent;
  color: var(--fg);
}
.ask-row button {
  font: inherit;
  font-size: 15px;
  font-weight: 600;
  background: var(--fg);
  color: var(--bg);
  border: none;
  border-radius: 999px;
  padding: 10px 20px;
  cursor: pointer;
}

input.content:
// The lens on the seance, dressed as Messages.app. Two views: the room
// (coverage-arbitration) and 1:1 chats (dialogue folds). Renders; never
// invents — but now it also *paces*: twin bubbles arrive on sampled real
// latencies with a typing indicator, because alive is half timing.
const $ = (id) => document.getElementById(id);
let volume = 2;
let view = "room"; // "room" | person name
let viewGen = 0; // bumped on every view switch; stale deliveries stop
let current = []; // packets rendered in the current view, for copy chat
let experts = [];
let lastStamp = null; // for date separators
const eraByPerson = {};

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

boot();

async function boot() {
  experts = await fetch("/api/experts").then((r) => r.json());
  renderSidebar();
  await showRoom();
}

// ------------------------------------------------------------- sidebar

function hue(name) {
  let h = 0;
  for (const c of String(name)) h = (h * 31 + c.charCodeAt(0)) % 360;
  return h;
}

function initials(name) {
  const parts = String(name).replace(/\(.*?\)/g, "").trim().split(/\s+/);
  return parts.slice(0, 2).map((p) => (p[0] || "").toUpperCase()).join("") || "?";
}

function makeAvatar(name, room = false) {
  const el = document.createElement("div");
  el.className = "avatar";
  if (room) {
    el.style.background = "linear-gradient(180deg,#5e5ce6,#3634a3)";
    el.textContent = "⌘";
  } else {
    const h = hue(name);
    el.style.background = `linear-gradient(180deg,hsl(${h},55%,58%),hsl(${h},55%,42%))`;
    el.textContent = initials(name);
  }
  return el;
}

