  if (d.toDateString() === yest) return "Yesterday";
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

function maybeDateSep(p) {
  if (p.payload.sim) return;
  const t = new Date(p.observed_at).getTime();
  if (lastStamp == null || t - lastStamp > 20 * 60 * 1000) {
    const li = document.createElement("li");
    li.className = "datesep";
