// scroll up → page older history in, like real Messages
$("scroll").addEventListener("scroll", async () => {
  const sc = $("scroll");
  if (view === "room" || loadingOlder || oldestIdx <= 0 || sc.scrollTop > 80) return;
  loadingOlder = true;
  const gen = viewGen;
  try {
    const older = await fetch(
      `/api/history?person=${encodeURIComponent(view)}&before=${oldestIdx}`
    ).then((r) => r.json());
    if (gen !== viewGen || !older.length) return;
    oldestIdx = older[0].payload.idx ?? 0;
    const ctx = { last: null };
    const frag = document.createDocumentFragment();
    for (const p of older) for (const n of rowNodes(p, ctx)) frag.append(n);
    const prevHeight = sc.scrollHeight;
    $("log").prepend(frag);
    sc.scrollTop += sc.scrollHeight - prevHeight;
    current = older.concat(current);
  } finally {
    loadingOlder = false;
  }
});

