// ----------------------------------------------------- attention chart
// burst-weighted attention per week, one line per voice. colors validated
// against the dark surface: you #0a84ff, them #c26f1f (never gray, never
// confusable with the blue).
const ATTN = { you: "#0a84ff", them: "#c26f1f" };

$("attn-btn").addEventListener("click", async () => {
  const panel = $("attn-panel");
  if (!panel.hidden) {
    panel.hidden = true;
    $("attn-btn").classList.remove("active");
    return;
  }
  const series = await fetch(`/api/attention?person=${encodeURIComponent(view)}`).then((r) => r.json());
  panel.textContent = "";
  panel.hidden = false;
  $("attn-btn").classList.add("active");
  if (!series.length) {
    panel.textContent = "no history";
    return;
  }
  renderAttention(panel, series);
});

function renderAttention(panel, series) {
  const W = panel.clientWidth || 800;
  const H = 150;
  const pad = { l: 10, r: 52, t: 12, b: 18 };
  const max = Math.max(1, ...series.map((r) => Math.max(r.cal, r.them)));
  const x = (i) => pad.l + (i / Math.max(1, series.length - 1)) * (W - pad.l - pad.r);
  const y = (v) => pad.t + (1 - v / max) * (H - pad.t - pad.b);
  const path = (key) => series.map((r, i) => `${i ? "L" : "M"}${x(i).toFixed(1)},${y(r[key]).toFixed(1)}`).join("");

  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
  svg.setAttribute("width", "100%");
  svg.setAttribute("height", H);

  // year ticks, recessive
  let lastYear = "";
  series.forEach((r, i) => {
    const yr = r.week.slice(0, 4);
    if (yr !== lastYear) {
      lastYear = yr;
      const g = document.createElementNS(svg.namespaceURI, "line");
      g.setAttribute("x1", x(i)); g.setAttribute("x2", x(i));
      g.setAttribute("y1", pad.t); g.setAttribute("y2", H - pad.b);
      g.setAttribute("stroke", "rgba(255,255,255,0.08)");
      svg.append(g);
      const t = document.createElementNS(svg.namespaceURI, "text");
      t.setAttribute("x", x(i) + 3); t.setAttribute("y", H - 5);
      t.setAttribute("class", "attn-tick");
      t.textContent = yr;
      svg.append(t);
    }
  });

  for (const [key, color] of [["them", ATTN.them], ["cal", ATTN.you]]) {
    const p = document.createElementNS(svg.namespaceURI, "path");
    p.setAttribute("d", path(key));
    p.setAttribute("fill", "none");
    p.setAttribute("stroke", color);
    p.setAttribute("stroke-width", "2");
    p.setAttribute("stroke-linejoin", "round");
    svg.append(p);
    // direct label at the line's end
    const t = document.createElementNS(svg.namespaceURI, "text");
    t.setAttribute("x", W - pad.r + 6);
    t.setAttribute("y", y(series[series.length - 1][key]) + 4);
    t.setAttribute("class", "attn-label");
    t.setAttribute("fill", color);
    t.textContent = key === "cal" ? "you" : "them";
    svg.append(t);
  }

  // hover crosshair + readout
  const cross = document.createElementNS(svg.namespaceURI, "line");
  cross.setAttribute("y1", pad.t); cross.setAttribute("y2", H - pad.b);
  cross.setAttribute("stroke", "rgba(255,255,255,0.35)");
  cross.setAttribute("visibility", "hidden");
  svg.append(cross);
  const readout = document.createElement("div");
  readout.className = "attn-readout";
  readout.textContent = "attention · words said more together in a span, weighted by how much each of you spoke";
  svg.addEventListener("mousemove", (ev) => {
    const rect = svg.getBoundingClientRect();
    const px = ((ev.clientX - rect.left) / rect.width) * W;
    const i = Math.max(0, Math.min(series.length - 1, Math.round(((px - pad.l) / (W - pad.l - pad.r)) * (series.length - 1))));
    cross.setAttribute("x1", x(i)); cross.setAttribute("x2", x(i));
    cross.setAttribute("visibility", "visible");
    const r = series[i];
    readout.textContent = `week of ${r.week} — you ${r.cal} · them ${r.them}`;
  });
  svg.addEventListener("mouseleave", () => {
    cross.setAttribute("visibility", "hidden");
    readout.textContent = "attention · words said more together in a span, weighted by how much each of you spoke";
  });

  const legend = document.createElement("div");
  legend.className = "attn-legend";
  for (const [label, color] of [["you", ATTN.you], ["them", ATTN.them]]) {
    const item = document.createElement("span");
    const dot = document.createElement("span");
    dot.className = "attn-dot";
    dot.style.background = color;
    item.append(dot, document.createTextNode(label));
    legend.append(item);
  }
  panel.append(legend, svg, readout);
}

