"""Replay the packet log into the graph.

Runs a full rebuild every time: delete the projection, replay the log.
That the result is identical on every run is the whole thesis — the graph
is disposable; the packet log is the truth. No LLM is involved here:
op packets were already interpreted at ingestion, so replay is
deterministic and free.

The log is fully self-describing: `schema` packets declare the tables
(and rules like exclusive_from), `op` packets fill them. Rebuild is two
passes — schema first, then ops — so declarations can arrive at any
point in the log's life. Changing the ontology = minting new schema
packets and replaying.
"""

import shutil
from datetime import datetime
from pathlib import Path

import ladybug as lb

import packets

HERE = Path(__file__).parent
GRAPH = HERE / "graph.lbdb"


def ddl(body: dict) -> str:
    if body["decl"] == "node":
        cols = ", ".join(f"{k} {v}" for k, v in body["props"].items())
        return f"CREATE NODE TABLE {body['name']}({cols})"
    cols = "".join(f", {k} {v}" for k, v in body.get("props", {}).items())
    return f"CREATE REL TABLE {body['name']}(FROM {body['frm']} TO {body['to']}{cols})"


def fresh_connection(schema: list[dict]) -> lb.Connection:
    for p in (GRAPH, HERE / "graph.lbdb.wal"):
        if p.is_dir():
            shutil.rmtree(p)
        elif p.exists():
            p.unlink()
    conn = lb.Connection(lb.Database(str(GRAPH)))
    for body in schema:
        conn.execute(ddl(body))
    return conn


def as_param(key: str, value):
    if key == "since":
        return datetime.fromisoformat(value.replace("Z", ""))
    return value


def apply_op(conn: lb.Connection, body: dict, exclusive_from: set[str]) -> None:
    op = body["op"]
    props = {k: as_param(k, v) for k, v in body.get("props", {}).items()}

    if op == "upsert_node":
        set_clause = ", ".join(f"n.{k} = ${k}" for k in props)
        q = f"MERGE (n:{body['table']} {{name: $name}})"
        if set_clause:
            q += f" SET {set_clause}"
        conn.execute(q, {"name": body["key"], **props})

    elif op == "upsert_edge":
        table = body["table"]
        (ft, fk), (tt, tk) = body["frm"], body["to"]
        if table in exclusive_from:
            conn.execute(
                f"MATCH (a:{ft} {{name: $fk}})-[r:{table}]->() DELETE r",
                {"fk": fk},
            )
        set_clause = ", ".join(f"r.{k} = ${k}" for k in props)
        q = (
            f"MATCH (a:{ft} {{name: $fk}}), (b:{tt} {{name: $tk}}) "
            f"MERGE (a)-[r:{table}]->(b)"
        )
        if set_clause:
            q += f" SET {set_clause}"
        conn.execute(q, {"fk": fk, "tk": tk, **props})

    else:
        raise ValueError(f"unknown op: {op}")


def rebuild() -> None:
    log = packets.read_all()
    schema = [p["body"] for p in log if p["kind"] == "schema"]
    exclusive_from = {b["name"] for b in schema if b.get("exclusive_from")}
    conn = fresh_connection(schema)
    ops = [p for p in log if p["kind"] == "op"]
    for pkt in ops:
