"""Field receptor: HTTP endpoint the iPhone shortcut POSTs transcripts to.

Run it on the Mac:      uv run receptor.py
Reach it over Tailscale: http://<mac-tailnet-name>:8787/packet

Accepts JSON like {"text": "...", "source": "cal-phone"} and mints a raw
packet into the log. It interprets nothing — it is only a receptor.
"""

import json
from http.server import BaseHTTPRequestHandler, HTTPServer

import apply
import fetcher
import buzz
import interpret
import packets
import resolver


def crank() -> tuple[list[dict], list[tuple[str, str]]]:
    """One full turn of the society. Scribe and Squint alternate until
    the log goes quiet (agents mint raw packets for each other, so one
    pass isn't always enough), then rebuild, then Fetch, then Herald."""
    results = interpret.run()
    for _ in range(4):
        resolver.run()
        more = interpret.run()
        if not more:
            break
        results += more
    apply.rebuild()
    answers = fetcher.run()
    buzz.run()
    return results, answers


def apply_response(text: str, code: str | None) -> tuple[str | None, str]:
    """Cal pressed the Answer button: tag his reply to an open question.
    Explicit in-response math only — never inferred from passing speech."""
    log = packets.read_all()
    answered = {p["body"].get("answers") for p in log if p["body"].get("answers")}
    unresolved = {
        p["body"].get("re")
        for p in log
        if p["kind"] == "reasoning"
        and p["body"].get("agent") == "squint.v0"
        and p["body"].get("conclusion") == "unresolved"
    }
    candidates = [
        q for q in log
        if q["kind"] == "question"
        and q["id"] not in answered
        and (q["body"].get("for") == "humans" or q["id"] in unresolved)
    ]
    if code:
        candidates = [q for q in candidates if q["id"].endswith(code)]
    if not candidates:
        return None, "no matching open question"
    target = candidates[-1]  # most recent open question

    response = packets.mint(
        "raw.response",
        {"text": text, "answers": target["id"], "re": target["id"]},
        source="cal-phone",
    )
    about = target["body"].get("about", {})
    norm = interpret.normalize(text)
    if about.get("role") == "placement" and norm.split()[:1] and norm.split()[0] in ("in", "on", "inside", "atop"):
        # fragment like "on the desk" -> compose the full statement so
        # Scribe can read it; provenance chains response -> question
        packets.mint(
            "raw.restated",
            {
                "text": f"the {about['token']} is {norm}",
                "re": response["id"],
                "answers": target["id"],
                "note": "composed from in-response answer",
            },
            source="receptor",
        )
    return target["id"], target["body"]["text"]

PORT = 8787


class Handler(BaseHTTPRequestHandler):
    def do_POST(self):
        if self.path not in ("/packet", "/answer"):
            return self._send(404, {"error": "unknown path"})
        length = int(self.headers.get("Content-Length", 0))
        try:
            body = json.loads(self.rfile.read(length) or b"{}")
        except json.JSONDecodeError:
            return self._send(400, {"error": "invalid json"})
        text = (body.get("text") or "").strip()
        if not text:
            return self._send(400, {"error": "no text"})

        if self.path == "/answer":
            try:
                qid, q_text = apply_response(text, (body.get("code") or "").strip() or None)
                if qid is None:
                    return self._send(200, {"ok": False, "error": q_text})
                results, answers = crank()
                return self._send(200, {"ok": True, "answered": qid, "question": q_text})
            except Exception as exc:
                return self._send(200, {"ok": False, "error": f"hub error: {exc}"})
        pkt = packets.mint(
            body.get("kind", "raw.voice"),
            {"text": text},
            source=body.get("source", "cal-phone"),
        )
        # speaking is updating: one crank per packet — the whole society
        # takes a turn, coordinated by nothing but the log
        try:
            results, answers = crank()
            mine = next((r for r in results if r["id"] == pkt["id"]), None)
            note = f"{mine['conclusion']} ({mine['ops']} emitted)" if mine else "no result"
            answer = next((t for rid, t in answers if rid == pkt["id"]), None)
        except Exception as exc:
            note, answer = f"hub error: {exc}", None
        resp = {"ok": True, "id": pkt["id"], "interpreted": note}
        if answer:
            resp["answer"] = answer
        self._send(200, resp)

    def do_GET(self):
        self._send(200, {"ok": True, "service": "servicerm receptor"})

    def _send(self, code: int, obj: dict):
        data = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)


if __name__ == "__main__":
    print(f"receptor listening on 0.0.0.0:{PORT} — POST /packet")
    HTTPServer(("0.0.0.0", PORT), Handler).serve_forever()

