"""Live packet log viewer — a little window on the system of record.

    uv run logview.py

Polls packets.jsonl once a second and repaints when it grows. Read-only:
this window observes the log, it never touches it.
"""

import json
import tkinter as tk
from datetime import datetime
from pathlib import Path
from tkinter import ttk

LOG = Path(__file__).parent / "packets.jsonl"

KIND_COLORS = {
    "raw": "#4ea1ff",     # human observations
    "op": "#3fb950",      # committed graph mutations
    "skip": "#8b949e",    # unparsed, waiting for a smarter interpreter
    "schema": "#bc8cff",  # ontology declarations — the log describing itself
    "rule": "#f0883e",    # grammar declarations — the interpreter's brain, logged
    "reasoning": "#e3b341",  # a mind at work — Scribe, Squint, Fetch, more later
    "question": "#ff7b72",   # an agent asking the society for help
    "query": "#39c5cf",      # a spoken question compiled to literal cypher
    "answer": "#7ee787",     # the graph speaking back
    "sent": "#f778ba",       # Buzz carrying a question out to the humans
    "task": "#d29922",       # intended, unrealized change — a command, not a fact
    "config": "#8b949e",     # assumptions declared on the tape, not buried in code
}


def local_time(iso: str) -> str:
    return datetime.fromisoformat(iso).astimezone().strftime("%b %d  %H:%M:%S")


def summarize(pkt: dict) -> str:
    body, kind = pkt["body"], pkt["kind"]
    if kind.startswith("raw."):
        return body.get("text", "").replace("\n", " / ")
    if kind == "op":
        if body["op"] == "upsert_node":
            return f"{body['table']}: {body['key']}"
        if body["op"] == "upsert_edge":
            return f"{body['frm'][1]}  —{body['table']}→  {body['to'][1]}"
        return body["op"]
    if kind == "skip.note":
        return f"({body.get('note', 'skipped')})"
    if kind == "schema":
        return f"declare {body['decl']} table: {body['name']}"
    if kind == "rule":
        return f"declare rule: {body['name']}  ({body['action']})   {body['pattern']}"
    if kind == "reasoning":
        if body.get("because"):
            return f"[{body['agent']}] {body['because']} → {body['conclusion']}"
        if body.get("matched"):
            return f"[{body['agent']}] {body['matched']} matched {body['bindings']} → {body['conclusion']}"
        return f"[{body['agent']}] no match in {len(body.get('considered', []))} rules → {body['conclusion']}"
    if kind == "question":
        return f"[{body['from_agent']}] {body['text']}"
    if kind == "query":
        return f"{body['shape']}?  " + body["cypher"].replace("\n", "  |  ")
    if kind == "answer":
        return body["text"]
    if kind == "rule.retire":
        return f"retire rule: {body['name']}"
    if kind == "schema.retire":
        return f"retire schema: {body['name']}"
    if kind == "config":
        return "config: " + json.dumps(body)
    if kind == "sent":
        return f"→ {body['to']}: {body['text']}"
    if kind == "task":
        return f"TASK: {body['text']}"
    return json.dumps(body)[:100]


class LogView:
    def __init__(self, root: tk.Tk):
        self.root = root
        root.title("servicerm — packet log")
        root.geometry("900x520")
        root.configure(bg="#0d1117")

        style = ttk.Style()
        style.theme_use("clam")
        style.configure(
            "Log.Treeview",
            background="#0d1117", fieldbackground="#0d1117",
            foreground="#c9d1d9", rowheight=24, font=("Menlo", 12), borderwidth=0,
        )
        style.configure(
            "Log.Treeview.Heading",
            background="#161b22", foreground="#8b949e", font=("Menlo", 11, "bold"),
        )
        style.map("Log.Treeview", background=[("selected", "#1f6feb")])

        cols = ("time", "source", "kind", "summary")
        self.tree = ttk.Treeview(root, columns=cols, show="headings", style="Log.Treeview")
        for col, width, stretch in (
            ("time", 130, False), ("source", 110, False),
            ("kind", 90, False), ("summary", 540, True),
        ):
            self.tree.heading(col, text=col.upper())
            self.tree.column(col, width=width, stretch=stretch)
        for tag, color in KIND_COLORS.items():
            self.tree.tag_configure(tag, foreground=color)

        scroll = ttk.Scrollbar(root, orient="vertical", command=self.tree.yview)
        self.tree.configure(yscrollcommand=scroll.set)
        self.tree.pack(side="left", fill="both", expand=True)
        scroll.pack(side="right", fill="y")

        self.by_iid = {}
        self.tree.bind("<Button-1>", self._on_click)
        self.tree.bind("<Double-1>", self._on_double)

        self.seen = 0
        self.poll()

    def _on_click(self, event):
        row = self.tree.identify_row(event.y)
        if not row:
            self.tree.selection_remove(*self.tree.selection())
        elif row in self.tree.selection():
            self.tree.selection_remove(row)
            return "break"

    def _on_double(self, event):
        row = self.tree.identify_row(event.y)
        pkt = self.by_iid.get(row)
        if not pkt:
            return
        self.tree.selection_set(row)
        win = tk.Toplevel(self.root)
        win.title(pkt["id"])
        win.geometry("680x440")
        text = tk.Text(
            win, bg="#0d1117", fg="#c9d1d9", font=("Menlo", 12), wrap="word",
            insertbackground="#c9d1d9", padx=14, pady=12, borderwidth=0,
        )
        text.insert("1.0", json.dumps(pkt, indent=2))
        text.configure(state="disabled")
        text.pack(fill="both", expand=True)

    def poll(self):
        try:
            lines = LOG.read_text().splitlines() if LOG.exists() else []
        except OSError:
            lines = []
        if len(lines) != self.seen:
            if len(lines) < self.seen:
                # the log shrank — it was reborn or swapped. repaint from zero.
                self.tree.delete(*self.tree.get_children())
                self.by_iid.clear()
                self.seen = 0
            at_bottom = self.seen == 0 or self.tree.yview()[1] > 0.99
            for line in lines[self.seen:]:
                if not line.strip():
                    continue
                pkt = json.loads(line)
                tag = pkt["kind"].split(".")[0]
                iid = self.tree.insert(
                    "", "end",
                    values=(local_time(pkt["minted_at"]), pkt["source"],
                            pkt["kind"], summarize(pkt)),
                    tags=(tag,),
                )
                self.by_iid[iid] = pkt
            self.seen = len(lines)
            self.root.title(f"servicerm — packet log ({self.seen} packets)")
            if at_bottom and self.tree.get_children():
                self.tree.see(self.tree.get_children()[-1])
        self.root.after(1000, self.poll)


if __name__ == "__main__":
    root = tk.Tk()
    LogView(root)
    root.mainloop()

"""Live packet log viewer — a little window on the system of record.

    uv run logview.py

Polls packets.jsonl once a second and repaints when it grows. Read-only:
this window observes the log, it never touches it.
"""

import json
import tkinter as tk
from datetime import datetime
from pathlib import Path
from tkinter import ttk

LOG = Path(__file__).parent / "packets.jsonl"

KIND_COLORS = {
    "raw": "#4ea1ff",     # human observations
    "op": "#3fb950",      # committed graph mutations
    "skip": "#8b949e",    # unparsed, waiting for a smarter interpreter
    "schema": "#bc8cff",  # ontology declarations — the log describing itself
    "rule": "#f0883e",    # grammar declarations — the interpreter's brain, logged
    "reasoning": "#e3b341",  # a mind at work — Scribe, Squint, Fetch, more later
    "question": "#ff7b72",   # an agent asking the society for help
    "query": "#39c5cf",      # a spoken question compiled to literal cypher
    "answer": "#7ee787",     # the graph speaking back
    "sent": "#f778ba",       # Buzz carrying a question out to the humans
    "task": "#d29922",       # intended, unrealized change — a command, not a fact
    "config": "#8b949e",     # assumptions declared on the tape, not buried in code
}


def local_time(iso: str) -> str:
    return datetime.fromisoformat(iso).astimezone().strftime("%b %d  %H:%M:%S")


def summarize(pkt: dict) -> str:
    body, kind = pkt["body"], pkt["kind"]
    if kind.startswith("raw."):
        return body.get("text", "").replace("\n", " / ")
    if kind == "op":
        if body["op"] == "upsert_node":
            return f"{body['table']}: {body['key']}"
        if body["op"] == "upsert_edge":
            return f"{body['frm'][1]}  —{body['table']}→  {body['to'][1]}"
        return body["op"]
    if kind == "skip.note":
        return f"({body.get('note', 'skipped')})"
    if kind == "schema":
        return f"declare {body['decl']} table: {body['name']}"
    if kind == "rule":
        return f"declare rule: {body['name']}  ({body['action']})   {body['pattern']}"
    if kind == "reasoning":
        if body.get("because"):
            return f"[{body['agent']}] {body['because']} → {body['conclusion']}"
        if body.get("matched"):
            return f"[{body['agent']}] {body['matched']} matched {body['bindings']} → {body['conclusion']}"
        n = len(body.get("considered") or [])
        return f"[{body['agent']}] no match in {n} rules → {body.get('conclusion', '?')}"
    if kind == "question":
        return f"[{body['from_agent']}] {body['text']}"
    if kind == "query":
        return f"{body['shape']}?  " + body["cypher"].replace("\n", "  |  ")
    if kind == "answer":
        return body["text"]
    if kind == "rule.retire":
        return f"retire rule: {body['name']}"
    if kind == "schema.retire":
        return f"retire schema: {body['name']}"
    if kind == "config":
        return "config: " + json.dumps(body)
    if kind == "sent":
        return f"→ {body['to']}: {body['text']}"
    if kind == "task":
        return f"TASK: {body['text']}"
    return json.dumps(body)[:100]


class LogView:
    def __init__(self, root: tk.Tk):
        self.root = root
        root.title("servicerm — packet log")
        root.geometry("900x520")
        root.configure(bg="#0d1117")

        style = ttk.Style()
        style.theme_use("clam")
        style.configure(
            "Log.Treeview",
            background="#0d1117", fieldbackground="#0d1117",
            foreground="#c9d1d9", rowheight=24, font=("Menlo", 12), borderwidth=0,
        )
        style.configure(
            "Log.Treeview.Heading",
            background="#161b22", foreground="#8b949e", font=("Menlo", 11, "bold"),
        )
        style.map("Log.Treeview", background=[("selected", "#1f6feb")])

        cols = ("time", "source", "kind", "summary")
        self.tree = ttk.Treeview(root, columns=cols, show="headings", style="Log.Treeview")
        for col, width, stretch in (
            ("time", 130, False), ("source", 110, False),
            ("kind", 90, False), ("summary", 540, True),
        ):
            self.tree.heading(col, text=col.upper())
            self.tree.column(col, width=width, stretch=stretch)
        for tag, color in KIND_COLORS.items():
            self.tree.tag_configure(tag, foreground=color)

        scroll = ttk.Scrollbar(root, orient="vertical", command=self.tree.yview)
        self.tree.configure(yscrollcommand=scroll.set)
        self.tree.pack(side="left", fill="both", expand=True)
        scroll.pack(side="right", fill="y")

        self.by_iid = {}
        self.tree.bind("<Button-1>", self._on_click)
        self.tree.bind("<Double-1>", self._on_double)

        self.seen = 0
        self.poll()

    def _on_click(self, event):
        row = self.tree.identify_row(event.y)
        if not row:
            self.tree.selection_remove(*self.tree.selection())
        elif row in self.tree.selection():
            self.tree.selection_remove(row)
            return "break"

    def _on_double(self, event):
        row = self.tree.identify_row(event.y)
        pkt = self.by_iid.get(row)
        if not pkt:
            return
        self.tree.selection_set(row)
        win = tk.Toplevel(self.root)
        win.title(pkt["id"])
        win.geometry("680x440")
        text = tk.Text(
            win, bg="#0d1117", fg="#c9d1d9", font=("Menlo", 12), wrap="word",
            insertbackground="#c9d1d9", padx=14, pady=12, borderwidth=0,
        )
        text.insert("1.0", json.dumps(pkt, indent=2))
        text.configure(state="disabled")
        text.pack(fill="both", expand=True)

    def poll(self):
        try:
            lines = LOG.read_text().splitlines() if LOG.exists() else []
        except OSError:
            lines = []
        if len(lines) != self.seen:
            if len(lines) < self.seen:
                # the log shrank — it was reborn or swapped. repaint from zero.
                self.tree.delete(*self.tree.get_children())
                self.by_iid.clear()
                self.seen = 0
            at_bottom = self.seen == 0 or self.tree.yview()[1] > 0.99
            for line in lines[self.seen:]:
                if not line.strip():
                    continue
                pkt = json.loads(line)
                tag = pkt["kind"].split(".")[0]
                iid = self.tree.insert(
                    "", "end",
                    values=(local_time(pkt["minted_at"]), pkt["source"],
                            pkt["kind"], summarize(pkt)),
                    tags=(tag,),
                )
                self.by_iid[iid] = pkt
            self.seen = len(lines)
            self.root.title(f"servicerm — packet log ({self.seen} packets)")
            if at_bottom and self.tree.get_children():
                self.tree.see(self.tree.get_children()[-1])
        self.root.after(1000, self.poll)


if __name__ == "__main__":
    root = tk.Tk()
    LogView(root)
    root.mainloop()

"""Replay the packet log into the graph.

Runs a full rebuild every time: delete the projection, replay the log.
That the result is identical on every run is the whole thesis — the graph
is disposable; the packet log is the truth. No LLM is involved here:
op packets were already interpreted at ingestion, so replay is
deterministic and free.

The log is fully self-describing: `schema` packets declare the tables
(and rules like exclusive_from), `op` packets fill them. Rebuild is two
passes — schema first, then ops — so declarations can arrive at any
point in the log's life. Changing the ontology = minting new schema
packets and replaying.
"""

import shutil
from datetime import datetime
from pathlib import Path

import ladybug as lb

import packets

HERE = Path(__file__).parent
GRAPH = HERE / "graph.lbdb"


def ddl(body: dict) -> str:
    if body["decl"] == "node":
        cols = ", ".join(f"{k} {v}" for k, v in body["props"].items())
        return f"CREATE NODE TABLE {body['name']}({cols})"
    pairs = body.get("pairs") or [[body["frm"], body["to"]]]
    froms = ", ".join(f"FROM {a} TO {b}" for a, b in pairs)
    cols = "".join(f", {k} {v}" for k, v in body.get("props", {}).items())
    return f"CREATE REL TABLE {body['name']}({froms}{cols})"


def fresh_connection(schema: list[dict]) -> lb.Connection:
    for p in (GRAPH, HERE / "graph.lbdb.wal"):
        if p.is_dir():
            shutil.rmtree(p)
        elif p.exists():
            p.unlink()
    conn = lb.Connection(lb.Database(str(GRAPH)))
    for body in schema:
        try:
            conn.execute(ddl(body))
        except Exception as exc:
            print(f"schema decl {body.get('name')} skipped: {exc}")
    return conn


def as_param(key: str, value):
    if key == "since":
        return datetime.fromisoformat(value.replace("Z", ""))
    return value


def apply_op(conn: lb.Connection, body: dict, exclusive_from: set[str]) -> None:
    op = body["op"]
    props = {k: as_param(k, v) for k, v in body.get("props", {}).items()}

    if op == "upsert_node":
        set_clause = ", ".join(f"n.{k} = ${k}" for k in props)
        q = f"MERGE (n:{body['table']} {{name: $name}})"
        if set_clause:
            q += f" SET {set_clause}"
        conn.execute(q, {"name": body["key"], **props})

    elif op == "upsert_edge":
        table = body["table"]
        (ft, fk), (tt, tk) = body["frm"], body["to"]
        # exclusive_from maps a table to every table it displaces from:
        # a placement-family edge (INSIDE/ATOP) retires old edges in both
        for cleared in exclusive_from.get(table, []):
            try:
                conn.execute(
                    f"MATCH (a:{ft} {{name: $fk}})-[r:{cleared}]->() DELETE r",
                    {"fk": fk},
                )
            except Exception:
                pass
        set_clause = ", ".join(f"r.{k} = ${k}" for k in props)
        q = (
            f"MATCH (a:{ft} {{name: $fk}}), (b:{tt} {{name: $tk}}) "
            f"MERGE (a)-[r:{table}]->(b)"
        )
        if set_clause:
            q += f" SET {set_clause}"
        conn.execute(q, {"fk": fk, "tk": tk, **props})

    elif op == "delete_node":
        # a correction: the graph forgets, the log remembers it once believed
        conn.execute(
            f"MATCH (n:{body['table']} {{name: $k}}) DETACH DELETE n",
            {"k": body["key"]},
        )

    else:
        raise ValueError(f"unknown op: {op}")


def rebuild() -> None:
    log = packets.read_all()
    retired = {p["body"]["name"] for p in log if p["kind"] == "schema.retire"}
    schema = [p["body"] for p in log
              if p["kind"] == "schema" and p["body"]["name"] not in retired]

    # table -> list of tables a new edge from the same source displaces
    families: dict[str, list[str]] = {}
    for b in schema:
        if b.get("family"):
            families.setdefault(b["family"], []).append(b["name"])
    exclusive_from: dict[str, list[str]] = {}
    for members in families.values():
        for name in members:
            exclusive_from[name] = members
    for b in schema:
        if b.get("exclusive_from"):
            exclusive_from.setdefault(b["name"], [b["name"]])

    conn = fresh_connection(schema)
    ops = [p for p in log if p["kind"] == "op"
           and p["body"].get("table") not in retired]
    failed = 0
    for pkt in ops:
        try:
            apply_op(conn, pkt["body"], exclusive_from)
        except Exception as exc:
            failed += 1
            print(f"op {pkt['id']} failed, skipped: {exc}")
    note = f", {failed} failed" if failed else ""
    print(f"rebuilt {GRAPH.name}: {len(schema)} schema decls, {len(ops)} ops{note}")


if __name__ == "__main__":
    rebuild()

input.content:
"""Scribe (agent id: scribe.v0) — the deterministic interpreter.

Constitution: code may contain mechanisms; code may not contain
vocabulary. The words — person, container, battery, hold, own — and
every fact about them live on the tape: schema, config, capability,
and rule packets. This file knows only how to segment, match, resolve,
walk IS_A chains, check capabilities the tape declares, and mint.

Every raw packet gets exactly one reasoning packet. Guardrails (repair
speech, name length) run centrally over every action's output. Every
minted packet cites its causes in the envelope `re` list.
"""

import re

import packets

AGENT = "scribe.v0"

NODE_TABLES = ("Thing", "Kind")

DEFAULT_CONFIG = {
    "max_name_words": 4,
    "repair_words": ["sorry", "actually", "i meant", "scratch that", "never mind"],
    "segment_markers": ["create", "there is", "where is", "who owns",
                        "forget", "remove", "delete"],
    "mechanisms": {"in": {"rel": "INSIDE", "requires": "hold"},
                   "on": {"rel": "ATOP", "requires": "support"}},
    "prep_words": {"in": "in", "into": "in", "inside": "in",
                   "on": "on", "onto": "on"},
    "own_requires": "own",
}

RESERVED_KINDS = ("relationship", "rule")


# ------------------------------------------------------------- tape reads

def get_config(log: list[dict]) -> dict:
    cfg = dict(DEFAULT_CONFIG)
    for p in log:
        if p["kind"] == "config":
            cfg.update(p["body"])
    return cfg


def normalize(text: str) -> str:
    lines = [re.sub(r"[^\w\s]", "", ln.lower()).strip() for ln in text.splitlines()]
    lines = [ln for ln in lines if ln]
    deduped = [ln for i, ln in enumerate(lines) if i == 0 or ln != lines[i - 1]]
    return " ".join(deduped)


def segment(text: str, markers: list[str]) -> list[str]:
    words = text.split()
    cuts = [0]
    for i in range(1, len(words)):
        for mk in markers:
            mw = mk.split()
            if words[i:i + len(mw)] == mw:
                cuts.append(i)
                break
    return [" ".join(words[a:b]) for a, b in zip(cuts, cuts[1:] + [len(words)])]


def known_nodes(log: list[dict]) -> dict[str, set[str]]:
    known = {t: set() for t in NODE_TABLES}
    for p in log:
        if p["kind"] != "op":
            continue
        body = p["body"]
        if body["op"] == "upsert_node" and body["table"] in known:
            known[body["table"]].add(body["key"])
        elif body["op"] == "delete_node" and body["table"] in known:
            known[body["table"]].discard(body["key"])
    return known


def build_ctx(log: list[dict]) -> dict:
    """Everything an action may consult, all read from the tape."""
    known = known_nodes(log)
    direct: dict[str, set] = {}
    up: dict[str, set] = {}
    for p in log:
        if p["kind"] == "op" and p["body"]["op"] == "upsert_edge" and p["body"]["table"] == "IS_A":
            (ft, fk), (_, tk) = p["body"]["frm"], p["body"]["to"]
            (up if ft == "Kind" else direct).setdefault(fk, set()).add(tk)
    caps: dict[str, set] = {}
    for p in log:
        if p["kind"] == "capability":
            caps.setdefault(p["body"]["kind"], set()).add(p["body"]["can"])

    def ancestry(name: str) -> set[str]:
        seen: set[str] = set()
        stack = list(direct.get(name, ())) + list(up.get(name, ()))
        if name in known["Kind"]:
            seen.add(name)
        while stack:
            k = stack.pop()
            if k not in seen:
                seen.add(k)
                stack.extend(up.get(k, ()))
        return seen

    def can(name: str, capability: str) -> bool:
        return any(capability in caps.get(k, ()) for k in ancestry(name))

    return {"log": log, "known": known, "ancestry": ancestry,
            "can": can, "cfg": get_config(log)}


def _strip_possessive(x: str, ctx: dict) -> str:
    first, _, rest = x.partition(" ")
    if rest and first.endswith("s"):
        owner = first[:-1]
        if owner in ctx["known"]["Thing"] and ctx["can"](owner, ctx["cfg"]["own_requires"]):
            return rest.strip()
    return x


def resolve(phrase: str, ctx: dict) -> dict:
    """The one noun-phrase resolver. Determiners are data: 'the/my' =
    definite (instance), 'a/an' = indefinite (class), bare = unknown."""
    p = phrase.strip()
    for prefix in ("of kind ", "of type "):
        if p.startswith(prefix):
            p = p[len(prefix):].strip()
    definite = None
    for det, d in (("the ", True), ("my ", True), ("an ", False), ("a ", False)):
        if p.startswith(det):
            definite, p = d, p[len(det):].strip()
            break
    p = _strip_possessive(p, ctx)
    known = ctx["known"]
    table = "Thing" if p in known["Thing"] else "Kind" if p in known["Kind"] else None
    return {"definite": definite, "key": p, "table": table}


def _question(text: str, about: dict, for_humans: bool = False) -> dict:
    q = {"_kind": "question", "from_agent": AGENT, "about": about, "text": text}
    if for_humans:
        q["for"] = "humans"
    return q


def _mechanism(prep: str, y: str, ctx: dict):
    """Preposition -> mechanism, validated by the tape's capabilities."""
    cfg = ctx["cfg"]
    slot = cfg["prep_words"].get(prep)
    if prep == "to":
        for s, mech in cfg["mechanisms"].items():
            if ctx["can"](y, mech["requires"]):
                slot = s
                break
        slot = slot or "in"
    if not slot:
        return None, None
    return slot, cfg["mechanisms"][slot]


# ---------------------------------------------------------------- actions

def action_place(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    g = m.groupdict()
    rx = resolve(g["x"], ctx)
    ry = resolve(g["y"], ctx)
    prep = (g.get("prep") or "in").strip()
    for role in ("xowner", "yowner"):
        owner = (g.get(role) or "").strip()
        if owner and owner not in ctx["known"]["Thing"]:
            return [_question(f"who is '{owner}'?",
                              {"token": owner, "surface": owner + "s",
                               "table": "Thing", "role": "owner"})]
    slot, mech = _mechanism(prep, ry["key"], ctx)
    if not mech:
        return []
    if ry["table"] == "Thing" and not ctx["can"](ry["key"], mech["requires"]):
        return [_question(
            f"can things go {slot} the {ry['key']}? "
            f"(nothing says its kind can {mech['requires']})",
            {"token": ry["key"], "table": "Kind", "role": "capability",
             "needed": mech["requires"]}, for_humans=True)]
    since = raw["minted_at"].replace("+00:00", "")
    ops = [{"op": "upsert_node", "table": "Thing", "key": rx["key"], "props": {}}]
    if ry["table"] != "Thing":
        # unknown place: create it, but it has no capability yet — ask
        return [_question(
            f"what is the {ry['key']}? (i need to know its kind before "
            f"things can go {slot} it)",
            {"token": ry["key"], "table": "Kind", "role": "capability",
             "needed": mech["requires"]}, for_humans=True)]
    ops += [
        {"op": "upsert_edge", "table": mech["rel"],
         "frm": ["Thing", rx["key"]], "to": ["Thing", ry["key"]],
         "props": {"since": since}},
    ]
    return ops


def action_imperative_task(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    g = m.groupdict()
    x, y = g["x"].strip(), g["y"].strip()
    prep = (g.get("prep") or "in").strip()
    return [{"_kind": "task", "what": "place", "x": x, "prep": prep, "y": y,
             "text": f"put the {x} {prep} the {y}"}]


def action_declare_thing(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    """One declaration action for every category: Thing + IS_A kind."""
    k, x = m.group("k").strip(), m.group("x").strip()
    if k in RESERVED_KINDS:
        return [_question(
            f"i heard 'create {k} …' but couldn't parse the rest — "
            f"try 'create relationship name between a and b'",
            {"token": x, "table": "Kind", "role": "declaration"}, for_humans=True)]
    since = raw["minted_at"].replace("+00:00", "")
    if k == "kind":
        return [{"op": "upsert_node", "table": "Kind", "key": x, "props": {}}]
    ops = [
        {"op": "upsert_node", "table": "Thing", "key": x, "props": {}},
        {"op": "upsert_node", "table": "Kind", "key": k, "props": {}},
        {"op": "upsert_edge", "table": "IS_A",
         "frm": ["Thing", x], "to": ["Kind", k], "props": {"since": since}},
    ]
    owner = (m.groupdict().get("owner") or "").strip()
    if owner:
        ops += [
            {"op": "upsert_node", "table": "Thing", "key": owner, "props": {}},
            {"op": "upsert_edge", "table": "OWNS",
             "frm": ["Thing", owner], "to": ["Thing", x], "props": {"since": since}},
        ]
    return ops


def action_set_kind(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    """Determiner-routed IS_A, fully uniform: 'cal is a person' and
    'the m12 is a battery' are the same shape of fact."""
    rx = resolve(m.group("x"), ctx)
    rk = resolve(m.group("k"), ctx)
    since = raw["minted_at"].replace("+00:00", "")
    if rk["key"] == "kind":
        return [{"op": "upsert_node", "table": "Kind", "key": rx["key"], "props": {}}]
    class_statement = rx["definite"] is False or rx["table"] == "Kind"
    frm_table = "Kind" if class_statement else "Thing"
    return [
        {"op": "upsert_node", "table": frm_table, "key": rx["key"], "props": {}},
        {"op": "upsert_node", "table": "Kind", "key": rk["key"], "props": {}},
        {"op": "upsert_edge", "table": "IS_A",
         "frm": [frm_table, rx["key"]], "to": ["Kind", rk["key"]],
         "props": {"since": since}},
    ]


def action_declare_capability(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    """'a truck can hold' — physics, spoken."""
    k, cap = m.group("k").strip(), m.group("cap").strip()
    return [
        {"op": "upsert_node", "table": "Kind", "key": k, "props": {}},
        {"_kind": "capability", "kind": k, "can": cap},
    ]


def action_declare_relationship(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    tail = (m.groupdict().get("tail") or "").strip()
    verb = m.group("name").lower()
    aw, bw = m.group("a"), m.group("b")
    if tail:
        return [_question(
            f"i understood 'relationship {verb} between {aw} and {bw}' "
            f"but not '{tail}' — declare without it, or teach me what it means",
            {"token": tail, "table": "Kind", "role": "declaration"}, for_humans=True)]
    kinds = [None if aw in ("thing", "anything") else aw,
             None if bw in ("thing", "anything") else bw]
    schema = {"_kind": "schema", "decl": "rel", "name": verb.upper(),
              "pairs": [["Thing", "Thing"]], "props": {"since": "TIMESTAMP"}}
    if any(kinds):
        schema["kinds"] = kinds
    return [
        schema,
        {"_kind": "rule", "name": f"spoken.{verb}", "action": "assert_rel",
         "pattern": rf"^(?:the\s+|my\s+)?(?P<x>.+?)\s+(?P<rel>{verb})\s+"
                    rf"(?:the\s+|my\s+)?(?P<y>.+)$"},
    ]


def action_incomplete_relationship(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    name = m.group("name").strip()
    return [_question(f"create relationship {name}: between what and what?",
                      {"token": name, "table": "Kind", "role": "declaration"},
                      for_humans=True)]


def action_forget(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    x = m.group("x").strip()
    if x.startswith("relationship "):
        verb = x.split(None, 1)[1].strip()
        return [
            {"_kind": "rule.retire", "name": f"spoken.{verb}"},
            {"_kind": "schema.retire", "name": verb.upper()},
        ]
    known = ctx["known"]
    table = "Thing" if x in known["Thing"] else "Kind" if x in known["Kind"] else None
    if not table:
        return []
    return [{"op": "delete_node", "table": table, "key": x,
             "note": "spoken correction"}]


def action_assert_rel(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    g = m.groupdict()
    x, y, rel = g["x"].strip(), g["y"].strip(), g["rel"].strip().upper()
    log = ctx["log"]
    retired = {p["body"]["name"] for p in log if p["kind"] == "schema.retire"}
    pairs, kind_req = None, None
    for p in log:
        body = p["body"]
        if p["kind"] == "schema" and body.get("decl") == "rel" and body["name"] == rel:
            pairs = body.get("pairs")
            kind_req = body.get("kinds")
    if not pairs or rel in retired:
        return []
    if kind_req:
        for thing, needed in zip((x, y), kind_req):
            if needed and needed not in ctx["ancestry"](thing):
                return [_question(
                    f"is the {thing} a {needed}? "
                    f"({rel.lower()} only connects "
                    f"{kind_req[0] or 'anything'} to {kind_req[1] or 'anything'})",
                    {"token": thing, "table": "Kind", "role": "kind",
                     "needed": needed}, for_humans=True)]
    since = raw["minted_at"].replace("+00:00", "")
    return [
        {"op": "upsert_node", "table": "Thing", "key": x, "props": {}},
        {"op": "upsert_node", "table": "Thing", "key": y, "props": {}},
        {"op": "upsert_edge", "table": rel,
         "frm": ["Thing", x], "to": ["Thing", y], "props": {"since": since}},
    ]


def action_query_place(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    rx = resolve(m.group("x"), ctx)
    if rx["table"] != "Thing":
        return [_question(f"what is '{rx['key']}'?",
                          {"token": rx["key"], "surface": rx["key"],
                           "table": "Thing", "role": "subject"})]
    return [{
        "_kind": "query",
        "shape": "place",
        "subject": ["Thing", rx["key"]],
        "cypher": ("MATCH (a:Thing {name: $name})-[r:INSIDE]->(b:Thing) RETURN b.name\n"
                   "MATCH (a:Thing {name: $name})-[r:ATOP]->(b:Thing) RETURN b.name"),
        "params": {"name": rx["key"]},
        "question": normalize(raw["body"]["text"]),
    }]


def action_query_owner(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    rx = resolve(m.group("x"), ctx)
    if rx["table"] != "Thing":
        return [_question(f"what is '{rx['key']}'?",
                          {"token": rx["key"], "surface": rx["key"],
                           "table": "Thing", "role": "subject"})]
    return [{
        "_kind": "query",
        "shape": "owner",
        "subject": ["Thing", rx["key"]],
        "cypher": "MATCH (p:Thing)-[:OWNS]->(b:Thing {name: $name}) RETURN p.name",
        "params": {"name": rx["key"]},
        "question": normalize(raw["body"]["text"]),
    }]


def action_assert_owns(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    p, x = m.group("p").strip(), m.group("x").strip()
    if p == "who":
        return []
    if p not in ctx["known"]["Thing"]:
        return [_question(f"who is '{p}'?",
                          {"token": p, "surface": p, "table": "Thing", "role": "owner"})]
    if not ctx["can"](p, ctx["cfg"]["own_requires"]):
        return [_question(
            f"can {p} own things? (nothing says its kind can own)",
            {"token": p, "table": "Kind", "role": "capability",
             "needed": ctx["cfg"]["own_requires"]}, for_humans=True)]
    since = raw["minted_at"].replace("+00:00", "")
    return [
        {"op": "upsert_node", "table": "Thing", "key": x, "props": {}},
        {"op": "upsert_edge", "table": "OWNS",
         "frm": ["Thing", p], "to": ["Thing", x], "props": {"since": since}},
    ]


def action_answer_buzz(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    x = m.group("x").strip()
    log = ctx["log"]
    by_id = {p["id"]: p for p in log}
    answered = {p["body"].get("answers") for p in log if p["body"].get("answers")}
    unresolved: set = set()
    for p in log:
        if (p["kind"] == "reasoning" and p["body"].get("agent") == "squint.v0"
                and p["body"].get("conclusion") == "unresolved"):
            unresolved.update(p.get("re") or [])
    candidates = [
        q for q in log
        if q["kind"] == "question"
        and q["id"] not in answered
        and (q["body"].get("for") == "humans" or q["id"] in unresolved)
    ]
    if not candidates:
        return []
    target = candidates[-1]
    about = target["body"].get("about", {})
    role = about.get("role")
    first = x.split()[0] if x.split() else ""
    is_placement_answer = first in ("in", "on", "inside", "atop")

    if role == "placement" and is_placement_answer:
        return [
            {"_kind": "raw.response", "text": x, "answers": target["id"]},
            {"_kind": "raw.restated", "text": f"the {about['token']} is {x}",
             "answers": target["id"], "note": "composed from hey-buzz answer"},
        ]
    if role in ("owner", "subject") and not is_placement_answer:
        orig_id = (target.get("re") or [None])[0]
        orig = by_id.get(orig_id)
        token = about.get("token", "")
        surface = about.get("surface", token)
        if orig and orig["kind"].startswith("raw.") and surface:
            replacement = x + surface[len(token):] if surface.startswith(token) else x
            return [
                {"_kind": "raw.response", "text": x, "answers": target["id"]},
                {"_kind": "raw.restated",
                 "text": normalize(orig["body"]["text"]).replace(surface, replacement),
                 "answers": target["id"], "note": "composed from hey-buzz answer"},
            ]
    if role in ("kind", "capability") and not is_placement_answer and x not in ("yes", "no"):
        token = about.get("token", "")
        if token:
            return [
                {"_kind": "raw.response", "text": x, "answers": target["id"]},
                {"_kind": "raw.restated", "text": f"the {token} is a {x}",
                 "answers": target["id"], "note": "composed from hey-buzz answer"},
            ]
    return [{
        "_kind": "raw.response",
        "text": x,
        "note": f"answer shape doesn't fit open question '{target['body']['text']}' — left open",
    }]


ACTIONS = {
    "place": action_place,
    "imperative_task": action_imperative_task,
    "declare_thing": action_declare_thing,
    "set_kind": action_set_kind,
    "declare_capability": action_declare_capability,
    "declare_relationship": action_declare_relationship,
    "incomplete_relationship": action_incomplete_relationship,
    "forget": action_forget,
    "assert_rel": action_assert_rel,
    "query_place": action_query_place,
    "query_owner": action_query_owner,
    "assert_owns": action_assert_owns,
    "answer_buzz": action_answer_buzz,
}


# ------------------------------------------------------------------ run

def load_rules(log: list[dict]) -> list[dict]:
    retired = {p["body"]["name"] for p in log if p["kind"] == "rule.retire"}
    return [
        {"name": p["body"]["name"], "rx": re.compile(p["body"]["pattern"]),
         "action": p["body"]["action"]}
        for p in log
        if p["kind"] == "rule"
        and p["body"]["name"] not in retired
        and p["body"]["action"] in ACTIONS
    ]


def run() -> list[dict]:
    log = packets.read_all()
    done: set = set()
    for p in log:
        if p["kind"] == "reasoning":
            done.update(p.get("re") or [])
            done.add(p["body"].get("re"))
    pending = [p for p in log if p["kind"].startswith("raw.") and p["id"] not in done]
    rules = load_rules(log)
    ctx = build_ctx(log)
    cfg = ctx["cfg"]
    results = []

    for raw in pending:
        text = normalize(raw["body"]["text"])

        if raw["kind"] != "raw.segment":
            clauses = segment(text, cfg["segment_markers"])
            if len(clauses) > 1:
                r = packets.mint("reasoning", {
                    "agent": AGENT, "method": "segmentation",
                    "considered": None, "matched": None,
                    "bindings": {"clauses": clauses},
                    "conclusion": f"split into {len(clauses)} statements",
                }, source=AGENT, re=[raw["id"]])
                for clause in clauses:
                    packets.mint("raw.segment", {"text": clause},
                                 source=AGENT, re=[raw["id"], r["id"]])
                print(f"{raw['id']}  \"{raw['body']['text'][:50]}\"  -> segmented ({len(clauses)})")
                results.append({"id": raw["id"], "text": raw["body"]["text"],
                                "ops": 0, "conclusion": "segmented"})
                continue

        if any(w in text for w in cfg["repair_words"]):
            packets.mint("reasoning", {
                "agent": AGENT, "method": "repair-word guardrail",
                "considered": None, "matched": None, "bindings": None,
                "conclusion": "repair — not parsed, please restate",
            }, source=AGENT, re=[raw["id"]])
            print(f"{raw['id']}  \"{raw['body']['text'][:50]}\"  -> repair, not parsed")
            results.append({"id": raw["id"], "text": raw["body"]["text"],
                            "ops": 0, "conclusion": "repair"})
            continue

        match, matched_rule = None, None
        for rule in rules:
            m = rule["rx"].match(text)
            if m:
                match, matched_rule = m, rule
                break

        bodies = ACTIONS[matched_rule["action"]](match, raw, ctx) if matched_rule else []

        long_names = [b["key"] for b in bodies
                      if b.get("op") == "upsert_node"
                      and len(b["key"].split()) > cfg["max_name_words"]]
        if long_names:
            bodies = [_question(
                f"did you really mean to name a thing '{long_names[0]}'?",
                {"token": long_names[0], "table": "Thing", "role": "naming"},
                for_humans=True)]

        if not matched_rule:
            conclusion = "skip"
        elif any(b.get("_kind") == "question" for b in bodies):
            conclusion = "question"
        else:
            conclusion = matched_rule["action"]

        reasoning_body = {
            "agent": AGENT, "method": "regex over normalized text",
            "considered": [r["name"] for r in rules],
            "matched": matched_rule["name"] if matched_rule else None,
            "bindings": ({k: (v or "").strip() for k, v in match.groupdict().items()}
                         if match else None),
            "conclusion": conclusion,
        }
        if conclusion == "imperative_task":
            reasoning_body["mood"] = "imperative — recorded as open task, not fact"
        elif match and "subj" in match.groupdict():
            subj = (match.group("subj") or "").strip()
            reasoning_body["mood"] = "report" if subj else "report (elliptical)"
        reasoning = packets.mint("reasoning", reasoning_body,
                                 source=AGENT, re=[raw["id"]])

        emitted = 0
        for body in bodies:
            kind = body.pop("_kind", "op")
            body["via"] = matched_rule["name"]
            packets.mint(kind, body, source=AGENT, re=[raw["id"], reasoning["id"]])
            emitted += 1
            if body.get("op") == "upsert_node" and body["table"] in ctx["known"]:
                ctx["known"][body["table"]].add(body["key"])

        print(f"{raw['id']}  \"{raw['body']['text'][:50]}\"  -> {conclusion} ({emitted} emitted)")
        results.append({"id": raw["id"], "text": raw["body"]["text"],
                        "ops": emitted, "conclusion": conclusion})

    if not pending:
        print("nothing pending")
    return results


if __name__ == "__main__":
    run()

toolUseResult.content:
"""Scribe (agent id: scribe.v0) — the deterministic interpreter.

Constitution: code may contain mechanisms; code may not contain
vocabulary. The words — person, container, battery, hold, own — and
every fact about them live on the tape: schema, config, capability,
and rule packets. This file knows only how to segment, match, resolve,
walk IS_A chains, check capabilities the tape declares, and mint.

Every raw packet gets exactly one reasoning packet. Guardrails (repair
speech, name length) run centrally over every action's output. Every
minted packet cites its causes in the envelope `re` list.
"""

import re

import packets

AGENT = "scribe.v0"

NODE_TABLES = ("Thing", "Kind")

DEFAULT_CONFIG = {
    "max_name_words": 4,
    "repair_words": ["sorry", "actually", "i meant", "scratch that", "never mind"],
    "segment_markers": ["create", "there is", "where is", "who owns",
                        "forget", "remove", "delete"],
    "mechanisms": {"in": {"rel": "INSIDE", "requires": "hold"},
                   "on": {"rel": "ATOP", "requires": "support"}},
    "prep_words": {"in": "in", "into": "in", "inside": "in",
                   "on": "on", "onto": "on"},
    "own_requires": "own",
}

RESERVED_KINDS = ("relationship", "rule")


# ------------------------------------------------------------- tape reads

def get_config(log: list[dict]) -> dict:
    cfg = dict(DEFAULT_CONFIG)
    for p in log:
        if p["kind"] == "config":
            cfg.update(p["body"])
    return cfg


def normalize(text: str) -> str:
    lines = [re.sub(r"[^\w\s]", "", ln.lower()).strip() for ln in text.splitlines()]
    lines = [ln for ln in lines if ln]
    deduped = [ln for i, ln in enumerate(lines) if i == 0 or ln != lines[i - 1]]
    return " ".join(deduped)


def segment(text: str, markers: list[str]) -> list[str]:
    words = text.split()
    cuts = [0]
    for i in range(1, len(words)):
        for mk in markers:
            mw = mk.split()
            if words[i:i + len(mw)] == mw:
                cuts.append(i)
                break
    return [" ".join(words[a:b]) for a, b in zip(cuts, cuts[1:] + [len(words)])]


def known_nodes(log: list[dict]) -> dict[str, set[str]]:
    known = {t: set() for t in NODE_TABLES}
    for p in log:
        if p["kind"] != "op":
            continue
        body = p["body"]
        if body["op"] == "upsert_node" and body["table"] in known:
            known[body["table"]].add(body["key"])
        elif body["op"] == "delete_node" and body["table"] in known:
            known[body["table"]].discard(body["key"])
    return known


def build_ctx(log: list[dict]) -> dict:
    """Everything an action may consult, all read from the tape."""
    known = known_nodes(log)
    direct: dict[str, set] = {}
    up: dict[str, set] = {}
    for p in log:
        if p["kind"] == "op" and p["body"]["op"] == "upsert_edge" and p["body"]["table"] == "IS_A":
            (ft, fk), (_, tk) = p["body"]["frm"], p["body"]["to"]
            (up if ft == "Kind" else direct).setdefault(fk, set()).add(tk)
    caps: dict[str, set] = {}
    for p in log:
        if p["kind"] == "capability":
            caps.setdefault(p["body"]["kind"], set()).add(p["body"]["can"])

    def ancestry(name: str) -> set[str]:
        seen: set[str] = set()
        stack = list(direct.get(name, ())) + list(up.get(name, ()))
        if name in known["Kind"]:
            seen.add(name)
        while stack:
            k = stack.pop()
            if k not in seen:
                seen.add(k)
                stack.extend(up.get(k, ()))
        return seen

    def can(name: str, capability: str) -> bool:
        return any(capability in caps.get(k, ()) for k in ancestry(name))

    return {"log": log, "known": known, "ancestry": ancestry,
            "can": can, "cfg": get_config(log)}


def _strip_possessive(x: str, ctx: dict) -> str:
    first, _, rest = x.partition(" ")
    if rest and first.endswith("s"):
        owner = first[:-1]
        if owner in ctx["known"]["Thing"] and ctx["can"](owner, ctx["cfg"]["own_requires"]):
            return rest.strip()
    return x


def resolve(phrase: str, ctx: dict) -> dict:
    """The one noun-phrase resolver. Determiners are data: 'the/my' =
    definite (instance), 'a/an' = indefinite (class), bare = unknown."""
    p = phrase.strip()
    for prefix in ("of kind ", "of type "):
        if p.startswith(prefix):
            p = p[len(prefix):].strip()
    definite = None
    for det, d in (("the ", True), ("my ", True), ("an ", False), ("a ", False)):
        if p.startswith(det):
            definite, p = d, p[len(det):].strip()
            break
    p = _strip_possessive(p, ctx)
    known = ctx["known"]
    table = "Thing" if p in known["Thing"] else "Kind" if p in known["Kind"] else None
    return {"definite": definite, "key": p, "table": table}


def _question(text: str, about: dict, for_humans: bool = False) -> dict:
    q = {"_kind": "question", "from_agent": AGENT, "about": about, "text": text}
    if for_humans:
        q["for"] = "humans"
    return q


def _mechanism(prep: str, y: str, ctx: dict):
    """Preposition -> mechanism, validated by the tape's capabilities."""
    cfg = ctx["cfg"]
    slot = cfg["prep_words"].get(prep)
    if prep == "to":
        for s, mech in cfg["mechanisms"].items():
            if ctx["can"](y, mech["requires"]):
                slot = s
                break
        slot = slot or "in"
    if not slot:
        return None, None
    return slot, cfg["mechanisms"][slot]


# ---------------------------------------------------------------- actions

def action_place(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    g = m.groupdict()
    rx = resolve(g["x"], ctx)
    ry = resolve(g["y"], ctx)
    prep = (g.get("prep") or "in").strip()
    for role in ("xowner", "yowner"):
        owner = (g.get(role) or "").strip()
        if owner and owner not in ctx["known"]["Thing"]:
            return [_question(f"who is '{owner}'?",
                              {"token": owner, "surface": owner + "s",
                               "table": "Thing", "role": "owner"})]
    slot, mech = _mechanism(prep, ry["key"], ctx)
    if not mech:
        return []
    if ry["table"] == "Thing" and not ctx["can"](ry["key"], mech["requires"]):
        return [_question(
            f"can things go {slot} the {ry['key']}? "
            f"(nothing says its kind can {mech['requires']})",
            {"token": ry["key"], "table": "Kind", "role": "capability",
             "needed": mech["requires"]}, for_humans=True)]
    since = raw["minted_at"].replace("+00:00", "")
    ops = [{"op": "upsert_node", "table": "Thing", "key": rx["key"], "props": {}}]
    if ry["table"] != "Thing":
        # unknown place: create it, but it has no capability yet — ask
        return [_question(
            f"what is the {ry['key']}? (i need to know its kind before "
            f"things can go {slot} it)",
            {"token": ry["key"], "table": "Kind", "role": "capability",
             "needed": mech["requires"]}, for_humans=True)]
    ops += [
        {"op": "upsert_edge", "table": mech["rel"],
         "frm": ["Thing", rx["key"]], "to": ["Thing", ry["key"]],
         "props": {"since": since}},
    ]
    return ops


def action_imperative_task(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    g = m.groupdict()
    x, y = g["x"].strip(), g["y"].strip()
    prep = (g.get("prep") or "in").strip()
    return [{"_kind": "task", "what": "place", "x": x, "prep": prep, "y": y,
             "text": f"put the {x} {prep} the {y}"}]


def action_declare_thing(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    """One declaration action for every category: Thing + IS_A kind."""
    k, x = m.group("k").strip(), m.group("x").strip()
    if k in RESERVED_KINDS:
        return [_question(
            f"i heard 'create {k} …' but couldn't parse the rest — "
            f"try 'create relationship name between a and b'",
            {"token": x, "table": "Kind", "role": "declaration"}, for_humans=True)]
    since = raw["minted_at"].replace("+00:00", "")
    if k == "kind":
        return [{"op": "upsert_node", "table": "Kind", "key": x, "props": {}}]
    ops = [
        {"op": "upsert_node", "table": "Thing", "key": x, "props": {}},
        {"op": "upsert_node", "table": "Kind", "key": k, "props": {}},
        {"op": "upsert_edge", "table": "IS_A",
         "frm": ["Thing", x], "to": ["Kind", k], "props": {"since": since}},
    ]
    owner = (m.groupdict().get("owner") or "").strip()
    if owner:
        ops += [
            {"op": "upsert_node", "table": "Thing", "key": owner, "props": {}},
            {"op": "upsert_edge", "table": "OWNS",
             "frm": ["Thing", owner], "to": ["Thing", x], "props": {"since": since}},
        ]
    return ops


def action_set_kind(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    """Determiner-routed IS_A, fully uniform: 'cal is a person' and
    'the m12 is a battery' are the same shape of fact."""
    rx = resolve(m.group("x"), ctx)
    rk = resolve(m.group("k"), ctx)
    since = raw["minted_at"].replace("+00:00", "")
    if rk["key"] == "kind":
        return [{"op": "upsert_node", "table": "Kind", "key": rx["key"], "props": {}}]
    class_statement = rx["definite"] is False or rx["table"] == "Kind"
    frm_table = "Kind" if class_statement else "Thing"
    return [
        {"op": "upsert_node", "table": frm_table, "key": rx["key"], "props": {}},
        {"op": "upsert_node", "table": "Kind", "key": rk["key"], "props": {}},
        {"op": "upsert_edge", "table": "IS_A",
         "frm": [frm_table, rx["key"]], "to": ["Kind", rk["key"]],
         "props": {"since": since}},
    ]


def action_declare_capability(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    """'a truck can hold' — physics, spoken."""
    k, cap = m.group("k").strip(), m.group("cap").strip()
    return [
        {"op": "upsert_node", "table": "Kind", "key": k, "props": {}},
        {"_kind": "capability", "kind": k, "can": cap},
    ]


def action_declare_relationship(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    tail = (m.groupdict().get("tail") or "").strip()
    verb = m.group("name").lower()
    aw, bw = m.group("a"), m.group("b")
    if tail:
        return [_question(
            f"i understood 'relationship {verb} between {aw} and {bw}' "
            f"but not '{tail}' — declare without it, or teach me what it means",
            {"token": tail, "table": "Kind", "role": "declaration"}, for_humans=True)]
    kinds = [None if aw in ("thing", "anything") else aw,
             None if bw in ("thing", "anything") else bw]
    schema = {"_kind": "schema", "decl": "rel", "name": verb.upper(),
              "pairs": [["Thing", "Thing"]], "props": {"since": "TIMESTAMP"}}
    if any(kinds):
        schema["kinds"] = kinds
    return [
        schema,
        {"_kind": "rule", "name": f"spoken.{verb}", "action": "assert_rel",
         "pattern": rf"^(?:the\s+|my\s+)?(?P<x>.+?)\s+(?P<rel>{verb})\s+"
                    rf"(?:the\s+|my\s+)?(?P<y>.+)$"},
    ]


def action_incomplete_relationship(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    name = m.group("name").strip()
    return [_question(f"create relationship {name}: between what and what?",
                      {"token": name, "table": "Kind", "role": "declaration"},
                      for_humans=True)]


def action_forget(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    x = m.group("x").strip()
    if x.startswith("relationship "):
        verb = x.split(None, 1)[1].strip()
        return [
            {"_kind": "rule.retire", "name": f"spoken.{verb}"},
            {"_kind": "schema.retire", "name": verb.upper()},
        ]
    known = ctx["known"]
    table = "Thing" if x in known["Thing"] else "Kind" if x in known["Kind"] else None
    if not table:
        return []
    return [{"op": "delete_node", "table": table, "key": x,
             "note": "spoken correction"}]


def action_assert_rel(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    g = m.groupdict()
    x, y, rel = g["x"].strip(), g["y"].strip(), g["rel"].strip().upper()
    log = ctx["log"]
    retired = {p["body"]["name"] for p in log if p["kind"] == "schema.retire"}
    pairs, kind_req = None, None
    for p in log:
        body = p["body"]
        if p["kind"] == "schema" and body.get("decl") == "rel" and body["name"] == rel:
            pairs = body.get("pairs")
            kind_req = body.get("kinds")
    if not pairs or rel in retired:
        return []
    if kind_req:
        for thing, needed in zip((x, y), kind_req):
            if needed and needed not in ctx["ancestry"](thing):
                return [_question(
                    f"is the {thing} a {needed}? "
                    f"({rel.lower()} only connects "
                    f"{kind_req[0] or 'anything'} to {kind_req[1] or 'anything'})",
                    {"token": thing, "table": "Kind", "role": "kind",
                     "needed": needed}, for_humans=True)]
    since = raw["minted_at"].replace("+00:00", "")
    return [
        {"op": "upsert_node", "table": "Thing", "key": x, "props": {}},
        {"op": "upsert_node", "table": "Thing", "key": y, "props": {}},
        {"op": "upsert_edge", "table": rel,
         "frm": ["Thing", x], "to": ["Thing", y], "props": {"since": since}},
    ]


def action_query_place(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    rx = resolve(m.group("x"), ctx)
    if rx["table"] != "Thing":
        return [_question(f"what is '{rx['key']}'?",
                          {"token": rx["key"], "surface": rx["key"],
                           "table": "Thing", "role": "subject"})]
    return [{
        "_kind": "query",
        "shape": "place",
        "subject": ["Thing", rx["key"]],
        "cypher": ("MATCH (a:Thing {name: $name})-[r:INSIDE]->(b:Thing) RETURN b.name\n"
                   "MATCH (a:Thing {name: $name})-[r:ATOP]->(b:Thing) RETURN b.name"),
        "params": {"name": rx["key"]},
        "question": normalize(raw["body"]["text"]),
    }]


def action_query_owner(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    rx = resolve(m.group("x"), ctx)
    if rx["table"] != "Thing":
        return [_question(f"what is '{rx['key']}'?",
                          {"token": rx["key"], "surface": rx["key"],
                           "table": "Thing", "role": "subject"})]
    return [{
        "_kind": "query",
        "shape": "owner",
        "subject": ["Thing", rx["key"]],
        "cypher": "MATCH (p:Thing)-[:OWNS]->(b:Thing {name: $name}) RETURN p.name",
        "params": {"name": rx["key"]},
        "question": normalize(raw["body"]["text"]),
    }]


def action_assert_owns(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    p, x = m.group("p").strip(), m.group("x").strip()
    if p == "who":
        return []
    if p not in ctx["known"]["Thing"]:
        return [_question(f"who is '{p}'?",
                          {"token": p, "surface": p, "table": "Thing", "role": "owner"})]
    if not ctx["can"](p, ctx["cfg"]["own_requires"]):
        return [_question(
            f"can {p} own things? (nothing says its kind can own)",
            {"token": p, "table": "Kind", "role": "capability",
             "needed": ctx["cfg"]["own_requires"]}, for_humans=True)]
    since = raw["minted_at"].replace("+00:00", "")
    return [
        {"op": "upsert_node", "table": "Thing", "key": x, "props": {}},
        {"op": "upsert_edge", "table": "OWNS",
         "frm": ["Thing", p], "to": ["Thing", x], "props": {"since": since}},
    ]


def action_answer_buzz(m: re.Match, raw: dict, ctx: dict) -> list[dict]:
    x = m.group("x").strip()
    log = ctx["log"]
    by_id = {p["id"]: p for p in log}
    answered = {p["body"].get("answers") for p in log if p["body"].get("answers")}
    unresolved: set = set()
    for p in log:
        if (p["kind"] == "reasoning" and p["body"].get("agent") == "squint.v0"
                and p["body"].get("conclusion") == "unresolved"):
            unresolved.update(p.get("re") or [])
    candidates = [
        q for q in log
        if q["kind"] == "question"
        and q["id"] not in answered
        and (q["body"].get("for") == "humans" or q["id"] in unresolved)
    ]
    if not candidates:
        return []
    target = candidates[-1]
    about = target["body"].get("about", {})
    role = about.get("role")
    first = x.split()[0] if x.split() else ""
    is_placement_answer = first in ("in", "on", "inside", "atop")

    if role == "placement" and is_placement_answer:
        return [
            {"_kind": "raw.response", "text": x, "answers": target["id"]},
            {"_kind": "raw.restated", "text": f"the {about['token']} is {x}",
             "answers": target["id"], "note": "composed from hey-buzz answer"},
        ]
    if role in ("owner", "subject") and not is_placement_answer:
        orig_id = (target.get("re") or [None])[0]
        orig = by_id.get(orig_id)
        token = about.get("token", "")
        surface = about.get("surface", token)
        if orig and orig["kind"].startswith("raw.") and surface:
            replacement = x + surface[len(token):] if surface.startswith(token) else x
            return [
                {"_kind": "raw.response", "text": x, "answers": target["id"]},
                {"_kind": "raw.restated",
                 "text": normalize(orig["body"]["text"]).replace(surface, replacement),
                 "answers": target["id"], "note": "composed from hey-buzz answer"},
            ]
    if role in ("kind", "capability") and not is_placement_answer and x not in ("yes", "no"):
        token = about.get("token", "")
        if token:
            return [
                {"_kind": "raw.response", "text": x, "answers": target["id"]},
                {"_kind": "raw.restated", "text": f"the {token} is a {x}",
                 "answers": target["id"], "note": "composed from hey-buzz answer"},
            ]
    return [{
        "_kind": "raw.response",
        "text": x,
        "note": f"answer shape doesn't fit open question '{target['body']['text']}' — left open",
    }]


ACTIONS = {
    "place": action_place,
    "imperative_task": action_imperative_task,
    "declare_thing": action_declare_thing,
    "set_kind": action_set_kind,
    "declare_capability": action_declare_capability,
    "declare_relationship": action_declare_relationship,
    "incomplete_relationship": action_incomplete_relationship,
    "forget": action_forget,
    "assert_rel": action_assert_rel,
    "query_place": action_query_place,
    "query_owner": action_query_owner,
    "assert_owns": action_assert_owns,
    "answer_buzz": action_answer_buzz,
}


# ------------------------------------------------------------------ run

def load_rules(log: list[dict]) -> list[dict]:
    retired = {p["body"]["name"] for p in log if p["kind"] == "rule.retire"}
    return [
        {"name": p["body"]["name"], "rx": re.compile(p["body"]["pattern"]),
         "action": p["body"]["action"]}
        for p in log
        if p["kind"] == "rule"
        and p["body"]["name"] not in retired
        and p["body"]["action"] in ACTIONS
    ]


def run() -> list[dict]:
    log = packets.read_all()
    done: set = set()
    for p in log:
        if p["kind"] == "reasoning":
            done.update(p.get("re") or [])
            done.add(p["body"].get("re"))
    pending = [p for p in log if p["kind"].startswith("raw.") and p["id"] not in done]
    rules = load_rules(log)
    ctx = build_ctx(log)
    cfg = ctx["cfg"]
    results = []

    for raw in pending:
        text = normalize(raw["body"]["text"])

        if raw["kind"] != "raw.segment":
            clauses = segment(text, cfg["segment_markers"])
            if len(clauses) > 1:
                r = packets.mint("reasoning", {
                    "agent": AGENT, "method": "segmentation",
                    "considered": None, "matched": None,
                    "bindings": {"clauses": clauses},
                    "conclusion": f"split into {len(clauses)} statements",
                }, source=AGENT, re=[raw["id"]])
                for clause in clauses:
                    packets.mint("raw.segment", {"text": clause},
                                 source=AGENT, re=[raw["id"], r["id"]])
                print(f"{raw['id']}  \"{raw['body']['text'][:50]}\"  -> segmented ({len(clauses)})")
                results.append({"id": raw["id"], "text": raw["body"]["text"],
                                "ops": 0, "conclusion": "segmented"})
                continue

        if any(w in text for w in cfg["repair_words"]):
            packets.mint("reasoning", {
                "agent": AGENT, "method": "repair-word guardrail",
                "considered": None, "matched": None, "bindings": None,
                "conclusion": "repair — not parsed, please restate",
            }, source=AGENT, re=[raw["id"]])
            print(f"{raw['id']}  \"{raw['body']['text'][:50]}\"  -> repair, not parsed")
            results.append({"id": raw["id"], "text": raw["body"]["text"],
                            "ops": 0, "conclusion": "repair"})
            continue

        match, matched_rule = None, None
        for rule in rules:
            m = rule["rx"].match(text)
            if m:
                match, matched_rule = m, rule
                break

        bodies = ACTIONS[matched_rule["action"]](match, raw, ctx) if matched_rule else []

        long_names = [b["key"] for b in bodies
                      if b.get("op") == "upsert_node"
                      and len(b["key"].split()) > cfg["max_name_words"]]
        if long_names:
            bodies = [_question(
                f"did you really mean to name a thing '{long_names[0]}'?",
                {"token": long_names[0], "table": "Thing", "role": "naming"},
                for_humans=True)]

        if not matched_rule:
            conclusion = "skip"
        elif any(b.get("_kind") == "question" for b in bodies):
            conclusion = "question"
        else:
            conclusion = matched_rule["action"]

        reasoning_body = {
            "agent": AGENT, "method": "regex over normalized text",
            "considered": [r["name"] for r in rules],
            "matched": matched_rule["name"] if matched_rule else None,
            "bindings": ({k: (v or "").strip() for k, v in match.groupdict().items()}
                         if match else None),
            "conclusion": conclusion,
        }
        if conclusion == "imperative_task":
            reasoning_body["mood"] = "imperative — recorded as open task, not fact"
        elif match and "subj" in match.groupdict():
            subj = (match.group("subj") or "").strip()
            reasoning_body["mood"] = "report" if subj else "report (elliptical)"
        reasoning = packets.mint("reasoning", reasoning_body,
                                 source=AGENT, re=[raw["id"]])

        emitted = 0
        for body in bodies:
            kind = body.pop("_kind", "op")
            body["via"] = matched_rule["name"]
            packets.mint(kind, body, source=AGENT, re=[raw["id"], reasoning["id"]])
            emitted += 1
            if body.get("op") == "upsert_node" and body["table"] in ctx["known"]:
                ctx["known"][body["table"]].add(body["key"])

        print(f"{raw['id']}  \"{raw['body']['text'][:50]}\"  -> {conclusion} ({emitted} emitted)")
        results.append({"id": raw["id"], "text": raw["body"]["text"],
                        "ops": emitted, "conclusion": conclusion})

    if not pending:
        print("nothing pending")
    return results


if __name__ == "__main__":
    run()

