"""Replay the packet log into the graph.

Runs a full rebuild every time: delete the projection, replay the log.
That the result is identical on every run is the whole thesis — the graph
is disposable; the packet log is the truth. No LLM is involved here:
op packets were already interpreted at ingestion, so replay is
deterministic and free.

The log is fully self-describing: `schema` packets declare the tables
(and rules like exclusive_from), `op` packets fill them. Rebuild is two
passes — schema first, then ops — so declarations can arrive at any
point in the log's life. Changing the ontology = minting new schema
packets and replaying.
"""

import shutil
from datetime import datetime
from pathlib import Path

import ladybug as lb

import packets

HERE = Path(__file__).parent
GRAPH = HERE / "graph.lbdb"


def ddl(body: dict) -> str:
    if body["decl"] == "node":
        cols = ", ".join(f"{k} {v}" for k, v in body["props"].items())
        return f"CREATE NODE TABLE {body['name']}({cols})"
    pairs = body.get("pairs") or [[body["frm"], body["to"]]]
    froms = ", ".join(f"FROM {a} TO {b}" for a, b in pairs)
    cols = "".join(f", {k} {v}" for k, v in body.get("props", {}).items())
    return f"CREATE REL TABLE {body['name']}({froms}{cols})"


def fresh_connection(schema: list[dict]) -> lb.Connection:
    for p in (GRAPH, HERE / "graph.lbdb.wal"):
        if p.is_dir():
            shutil.rmtree(p)
        elif p.exists():
            p.unlink()
    conn = lb.Connection(lb.Database(str(GRAPH)))
    for body in schema:
        try:
            conn.execute(ddl(body))
        except Exception as exc:
            print(f"schema decl {body.get('name')} skipped: {exc}")
    return conn


def as_param(key: str, value):
    if key == "since":
        return datetime.fromisoformat(value.replace("Z", ""))
    return value


def apply_op(conn: lb.Connection, body: dict, exclusive_from: set[str]) -> None:
    op = body["op"]
    props = {k: as_param(k, v) for k, v in body.get("props", {}).items()}

    if op == "upsert_node":
        set_clause = ", ".join(f"n.{k} = ${k}" for k in props)
        q = f"MERGE (n:{body['table']} {{name: $name}})"
        if set_clause:
            q += f" SET {set_clause}"
        conn.execute(q, {"name": body["key"], **props})

    elif op == "upsert_edge":
        table = body["table"]
        (ft, fk), (tt, tk) = body["frm"], body["to"]
        # exclusive_from maps a table to every table it displaces from:
        # a placement-family edge (INSIDE/ATOP) retires old edges in both
        for cleared in exclusive_from.get(table, []):
            try:
                conn.execute(
                    f"MATCH (a:{ft} {{name: $fk}})-[r:{cleared}]->() DELETE r",
                    {"fk": fk},
                )
            except Exception:
                pass
        set_clause = ", ".join(f"r.{k} = ${k}" for k in props)
        q = (
            f"MATCH (a:{ft} {{name: $fk}}), (b:{tt} {{name: $tk}}) "
            f"MERGE (a)-[r:{table}]->(b)"
        )
        if set_clause:
            q += f" SET {set_clause}"
        conn.execute(q, {"fk": fk, "tk": tk, **props})

    elif op == "delete_node":
        # a correction: the graph forgets, the log remembers it once believed
        conn.execute(
            f"MATCH (n:{body['table']} {{name: $k}}) DETACH DELETE n",
            {"k": body["key"]},
        )

    else:
        raise ValueError(f"unknown op: {op}")


def rebuild() -> None:
    log = packets.read_all()
    retired = {p["body"]["name"] for p in log if p["kind"] == "schema.retire"}
    schema = [p["body"] for p in log
              if p["kind"] == "schema" and p["body"]["name"] not in retired]

    # table -> list of tables a new edge from the same source displaces
    families: dict[str, list[str]] = {}
    for b in schema:
        if b.get("family"):
            families.setdefault(b["family"], []).append(b["name"])
    exclusive_from: dict[str, list[str]] = {}
    for members in families.values():
        for name in members:
            exclusive_from[name] = members
    for b in schema:
        if b.get("exclusive_from"):
            exclusive_from.setdefault(b["name"], [b["name"]])

    conn = fresh_connection(schema)
    ops = [p for p in log if p["kind"] == "op"
           and p["body"].get("table") not in retired]
    failed = 0
    for pkt in ops:
        try:
            apply_op(conn, pkt["body"], exclusive_from)
        except Exception as exc:
            failed += 1
            print(f"op {pkt['id']} failed, skipped: {exc}")
    # one type system: table membership IS kindhood. Derive, at
    # projection time, an IS_A edge from every row to its table's root
    # kind — no redundant packets, and kind-queries see one world.
    for table in ("Person", "Container", "Surface", "Item"):
        root = table.lower()
        try:
            conn.execute("MERGE (k:Kind {name: $k})", {"k": root})
            conn.execute(
                f"MATCH (n:{table}) MERGE (k:Kind {{name: $k}}) "
                f"WITH n, k MERGE (n)-[:IS_A]->(k)",
                {"k": root},
            )
        except Exception as exc:
            print(f"root-kind projection for {table} skipped: {exc}")

    note = f", {failed} failed" if failed else ""
    print(f"rebuilt {GRAPH.name}: {len(schema)} schema decls, {len(ops)} ops{note}")


if __name__ == "__main__":
    rebuild()

