def revisit() -> list[str]:
    """The persistence law: blocked intent is never consumed, it waits.
    When an open question's blocker has cleared — by any path, per the
    volume principle — close it and restate the original utterance so
    Scribe reads it again."""
    log = packets.read_all()
    ctx = build_ctx(log)
    by_id = {p["id"]: p for p in log}
    answered = {p["body"].get("answers") for p in log if p["body"].get("answers")}
    restated = []
    for q in log:
        if q["kind"] != "question" or q["id"] in answered:
            continue
        about = q["body"].get("about", {})
        role, token = about.get("role"), about.get("token", "")
        cleared = False
        if role == "capability":
            cleared = ctx["can"](token, about.get("needed", ""))
        elif role == "kind":
            cleared = about.get("needed") in ctx["ancestry"](token)
        elif role in ("subject", "owner"):
            cleared = token in ctx["known"]["Thing"]
        if not cleared:
            continue
        raw_id = next((r for r in (q.get("re") or [])
                       if by_id.get(r, {}).get("kind", "").startswith("raw.")), None)
        packets.mint("reasoning", {
            "agent": AGENT, "method": "blocked-intent revisit",
            "considered": None, "matched": None, "bindings": {"token": token},
            "conclusion": "restate",
            "because": f"the blocker on '{q['body']['text']}' has cleared",
        }, source=AGENT, re=[q["id"]])
        raw = by_id.get(raw_id)
        if raw:
            pkt = packets.mint("raw.restated", {
                "text": normalize(raw["body"]["text"]),
                "answers": q["id"],
                "note": "blocked intent retried — blocker cleared",
            }, source=AGENT, re=[q["id"], raw["id"]])
            print(f"{q['id']}  blocker cleared -> restated: \"{pkt['body']['text'][:50]}\"")
            restated.append(pkt["id"])
        else:
            packets.mint("answer", {"text": "resolved", "answers": q["id"]},
