def load_rules(log: list[dict]) -> list[dict]:
    """Precedence is data: rules sort by their priority field (default
    100, lower first), stable by log order within a band — so a
    retrofit can place a rule correctly without a wipe."""
    retired = {p["body"]["name"] for p in log if p["kind"] == "rule.retire"}
    rules = [
        {"name": p["body"]["name"], "rx": re.compile(p["body"]["pattern"]),
         "action": p["body"]["action"],
         "priority": p["body"].get("priority", 100)}
        for p in log
        if p["kind"] == "rule"
        and p["body"]["name"] not in retired
        and p["body"]["action"] in ACTIONS
    ]
    return sorted(rules, key=lambda r: r["priority"])

