//! servicerm v2 — the CRM era.
//!
//! Constitution carried over from v1: an append-only packet log is the
//! only truth; everything else is a disposable projection; packets are
//! observations; interpretation happens once at ingestion; code may
//! contain mechanisms, never vocabulary.
//!
//! This is the shell: a terminal-launched window with tabs, showing
//! the census of the sources. Ingestion comes next.

use eframe::egui;
use std::path::PathBuf;

#[derive(PartialEq, Clone, Copy)]
enum Tab {
    People,
    Chats,
    Packets,
}

struct Census {
    contacts: i64,
    phones: i64,
    emails: i64,
    handles: i64,
    chats: i64,
    messages: i64,
}

fn sources_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("sources")
}

fn count(conn: &rusqlite::Connection, sql: &str) -> i64 {
    conn.query_row(sql, [], |r| r.get(0)).unwrap_or(-1)
}

fn take_census() -> rusqlite::Result<Census> {
    let dir = sources_dir();
    let contacts = rusqlite::Connection::open_with_flags(
        dir.join("AddressBook-v22.abcddb"),
        rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY,
    )?;
    let chat = rusqlite::Connection::open_with_flags(
        dir.join("chat.db"),
        rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY,
    )?;
    Ok(Census {
        contacts: count(
            &contacts,
            "SELECT count(*) FROM ZABCDRECORD \
             WHERE ZFIRSTNAME IS NOT NULL OR ZLASTNAME IS NOT NULL",
        ),
        phones: count(&contacts, "SELECT count(*) FROM ZABCDPHONENUMBER"),
        emails: count(&contacts, "SELECT count(*) FROM ZABCDEMAILADDRESS"),
        handles: count(&chat, "SELECT count(*) FROM handle"),
        chats: count(&chat, "SELECT count(*) FROM chat"),
        messages: count(&chat, "SELECT count(*) FROM message"),
    })
}

struct ServicermApp {
    tab: Tab,
    census: Option<Census>,
    census_error: Option<String>,
}

impl ServicermApp {
    fn new() -> Self {
        let (census, census_error) = match take_census() {
            Ok(c) => (Some(c), None),
            Err(e) => (None, Some(e.to_string())),
        };
        Self { tab: Tab::People, census, census_error }
    }
}

impl eframe::App for ServicermApp {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        egui::TopBottomPanel::top("tabs").show(ctx, |ui| {
            ui.horizontal(|ui| {
                ui.heading("servicerm");
                ui.separator();
                ui.selectable_value(&mut self.tab, Tab::People, "People");
                ui.selectable_value(&mut self.tab, Tab::Chats, "Chats");
                ui.selectable_value(&mut self.tab, Tab::Packets, "Packets");
            });
        });
        egui::CentralPanel::default().show(ctx, |ui| {
            if let Some(err) = &self.census_error {
                ui.colored_label(egui::Color32::RED, format!("sources error: {err}"));
                return;
            }
            let c = self.census.as_ref().unwrap();
            match self.tab {
                Tab::People => {
                    ui.heading("The CF Landscape Design universe");
                    ui.add_space(8.0);
                    ui.label(format!("{} named contacts", c.contacts));
                    ui.label(format!("{} phone numbers", c.phones));
                    ui.label(format!("{} email addresses", c.emails));
                    ui.label(format!("{} handles seen in messages", c.handles));
                    ui.add_space(8.0);
                    ui.weak("ingestion next: person + handle packets, then the list");
                }
                Tab::Chats => {
                    ui.heading("Chats");
                    ui.add_space(8.0);
                    ui.label(format!("{} chats", c.chats));
                    ui.label(format!("{} messages", c.messages));
                }
                Tab::Packets => {
                    ui.heading("Packet log");
                    ui.add_space(8.0);
                    ui.weak("the tape starts here — genesis pending");
                }
            }
        });
    }
}

fn main() -> eframe::Result {
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default().with_inner_size([980.0, 640.0]),
        ..Default::default()
    };
    eframe::run_native(
        "servicerm",
        options,
        Box::new(|_cc| Ok(Box::new(ServicermApp::new()))),
    )
}

