//! servicerm v2 — the CRM era.
//!
//! Constitution from v1: the packet log is the only truth; projections
//! are disposable; packets are observations; code may contain
//! mechanisms, never vocabulary.
//!
//! Deliberately minimal: a left toolbar with one entry — Clients —
//! showing the CFD-labeled roster. The spine first; everything else
//! hangs off it later.

mod contacts;

use eframe::egui;

struct App {
    clients: Vec<contacts::Client>,
    error: Option<String>,
    selected: Option<usize>,
}

impl App {
    fn new() -> Self {
        match contacts::cfd_clients() {
            Ok(clients) => Self { clients, error: None, selected: None },
            Err(e) => Self { clients: vec![], error: Some(e.to_string()), selected: None },
        }
    }
}

impl eframe::App for App {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        egui::SidePanel::left("toolbar")
            .resizable(false)
            .default_width(120.0)
            .show(ctx, |ui| {
                ui.add_space(8.0);
                ui.label(egui::RichText::new("servicerm").strong());
                ui.add_space(12.0);
                ui.selectable_label(true, "Clients");
            });

        egui::CentralPanel::default().show(ctx, |ui| {
            if let Some(err) = &self.error {
                ui.colored_label(egui::Color32::RED, format!("sources error: {err}"));
                return;
            }
            ui.heading(format!("Clients ({})", self.clients.len()));
            ui.add_space(6.0);
            egui::ScrollArea::vertical().show(ui, |ui| {
                for (i, c) in self.clients.iter().enumerate() {
                    let selected = self.selected == Some(i);
                    let label = ui.selectable_label(selected, &c.name);
                    if label.clicked() {
                        self.selected = if selected { None } else { Some(i) };
                    }
                    if self.selected == Some(i) {
                        ui.indent("detail", |ui| {
                            if !c.org.is_empty() {
                                ui.weak(&c.org);
                            }
                            for p in &c.phones {
                                ui.monospace(p);
