//! Testable step 2a: extract every (name, phone, email) triple from the
//! transposed v3.OpGraph pipeline CSV. Extraction only — matching against
//! the Contacts roster is a later, separate step.
//!
//!     cargo run --bin csv_handles

use std::collections::BTreeSet;
use std::path::PathBuf;

fn main() {
    let path = PathBuf::from(
        "/Users/caldayham/Desktop/graphlab.systems/v3.OpGraph/CFC - JOB TRACKER - Pipeline (3).csv",
    );
    let mut reader = csv::ReaderBuilder::new()
        .has_headers(false)
        .flexible(true)
        .from_path(&path)
        .expect("open pipeline csv");

    let rows: Vec<csv::StringRecord> = reader.records().filter_map(|r| r.ok()).collect();
    let find_row = |label: &str| {
        rows.iter()
            .find(|r| r.get(0).map(|f| f.trim().eq_ignore_ascii_case(label)) == Some(true))
    };
    let names = find_row("Name").expect("Name row");
    let phones = find_row("phone number").expect("phone row");
    let emails = find_row("email").expect("email row");

    let width = names.len().max(phones.len()).max(emails.len());
    let get = |r: &csv::StringRecord, i: usize| r.get(i).unwrap_or("").trim().to_string();

    let mut pairs: BTreeSet<(String, String, String)> = BTreeSet::new();
    for i in 1..width {
        let (n, p, e) = (get(names, i), get(phones, i), get(emails, i));
        if n.is_empty() && p.is_empty() && e.is_empty() {
            continue;
        }
        pairs.insert((n, p, e));
    }

    println!("{:<28} {:<18} {}", "NAME", "PHONE", "EMAIL");
    for (n, p, e) in &pairs {
        println!("{:<28} {:<18} {}", n, p, e);
    }
    println!("--- {} unique (name, phone, email) triples across job columns", pairs.len());
}

