//! The client roster: contacts Cal has deliberately labeled CFD —
//! in the name, nickname, organization, or notes. Nothing else
//! enters the CRM. Read-only against the copied Contacts database.

use rusqlite::{Connection, OpenFlags, Result};
use std::path::PathBuf;

pub struct Client {
    pub record_id: i64,
    pub name: String,
    pub org: String,
    pub phones: Vec<String>,
    pub emails: Vec<String>,
}

impl Client {
    /// Display name with Cal's filing labels stripped: everything from
    /// the first " - " on is labeling ("Alain - CFD", "Paul - YMCA - CFD",
    /// "Barbara Kirst - Nextdoor"), not name.
    pub fn display_name(&self) -> String {
        self.name
            .split(" - ")
            .next()
            .unwrap_or(&self.name)
            .trim()
            .to_string()
    }
}

pub fn sources_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("sources")
}

fn string_list(db: &Connection, sql: &str, owner: i64) -> Result<Vec<String>> {
    let mut stmt = db.prepare(sql)?;
    let rows = stmt.query_map([owner], |r| r.get::<_, Option<String>>(0))?;
    Ok(rows.filter_map(|r| r.ok().flatten()).collect())
}

pub fn cfd_clients() -> Result<Vec<Client>> {
    let db = Connection::open_with_flags(
        sources_dir().join("AddressBook-v22.abcddb"),
        OpenFlags::SQLITE_OPEN_READ_ONLY,
    )?;
    let mut stmt = db.prepare(
        "SELECT DISTINCT r.Z_PK,
                COALESCE(r.ZFIRSTNAME,''), COALESCE(r.ZLASTNAME,''),
                COALESCE(r.ZORGANIZATION,'')
         FROM ZABCDRECORD r
         LEFT JOIN ZABCDNOTE n ON n.ZCONTACT = r.Z_PK
         WHERE n.ZTEXT LIKE '%CFD%'
            OR r.ZFIRSTNAME LIKE '%CFD%' OR r.ZLASTNAME LIKE '%CFD%'
            OR r.ZORGANIZATION LIKE '%CFD%' OR r.ZNICKNAME LIKE '%CFD%'
         ORDER BY 2, 3",
    )?;
    let ids: Vec<(i64, String, String, String)> = stmt
        .query_map([], |r| {
            Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?))
        })?
        .filter_map(|r| r.ok())
        .collect();

    let mut out = Vec::new();
    for (id, first, last, org) in ids {
        let phones = string_list(
            &db,
            "SELECT ZFULLNUMBER FROM ZABCDPHONENUMBER WHERE ZOWNER = ?1",
            id,
        )?;
        let emails = string_list(
            &db,
            "SELECT ZADDRESS FROM ZABCDEMAILADDRESS WHERE ZOWNER = ?1",
            id,
        )?;
        let name = format!("{first} {last}").trim().to_string();
        out.push(Client { record_id: id, name, org, phones, emails });
    }
    Ok(out)
}

