//! ServiceRM v2 — the CRM era.
//!
//! Constitution from v1: the packet log is the only truth; projections
//! are disposable; packets are observations; code may contain
//! mechanisms, never vocabulary.
//!
//! One toolbar entry — Contacts — showing the unified roster:
//! CFD-labeled contacts, pipeline people matched into the address book
//! by handle, and pipeline-only people. Merge rules are Cal's, encoded
//! in merge.rs.

use eframe::egui;
use servicerm::merge::{self, Person, Source};

struct App {
    people: Vec<Person>,
    error: Option<String>,
    selected: Option<usize>,
}

impl App {
    fn new() -> Self {
        match merge::unified_roster() {
            Ok(people) => Self { people, error: None, selected: None },
            Err(e) => Self { people: vec![], error: Some(e.to_string()), selected: None },
        }
    }
}

impl eframe::App for App {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        egui::SidePanel::left("toolbar")
            .resizable(false)
            .default_width(120.0)
            .show(ctx, |ui| {
                ui.add_space(12.0);
                ui.selectable_label(true, "Contacts");
            });

        egui::CentralPanel::default().show(ctx, |ui| {
            if let Some(err) = &self.error {
                ui.colored_label(egui::Color32::RED, format!("sources error: {err}"));
                return;
            }
            ui.heading(format!("Contacts ({})", self.people.len()));
            ui.add_space(6.0);
            egui::ScrollArea::vertical().show(ui, |ui| {
                for (i, p) in self.people.iter().enumerate() {
                    let selected = self.selected == Some(i);
                    if ui.selectable_label(selected, &p.name).clicked() {
                        self.selected = if selected { None } else { Some(i) };
                    }
                    if self.selected == Some(i) {
                        ui.indent("detail", |ui| {
                            if let Some(filed) = &p.filed_as {
                                ui.weak(format!("filed as: {filed}"));
                            }
                            if p.source == Source::PipelineOnly {
                                ui.weak("from the job pipeline — not in Contacts yet");
                            }
                            for ph in &p.phones {
                                ui.monospace(ph);
                            }
                            for e in &p.emails {
                                ui.monospace(e);
                            }
                        });
                        ui.add_space(4.0);
                    }
                }
            });
        });
    }
}

fn main() -> eframe::Result {
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default().with_inner_size([760.0, 640.0]),
        ..Default::default()
    };
    eframe::run_native(
        "ServiceRM",
        options,
        Box::new(|_cc| Ok(Box::new(App::new()))),
    )
}

