//!
//!     cargo run --bin merge

use servicerm::merge::{unified_roster, Source};

fn main() {
    let people = match unified_roster() {
        Ok(p) => p,
        Err(e) => {
            eprintln!("merge error: {e}");
            return;
        }
    };
    let (mut cfd, mut matched, mut pipeline) = (0, 0, 0);
    for p in &people {
        let marker = match p.source {
            Source::CfdLabeled => {
                cfd += 1;
                "[cfd]     "
            }
            Source::ContactsMatched => {
                matched += 1;
                "[matched] "
            }
            Source::PipelineOnly => {
                pipeline += 1;
                "[pipeline]"
            }
        };
        let handles: Vec<String> = p.phones.iter().chain(p.emails.iter()).cloned().collect();
        println!("{marker} {:<30} {}", p.name, handles.join("  "));
    }
    println!(
        "--- {} total: {} cfd-labeled, {} matched into contacts, {} pipeline-only",
        people.len(),
        cfd,
        matched,
        pipeline
    );
}

