    )?;
    for row in stmt.query_map([], |r| Ok((r.get::<_, i64>(0)?, r.get::<_, String>(1)?)))? {
        if let Ok((owner, num)) = row {
            phones.entry(owner).or_default().push(num);
        }
    }
    let mut emails: std::collections::BTreeMap<i64, Vec<String>> = Default::default();
    let mut stmt = db.prepare(
        "SELECT ZOWNER, ZADDRESS FROM ZABCDEMAILADDRESS WHERE ZADDRESS IS NOT NULL",
    )?;
    for row in stmt.query_map([], |r| Ok((r.get::<_, i64>(0)?, r.get::<_, String>(1)?)))? {
        if let Ok((owner, addr)) = row {
            emails.entry(owner).or_default().push(addr);
        }
