        "SELECT DISTINCT r.Z_PK FROM ZABCDRECORD r
         LEFT JOIN ZABCDNOTE n ON n.ZCONTACT = r.Z_PK
         WHERE n.ZTEXT LIKE '%CFD%'
            OR r.ZFIRSTNAME LIKE '%CFD%' OR r.ZLASTNAME LIKE '%CFD%'
            OR r.ZORGANIZATION LIKE '%CFD%' OR r.ZNICKNAME LIKE '%CFD%'",
    )?;
    let cfd_ids = stmt
        .query_map([], |r| r.get::<_, i64>(0))?
