//! The v2 packet log — same constitution, same envelope as v1:
//! {id, minted_at, source, kind, re: [...], body}. Append-only, never
//! edited, never inserted; `re` is the attention column.

use serde::{Deserialize, Serialize};
use std::fs::OpenOptions;
use std::io::{BufRead, BufReader, Write};
use std::path::PathBuf;

#[derive(Serialize, Deserialize, Clone)]
pub struct Packet {
    pub id: String,
    pub minted_at: String,
    pub source: String,
    pub kind: String,
    pub re: Vec<String>,
    pub body: serde_json::Value,
}

pub fn log_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("packets.jsonl")
}

fn now_utc() -> String {
    // seconds precision, UTC, matching v1's format
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap();
    let secs = now.as_secs();
    let days = secs / 86400;
    let (mut y, mut rem_days) = (1970i64, days as i64);
    loop {
        let leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
        let len = if leap { 366 } else { 365 };
        if rem_days < len {
            break;
        }
        rem_days -= len;
        y += 1;
    }
    let leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    let month_lens = [31, if leap { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    let mut m = 0;
    while rem_days >= month_lens[m] {
        rem_days -= month_lens[m];
        m += 1;
    }
    let day_secs = secs % 86400;
    format!(
        "{y:04}-{:02}-{:02}T{:02}:{:02}:{:02}+00:00",
        m + 1,
        rem_days + 1,
        day_secs / 3600,
        (day_secs % 3600) / 60,
        day_secs % 60
    )
}

fn pkt_id() -> String {
    let mut bytes = [0u8; 6];
    // std-only entropy: address + time jitter hashed
    let t = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    let mut seed = t as u64 ^ (&bytes as *const _ as u64);
    for b in bytes.iter_mut() {
        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        *b = (seed >> 33) as u8;
    }
    format!("pkt_{}", bytes.iter().map(|b| format!("{b:02x}")).collect::<String>())
}

pub fn mint(kind: &str, body: serde_json::Value, source: &str, re: Vec<String>) -> Packet {
    let pkt = Packet {
        id: pkt_id(),
        minted_at: now_utc(),
        source: source.to_string(),
        kind: kind.to_string(),
        re,
        body,
    };
    let mut f = OpenOptions::new()
        .create(true)
        .append(true)
        .open(log_path())
        .expect("open packet log");
    writeln!(f, "{}", serde_json::to_string(&pkt).unwrap()).expect("append packet");
    pkt
}

pub fn read_all() -> Vec<Packet> {
    let Ok(f) = std::fs::File::open(log_path()) else {
        return vec![];
    };
    BufReader::new(f)
        .lines()
        .filter_map(|l| l.ok())
        .filter(|l| !l.trim().is_empty())
        .filter_map(|l| serde_json::from_str(&l).ok())
        .collect()
}

