        Some((f, l)) => (f.trim().to_string(), l.trim().to_string()),
        None => (full.trim().to_string(), String::new()),
    }
}

pub fn normalize_phone(s: &str) -> String {
    let digits: String = s.chars().filter(|c| c.is_ascii_digit()).collect();
    if digits.len() == 11 && digits.starts_with('1') {
        digits[1..].to_string()
    } else {
        digits
    }
}

pub fn clean_name(s: &str) -> String {
    let s = s.split(',').next().unwrap_or(s);
    let s = s.split(" - ").next().unwrap_or(s);
    s.trim().to_string()
}

fn pipeline_csv_path() -> PathBuf {
    PathBuf::from(
        "/Users/caldayham/Desktop/graphlab.systems/v3.OpGraph/CFC - JOB TRACKER - Pipeline (3).csv",
    )
}

/// (raw name, phone, email) per job column, empty columns skipped.
pub fn pipeline_triples() -> Vec<(String, String, String)> {
    let mut reader = match csv::ReaderBuilder::new()
        .has_headers(false)
        .flexible(true)
        .from_path(pipeline_csv_path())
    {
        Ok(r) => r,
        Err(_) => return vec![],
    };
    let rows: Vec<csv::StringRecord> = reader.records().filter_map(|r| r.ok()).collect();
    let find = |label: &str| {
        rows.iter()
            .find(|r| r.get(0).map(|f| f.trim().eq_ignore_ascii_case(label)) == Some(true))
    };
    let (names, phones, emails) = match (find("Name"), find("phone number"), find("email")) {
        (Some(n), Some(p), Some(e)) => (n, p, e),
        _ => return vec![],
    };
    let width = names.len().max(phones.len()).max(emails.len());
    let get = |r: &csv::StringRecord, i: usize| r.get(i).unwrap_or("").trim().to_string();
    (1..width)
        .map(|i| (get(names, i), get(phones, i), get(emails, i)))
        .filter(|(n, p, e)| !(n.is_empty() && p.is_empty() && e.is_empty()))
        .collect()
}

struct Group {
    name: String,
    phones: BTreeSet<String>, // digit-normalized
    emails: BTreeSet<String>, // lowercased
}

fn better_name(a: &str, b: &str) -> String {
    if b.len() > a.len() { b.to_string() } else { a.to_string() }
}

/// Dedupe pipeline triples by Cal's rules.
fn pipeline_groups() -> Vec<Group> {
    let mut groups: Vec<Group> = Vec::new();
    let mut by_phone: BTreeMap<String, usize> = BTreeMap::new();
    let mut by_email: BTreeMap<String, usize> = BTreeMap::new();
    let mut by_name: BTreeMap<String, usize> = BTreeMap::new();

    for (raw_name, phone, email) in pipeline_triples() {
        let name = clean_name(&raw_name);
        let digits = normalize_phone(&phone);
        let email = email.to_lowercase();

        let key_hit = (!digits.is_empty())
            .then(|| by_phone.get(&digits))
            .flatten()
            .or_else(|| (!email.is_empty()).then(|| by_email.get(&email)).flatten())
            .or_else(|| by_name.get(&name.to_lowercase()))
            .copied();

        let idx = match key_hit {
            Some(i) => i,
            None => {
                groups.push(Group {
                    name: name.clone(),
                    phones: BTreeSet::new(),
                    emails: BTreeSet::new(),
                });
                groups.len() - 1
            }
        };
        let g = &mut groups[idx];
        g.name = better_name(&g.name, &name);
        if !digits.is_empty() {
            g.phones.insert(digits.clone());
            by_phone.insert(digits, idx);
        }
        if !email.is_empty() {
            g.emails.insert(email.clone());
            by_email.insert(email, idx);
        }
        by_name.insert(g.name.to_lowercase(), idx);
    }
    groups
}

fn person_from_client(c: &Client, source: Source) -> Person {
    // Cal files labels inside the first-name field ("Suzi Leong - CFD",
    // last empty): clean the label, then split if last is missing
    let clean_first = clean_name(&c.first);
    let clean_last = clean_name(&c.last);
    let (first, last) = if clean_last.is_empty() {
        split_name(&clean_first)
    } else {
        (clean_first, clean_last)
    };
    let display = format!("{first} {last}").trim().to_string();
    Person {
        filed_as: (c.name != display).then(|| c.name.clone()),
        first,
        last,
        name: display,
        source,
        phones: c.phones.clone(),
        emails: c.emails.clone(),
    }
}

pub fn unified_roster() -> rusqlite::Result<Vec<Person>> {
    let (book, cfd_ids) = contacts::book()?;

    // handle indexes over the whole address book
    let mut phone_to_record: BTreeMap<String, usize> = BTreeMap::new();
    let mut email_to_record: BTreeMap<String, usize> = BTreeMap::new();
    for (i, c) in book.iter().enumerate() {
        for p in &c.phones {
            phone_to_record.insert(normalize_phone(p), i);
        }
        for e in &c.emails {
            email_to_record.insert(e.to_lowercase(), i);
        }
    }

    let mut include: BTreeMap<usize, Source> = BTreeMap::new();
    for (i, c) in book.iter().enumerate() {
        if cfd_ids.contains(&c.record_id) {
            include.insert(i, Source::CfdLabeled);
        }
    }

    let mut pipeline_only: Vec<Person> = Vec::new();
    for g in pipeline_groups() {
        let hit = g
            .phones
            .iter()
            .find_map(|d| phone_to_record.get(d))
            .or_else(|| g.emails.iter().find_map(|e| email_to_record.get(e)))
            .copied();
        match hit {
            Some(i) => {
                include.entry(i).or_insert(Source::ContactsMatched);
            }
            None => {
                if g.name.is_empty() {
                    continue;
                }
                pipeline_only.push(Person {
                    name: g.name.clone(),
                    filed_as: None,
                    source: Source::PipelineOnly,
                    phones: g.phones.iter().cloned().collect(),
                    emails: g.emails.iter().cloned().collect(),
                });
            }
        }
    }

    let mut out: Vec<Person> = include
        .iter()
        .map(|(&i, &src)| person_from_client(&book[i], src))
        .collect();
    out.extend(pipeline_only);
    out.sort_by(|a, b| a.name.to_lowercase().cmp(&b.name.to_lowercase()));
    Ok(out)
}

