//! The census ceremony: run the merge once and mint every person as an
//! observation packet into v2/packets.jsonl. Refuses to run twice —
//! after the census, changes enter as corrections and deltas, never
//! re-ingestion.
//!
//!     cargo run --bin ingest

use serde_json::json;
use servicerm::merge::{unified_roster, Source};
use servicerm::packets;

fn main() {
    let existing = packets::read_all();
    if existing.iter().any(|p| p.kind == "observation.person") {
        eprintln!(
            "log already holds a person census ({} packets) — corrections, not re-ingestion",
            existing.len()
        );
        return;
    }
    let people = match unified_roster() {
        Ok(p) => p,
        Err(e) => {
            eprintln!("ingest error: {e}");
            return;
        }
    };
    let mut minted = 0;
    for p in &people {
        let origin = match p.source {
            Source::CfdLabeled => "contacts:cfd-labeled",
            Source::ContactsMatched => "contacts:matched-by-handle",
            Source::PipelineOnly => "pipeline-csv",
        };
        packets::mint(
            "observation.person",
            json!({
                "first": p.first,
                "last": p.last,
                "filed_as": p.filed_as,
                "phones": p.phones,
                "emails": p.emails,
                "origin": origin,
            }),
            "ingest.v2",
            vec![],
        );
        minted += 1;
    }
    println!("census minted: {minted} observation.person packets -> {}",
             packets::log_path().display());
}

