//! People, read from the log — the projection the UI renders. The log
//! is the only source the app reads; ingest ceremonies are the only
//! writers.

use crate::packets;

#[derive(Clone)]
pub struct Person {
    pub packet_id: String,
    pub first: String,
    pub last: String,
    pub phones: Vec<String>,
    pub emails: Vec<String>,
}

impl Person {
    pub fn name(&self) -> String {
        format!("{} {}", self.first, self.last).trim().to_string()
    }
}

pub fn from_log() -> Vec<Person> {
    let mut people: Vec<Person> = packets::read_all()
        .into_iter()
        .filter(|p| p.kind == "observation.person")
        .map(|p| Person {
            packet_id: p.id,
            first: p.body["first"].as_str().unwrap_or("").to_string(),
            last: p.body["last"].as_str().unwrap_or("").to_string(),
            phones: str_list(&p.body["phones"]),
            emails: str_list(&p.body["emails"]),
        })
        .collect();
    people.sort_by_key(|p| p.name().to_lowercase());
    people
}

fn str_list(v: &serde_json::Value) -> Vec<String> {
    v.as_array()
        .map(|a| a.iter().filter_map(|x| x.as_str().map(String::from)).collect())
        .unwrap_or_default()
}

