//! Live chat preview for a person: join chat.db handles to a person's
//! phone digits / emails, list their chats with counts and last lines.
//! Read-only against the copied Messages database.

use crate::merge::normalize_phone;
use rusqlite::{Connection, OpenFlags};
use std::path::PathBuf;

pub struct ChatPreview {
    pub title: String,
    pub messages: i64,
    pub last_unix: i64,
    pub last_text: String,
}

fn chat_db() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("sources/chat.db")
}

/// Apple stores message.date as nanoseconds since 2001-01-01.
fn apple_to_unix(date: i64) -> i64 {
    date / 1_000_000_000 + 978_307_200
}

pub fn fmt_day(unix: i64) -> String {
    let days = unix / 86400;
    let (mut y, mut rem) = (1970i64, days);
    loop {
        let leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
        let len = if leap { 366 } else { 365 };
        if rem < len {
            break;
        }
        rem -= len;
        y += 1;
    }
