//! Genesis for the v2 log: declare the ontology on the tape, then mint
//! the person census. Runs once, on an empty log.
//!
//!     cargo run --bin genesis

use serde_json::json;
use servicerm::merge::unified_roster;
use servicerm::packets;

fn main() {
    if !packets::read_all().is_empty() {
        eprintln!("log is not empty — genesis already happened");
        return;
    }

    let nodes = [
        ("person", json!({"first": "string", "last": "string",
                           "phones": "string[]", "emails": "string[]"})),
        ("business", json!({"name": "string"})),
        ("property", json!({"address": "string"})),
        ("engagement", json!({"title": "string", "status": "string"})),
        ("chat", json!({"name": "string"})),
        ("message", json!({"ts": "timestamp", "text": "string"})),
    ];
    for (name, props) in nodes {
        packets::mint("schema", json!({"decl": "node", "name": name, "props": props}),
                      "genesis.v2", vec![]);
    }
    let rels = [
        ("client_of", "person", "business"),
        ("works_for", "person", "business"),
        ("owns", "person", "property"),
        ("located_at", "engagement", "property"),
        ("party_to", "person", "engagement"),
        ("member_of", "person", "chat"),
        ("in_chat", "message", "chat"),
        ("sent_by", "message", "person"),
    ];
    for (name, from, to) in rels {
        packets::mint("schema", json!({"decl": "rel", "name": name,
                                        "from": from, "to": to}),
                      "genesis.v2", vec![]);
    }
    packets::mint("config", json!({"person_identity": ["phone-digits", "email"]}),
                  "genesis.v2", vec![]);

    let people = unified_roster().expect("merge");
    let mut minted = 0;
    for p in &people {
        packets::mint(
            "observation.person",
            json!({"first": p.first, "last": p.last,
                   "phones": p.phones, "emails": p.emails}),
            "ingest.v2",
            vec![],
        );
        minted += 1;
    }
    println!(
        "genesis: {} schema + 1 config + {} person packets -> {}",
        nodes.len() + rels.len(),
        minted,
        packets::log_path().display()
    );
}

