/// The most recent `limit` messages of a chat, oldest first.
pub fn messages_for(chat_rowid: i64, limit: i64) -> Vec<Msg> {
    let Ok(db) = Connection::open_with_flags(chat_db(), OpenFlags::SQLITE_OPEN_READ_ONLY)
    else {
        return vec![];
    };
    let Ok(mut stmt) = db.prepare(
        "SELECT m.is_from_me, COALESCE(h.id, ''), m.date, m.text, m.attributedBody
