//! Live chat preview for a person: join chat.db handles to a person's
//! phone digits / emails, list their chats with counts and last lines.
//! Read-only against the copied Messages database.

use crate::merge::normalize_phone;
use rusqlite::{Connection, OpenFlags};
use std::path::PathBuf;

pub struct ChatPreview {
    pub rowid: i64,
    pub title: String,
    pub messages: i64,
    pub last_unix: i64,
    pub last_text: String,
}

pub struct Msg {
    pub from_me: bool,
    pub sender: String,
    pub unix: i64,
    pub text: String,
}

/// Modern Messages rows often have text = NULL with the string buried
/// in the typedstream-archived attributedBody blob. Standard trick:
/// find "NSString", then '+', then a length byte (0x81 = two-byte
/// little-endian length follows), then the UTF-8 text.
fn extract_attributed(blob: &[u8]) -> Option<String> {
    let marker = b"NSString";
    let at = blob.windows(marker.len()).position(|w| w == marker)?;
    let after = &blob[at + marker.len()..];
    let plus = after.iter().take(12).position(|&b| b == b'+')?;
    let rest = &after[plus + 1..];
    let (len, start) = match *rest.first()? {
        0x81 => {
            let l = u16::from_le_bytes([*rest.get(1)?, *rest.get(2)?]) as usize;
            (l, 3)
        }
        b => (b as usize, 1),
    };
    let bytes = rest.get(start..start + len)?;
    let s = String::from_utf8_lossy(bytes).to_string();
    (!s.trim().is_empty()).then_some(s)
}

fn message_text(text: Option<String>, blob: Option<Vec<u8>>) -> String {
    if let Some(t) = text {
        if !t.trim().is_empty() {
            return t;
        }
    }
    if let Some(b) = blob {
        if let Some(t) = extract_attributed(&b) {
            return t;
        }
    }
    "[attachment]".to_string()
}

fn chat_db() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("sources/chat.db")
}

/// Apple stores message.date as nanoseconds since 2001-01-01.
fn apple_to_unix(date: i64) -> i64 {
    date / 1_000_000_000 + 978_307_200
}

pub fn fmt_day(unix: i64) -> String {
    let days = unix / 86400;
    let (mut y, mut rem) = (1970i64, days);
    loop {
        let leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
        let len = if leap { 366 } else { 365 };
        if rem < len {
            break;
        }
        rem -= len;
        y += 1;
    }
    let leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    let lens = [31, if leap { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    let mut m = 0;
    while rem >= lens[m] {
        rem -= lens[m];
        m += 1;
    }
    format!("{y}-{:02}-{:02}", m + 1, rem + 1)
}

pub fn previews_for(phones: &[String], emails: &[String]) -> Vec<ChatPreview> {
    let Ok(db) = Connection::open_with_flags(chat_db(), OpenFlags::SQLITE_OPEN_READ_ONLY)
    else {
        return vec![];
    };

    // handle.id may be "", "", or an email
    let mut variants: Vec<String> = Vec::new();
    for p in phones {
        let d = normalize_phone(p);
        if !d.is_empty() {
            variants.push(format!("+1{d}"));
            variants.push(d);
        }
    }
    for e in emails {
        variants.push(e.to_lowercase());
    }
    if variants.is_empty() {
        return vec![];
    }
    let placeholders = vec!["?"; variants.len()].join(",");
    let sql = format!(
        "SELECT c.ROWID,
                COALESCE(NULLIF(c.display_name,''), c.chat_identifier),
                count(m.ROWID),
                max(m.date)
         FROM handle h
         JOIN chat_handle_join chj ON chj.handle_id = h.ROWID
         JOIN chat c ON c.ROWID = chj.chat_id
         JOIN chat_message_join cmj ON cmj.chat_id = c.ROWID
         JOIN message m ON m.ROWID = cmj.message_id
         WHERE lower(h.id) IN ({placeholders})
         GROUP BY c.ROWID
         ORDER BY max(m.date) DESC
         LIMIT 12"
    );
    let Ok(mut stmt) = db.prepare(&sql) else {
        return vec![];
    };
    let params: Vec<&dyn rusqlite::ToSql> =
        variants.iter().map(|v| v as &dyn rusqlite::ToSql).collect();
    let rows = stmt.query_map(params.as_slice(), |r| {
        Ok(ChatPreview {
            rowid: r.get(0)?,
            title: r.get::<_, Option<String>>(1)?.unwrap_or_default(),
            messages: r.get(2)?,
            last_unix: apple_to_unix(r.get::<_, Option<i64>>(3)?.unwrap_or(0)),
            last_text: String::new(),
        })
    });
    let mut previews: Vec<ChatPreview> = match rows {
        Ok(it) => it.filter_map(|r| r.ok()).collect(),
        Err(_) => vec![],
    };
    for p in &mut previews {
        if let Some(last) = messages_for(p.rowid, 1).pop() {
            p.last_text = last.text;
        }
    }
    previews
}

/// The most recent `limit` messages of a chat, oldest first.
pub fn messages_for(chat_rowid: i64, limit: i64) -> Vec<Msg> {
    let Ok(db) = Connection::open_with_flags(chat_db(), OpenFlags::SQLITE_OPEN_READ_ONLY)
    else {
        return vec![];
    };
    let Ok(mut stmt) = db.prepare(
        "SELECT m.is_from_me, COALESCE(h.id, ''), m.date, m.text, m.attributedBody
         FROM message m
         JOIN chat_message_join cmj ON cmj.message_id = m.ROWID
         LEFT JOIN handle h ON h.ROWID = m.handle_id
         WHERE cmj.chat_id = ?1
         ORDER BY m.date DESC
         LIMIT ?2",
    ) else {
        return vec![];
    };
    let rows = stmt.query_map(rusqlite::params![chat_rowid, limit], |r| {
        Ok(Msg {
            from_me: r.get::<_, i64>(0)? != 0,
            sender: r.get(1)?,
            unix: apple_to_unix(r.get::<_, Option<i64>>(2)?.unwrap_or(0)),
            text: message_text(r.get(3)?, r.get(4)?),
        })
    });
    let mut msgs: Vec<Msg> = match rows {
        Ok(it) => it.filter_map(|r| r.ok()).collect(),
        Err(_) => vec![],
    };
    msgs.reverse();
    msgs
}

