//! Chat ingest ceremony: every chat.db room involving a roster handle
//! becomes an observation.chat packet — identity is the chat's guid,
//! membership is its handle list. Messages stay live-read for now.
//!
//!     cargo run --bin ingest_chats

use rusqlite::{Connection, OpenFlags};
use serde_json::json;
use servicerm::merge::normalize_phone;
use servicerm::{packets, people};
use std::collections::BTreeSet;
use std::path::PathBuf;

fn main() {
    if packets::read_all().iter().any(|p| p.kind == "observation.chat") {
        eprintln!("log already holds a chat census — corrections, not re-ingestion");
        return;
    }
    let roster = people::from_log();
    let mut variants: BTreeSet<String> = BTreeSet::new();
    for p in &roster {
        for ph in &p.phones {
            let d = normalize_phone(ph);
            if !d.is_empty() {
                variants.insert(format!("+1{d}"));
                variants.insert(d);
            }
        }
        for e in &p.emails {
            variants.insert(e.to_lowercase());
        }
    }

    let db = Connection::open_with_flags(
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("sources/chat.db"),
        OpenFlags::SQLITE_OPEN_READ_ONLY,
    )
    .expect("open chat.db");

    let placeholders = vec!["?"; variants.len()].join(",");
    let sql = format!(
        "SELECT DISTINCT c.guid, COALESCE(c.display_name,''), c.style
         FROM handle h
         JOIN chat_handle_join chj ON chj.handle_id = h.ROWID
         JOIN chat c ON c.ROWID = chj.chat_id
         WHERE lower(h.id) IN ({placeholders})"
    );
    let vlist: Vec<String> = variants.into_iter().collect();
    let params: Vec<&dyn rusqlite::ToSql> =
        vlist.iter().map(|v| v as &dyn rusqlite::ToSql).collect();
    let mut stmt = db.prepare(&sql).expect("prepare");
    let chats: Vec<(String, String, i64)> = stmt
        .query_map(params.as_slice(), |r| {
            Ok((r.get(0)?, r.get(1)?, r.get::<_, i64>(2)?))
        })
        .expect("query")
        .filter_map(|r| r.ok())
        .collect();

    let mut member_stmt = db
        .prepare(
            "SELECT h.id FROM handle h
             JOIN chat_handle_join chj ON chj.handle_id = h.ROWID
             JOIN chat c ON c.ROWID = chj.chat_id
             WHERE c.guid = ?1",
        )
        .expect("prepare members");

    let mut minted = 0;
    for (guid, name, style) in &chats {
        let members: Vec<String> = member_stmt
            .query_map([guid], |r| r.get::<_, String>(0))
            .expect("members")
            .filter_map(|r| r.ok())
            .collect();
        packets::mint(
            "observation.chat",
            json!({
                "guid": guid,
                "name": name,
                "group": *style == 43,
                "members": members,
            }),
            "ingest.chats",
            vec![],
        );
        minted += 1;
    }
    println!("chat census: {minted} observation.chat packets minted");
}

