}

pub fn rooms_from_log() -> Vec<Room> {
    packets::read_all()
        .into_iter()
        .filter(|p| p.kind == "observation.chat")
        .map(|p| Room {
            guid: p.body["guid"].as_str().unwrap_or("").to_string(),
            name: p.body["name"].as_str().unwrap_or("").to_string(),
            group: p.body["group"].as_bool().unwrap_or(false),
            members: p.body["members"]
                .as_array()
                .map(|a| a.iter().filter_map(|x| x.as_str().map(String::from)).collect())
                .unwrap_or_default(),
        })
        .collect()
}

fn handle_key(id: &str) -> String {
    if id.contains('@') {
        id.to_lowercase()
    } else {
        normalize_phone(id)
    }
}

fn person_keys(p: &Person) -> Vec<String> {
    let mut keys: Vec<String> = p.phones.iter().map(|ph| normalize_phone(ph)).collect();
    keys.extend(p.emails.iter().map(|e| e.to_lowercase()));
    keys.retain(|k| !k.is_empty());
    keys
}

pub fn rooms_for<'a>(rooms: &'a [Room], p: &Person) -> Vec<&'a Room> {
    let keys = person_keys(p);
    rooms
        .iter()
        .filter(|r| r.members.iter().any(|m| keys.contains(&handle_key(m))))
        .collect()
}

/// Humane title: display name if the room has one; otherwise the
/// members' first names resolved through the roster, unknowns as
/// their last four digits.
pub fn room_title(room: &Room, roster: &[Person]) -> String {
    if !room.name.is_empty() {
        return room.name.clone();
    }
    let mut names: Vec<String> = Vec::new();
    for m in &room.members {
        let key = handle_key(m);
        let hit = roster.iter().find(|p| person_keys(p).contains(&key));
        match hit {
            Some(p) => names.push(p.first.clone()),
            None => {
                let d = normalize_phone(m);
                if d.len() >= 4 {
                    names.push(format!("…{}", &d[d.len() - 4..]));
                } else {
                    names.push(m.clone());
                }
            }
        }
    }
    names.sort();
    names.dedup();
    names.join(", ")
}

/// Live stats for a room from chat.db: (rowid, count, last_unix).
pub fn room_stats(guid: &str) -> Option<(i64, i64, i64)> {
    let db = Connection::open_with_flags(chat_db(), OpenFlags::SQLITE_OPEN_READ_ONLY).ok()?;
    db.query_row(
        "SELECT c.ROWID, count(m.ROWID), COALESCE(max(m.date), 0)
         FROM chat c
         LEFT JOIN chat_message_join cmj ON cmj.chat_id = c.ROWID
         LEFT JOIN message m ON m.ROWID = cmj.message_id
         WHERE c.guid = ?1",
        [guid],
        |r| {
            Ok((
                r.get::<_, i64>(0)?,
                r.get::<_, i64>(1)?,
                apple_to_unix(r.get::<_, i64>(2)?),
            ))
        },
    )
    .ok()
}

