//! ServiceRM v2 — the CRM era.
//!
//! The log (packets.jsonl) is the only truth. The UI reads people from
//! the log — never from the sources. Chat previews are a live read-only
//! join against the copied chat.db, keyed by phone digits and emails,
//! until the message ingest ceremony brings them onto the tape.

use eframe::egui;
use servicerm::chats::{self, ChatPreview, Msg};
use servicerm::people::{self, Person};

struct App {
    people: Vec<Person>,
    selected: Option<usize>,
    detail: Option<(usize, Vec<ChatPreview>)>,
    thread: Option<(i64, String, Vec<Msg>)>,
}

impl App {
    fn new() -> Self {
        Self {
            people: people::from_log(),
            selected: None,
            detail: None,
            thread: None,
        }
    }
}

impl eframe::App for App {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        egui::SidePanel::left("toolbar")
            .resizable(false)
            .default_width(110.0)
            .show(ctx, |ui| {
                ui.add_space(12.0);
                let _ = ui.selectable_label(true, "Contacts");
            });

        egui::SidePanel::left("list")
            .resizable(true)
            .default_width(230.0)
            .show(ctx, |ui| {
                ui.add_space(8.0);
                ui.heading(format!("Contacts ({})", self.people.len()));
                ui.add_space(6.0);
                egui::ScrollArea::vertical().show(ui, |ui| {
                    for (i, p) in self.people.iter().enumerate() {
                        let sel = self.selected == Some(i);
                        if ui.selectable_label(sel, p.name()).clicked() {
                            self.selected = Some(i);
                            self.thread = None;
                        }
                    }
                });
            });

        egui::CentralPanel::default().show(ctx, |ui| {
            let Some(i) = self.selected else {
                ui.add_space(24.0);
                ui.weak("select a contact");
                return;
            };
            let p = &self.people[i];
            ui.add_space(8.0);

            // thread view: reading one chat
            let mut go_back = false;
            if let Some((_, title, msgs)) = self.thread.as_ref() {
                ui.horizontal(|ui| {
                    if ui.button("← back").clicked() {
                        go_back = true;
                    }
                    ui.heading(format!("{} — {}", p.name(), title));
                });
                ui.add_space(6.0);
                egui::ScrollArea::vertical()
                    .stick_to_bottom(true)
                    .show(ui, |ui| {
                        let mut last_day = String::new();
                        for m in msgs {
                            let day = chats::fmt_day(m.unix);
                            if day != last_day {
                                ui.add_space(10.0);
                                ui.vertical_centered(|ui| ui.weak(day.clone()));
                                last_day = day;
                            }
                            ui.add_space(4.0);
                            if m.from_me {
                                ui.with_layout(
                                    egui::Layout::top_down(egui::Align::Max),
                                    |ui| {
                                        ui.label(
                                            egui::RichText::new(&m.text)
                                                .color(egui::Color32::from_rgb(88, 166, 255)),
                                        );
                                    },
                                );
                            } else {
                                ui.label(&m.text);
                            }
                        }
                    });
                if go_back {
                    self.thread = None;
                }
                return;
            }

            // contact detail: handles + chat list
            ui.heading(p.name());
            ui.add_space(6.0);
            for ph in &p.phones {
                ui.monospace(ph);
            }
            for e in &p.emails {
                ui.monospace(e);
            }
            ui.add_space(12.0);
            ui.separator();
            ui.add_space(6.0);
            ui.strong("Chats");
            ui.add_space(4.0);

            if self.detail.as_ref().map(|(j, _)| *j) != Some(i) {
                let previews = chats::previews_for(&p.phones, &p.emails);
                self.detail = Some((i, previews));
            }
            let previews = self.detail.as_ref().unwrap().1.clone();
            if previews.is_empty() {
                ui.weak("no chats found for these handles");
                return;
            }
            egui::ScrollArea::vertical().show(ui, |ui| {
                for c in &previews {
                    ui.add_space(6.0);
                    ui.horizontal(|ui| {
                        if ui.button(&c.title).clicked() {
                            let msgs = chats::messages_for(c.rowid, 300);
                            self.thread = Some((c.rowid, c.title.clone(), msgs));
                        }
                        ui.weak(format!(
                            "· {} messages · last {}",
                            c.messages,
                            chats::fmt_day(c.last_unix)
                        ));
                    });
                    let one_line: String = c.last_text.replace('\n', " ");
                    let snippet: String = one_line.chars().take(90).collect();
                    ui.weak(snippet);
                }
            });
        });
    }
}

fn main() -> eframe::Result {
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default().with_inner_size([1080.0, 680.0]),
        ..Default::default()
    };
    eframe::run_native(
        "ServiceRM",
        options,
        Box::new(|_cc| Ok(Box::new(App::new()))),
    )
}

